    const expanded = "==[[Ngala|Ngala (ln)]]==\n===Uitspraak===\n:[[Hulp:IPA|IPA]]: ˈlo˨ba˨\n===Betekenisse===\n#[[praat|Praat]]\n#[[sê|Sê]]\n";
