        const source = "==English==\n# first owner is valid\n==French==\n# [https:// broken\n";
        const job: ExpansionJob = .{ .index_offset = 0, .ordinal = 2, .ns = .{ .id = 0, .kind = .language }, .title = "Partial owners", .source = source };
