test "KBD literal protected headings cannot create owner or noun lexeme" {
    const headings = "==АДЫГЭБЗЭ (КЪЭБЭРДЕЙ-ШЭРДЖЭСЫБЗЭ)==\n===ПСАЛЪЭ ЛЪЭПКЪЫГЪУЭ: ЩЫӀЭЦӀЭ===\n";
