    for (owners, ids, titles, sources, pages, targets, 0..) |owner, code, title, source, whole, target, i| {
        const stored = try EuBorderHeadingTest.read(a, root, title, owner, code);
        const physical_stored = try EuBorderHeadingTest.read(a, physical_root, title, owner, code);
        try std.testing.expectEqualDeep(stored, physical_stored);
        var definitions: usize = 0; var own_action: usize = 0;
        for (stored.entry.sections) |section| for (section.blocks) |block| {
            if (block.kind == .definition) definitions += 1;
            for (block.spans) |span| {
                if (span.kind == .link and std.mem.eql(u8, span.target, target)) own_action += 1;
                for (targets, 0..) |other, j| if (i != j) try std.testing.expect(!std.mem.eql(u8, span.target, other));
            }
        };
        try std.testing.expectEqual(@as(usize, 1), definitions);
        try std.testing.expectEqual(@as(usize, 1), own_action);
        const document = encoder.presentation_document;
        const start = std.mem.indexOf(u8, whole, source) orelse return error.TestUnexpectedResult;
        const observation = try document.observeHeadingAnchorsAlloc(a, title, document.MissingText.untracked(whole), .{}, &namespaces, null, &options, .{}, null);
        const projection = [_]document.HeadingSourceRange{.{ .owner_start = 0, .page_start = start, .len = source.len }};
        var fallbacks: document.Fallbacks = .{};
        const payload = try document.compileClassifiedWithHeadingAnchorsAlloc(a, title, .language, owner, code,
            document.MissingText.untracked(source), null, .{}, &namespaces, null, &options, .{}, &fallbacks, null, &.{}, &observation, &projection, .{ .heading = owner, .code = code });
        const expected = try encoder.presentation_codec.decodeAlloc(a, payload, title, .language, .{ .heading = owner, .code = code });
        try std.testing.expectEqualDeep(expected, stored);
    }
}


const LiVarietyWriterTest = struct {
    const namespaces = "# wikidict-namespace-registry-v1\n# wiki\tfrwiktionary\n# dump-date\t20261001\n# content-language\tfr\n" ++
        "0\t\t\tcase-sensitive\t0\t1\t0\t\tmain\tdictionary_entries\n" ++
        "10\tTemplate\tTemplate\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n" ++
        "14\tCategory\tCategory\tcase-sensitive\t0\t0\t0\t\tcompile_only\tstandard_build_input\n";
    const registry_text = "# content-language\tfr\n# mediawiki\nfr\tFrench\nli\tLimburgs\nnl\tNederlands\n";
    fn marker(a: std.mem.Allocator, code_value: []const u8, label: []const u8, id: []const u8) ![]u8 {
        var hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(@embedFile("reviewed_language_aliases.json"), &hash, .{});
        return std.fmt.allocPrint(a, "# reviewed-alias\t{s}\t{s}\t{s}\t{s}\n", .{ code_value, label, id, std.fmt.bytesToHex(hash, .lower) });
    }
    fn load(io: std.Io, a: std.mem.Allocator, root: []const u8, ns: *const namespace_registry.Registry, reviewed: bool) !language_registry.Registry {
        try std.Io.Dir.cwd().createDirPath(io, root);
        const text = if (reviewed) try std.mem.concat(a, u8, &.{ registry_text,
            try marker(a, "li", "Mofers", "li-mofers-variety-p131871-r958780-v1"),
            try marker(a, "li", "Algemein Gesjreve Limburgs", "li-agl-variety-p101567-r983499-v1"),
            try marker(a, "nl", "Nederlandjs", "li-nederlandjs-exact-p26592-r905227-v1"),
        }) else registry_text;
        try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = try std.fs.path.join(a, &.{ root, "language-registry.tsv" }), .data = text });
        try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = try std.fs.path.join(a, &.{ root, "manifest.jsonl" }), .data = "" });
        return loadLanguageRegistry(io, a, root, ns);
    }
    fn entry(io: std.Io, a: std.mem.Allocator, output: []const u8, owner: []const u8, title: []const u8) !encoder.presentation_types.Entry {
        var filename: [encoder.blob_catalog.language_blob_filename_len]u8 = undefined;
        const path = try std.fs.path.join(a, &.{ output, "languages", encoder.blob_catalog.languageBlobFilename(owner, &filename) });
        const bytes = try std.Io.Dir.cwd().readFileAlloc(io, path, a, .limited(1024 * 1024));
        const blob = try encoder.blob_format.inspect(bytes);
        const metadata = try blob.languageMetadata();
        try std.testing.expectEqualStrings(owner, metadata.heading);
        var index = try blob.buildTrustedIndexAlloc(a); defer index.deinit(a);
        const record = (try index.find(title)).?;
        const stored = try encoder.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, metadata);
        try std.testing.expectEqualStrings(owner, stored.entry.language.?);
        try std.testing.expectEqualStrings(metadata.code, stored.entry.language_code);
        try std.testing.expectEqualSlices(u8, record.payload, try encoder.presentation_codec.encodeAlloc(a, stored));
        return stored.entry;
    }
    fn full(a: std.mem.Allocator, title: []const u8, source: []const u8, ns: *const namespace_registry.Registry) !encoder.presentation_types.Entry {
        const bytes = try encoder.presentation_document.compileReportedWithLinkTrailAlloc(a, title, .language, "Unclassified", "", source, null, .{}, ns, null);
        return (try encoder.presentation_codec.decodeAlloc(a, bytes, title, .language, .{ .code = "", .heading = "Unclassified" })).entry;
    }
};

test "Writer keeps reviewed LI varieties separate while preserving complete authored sections" {
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator(); const io = std.testing.io; const F = LiVarietyWriterTest;
    var ns = try namespace_registry.Registry.init(a, F.namespaces); defer ns.deinit();
    const input = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/li-input", .{tmp.sub_path});
    const output = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/li-output", .{tmp.sub_path});
    var registry = try F.load(io, a, input, &ns, true); defer registry.deinit();
    const codes = languageCodes(&registry, &ns);
    var writer = try encoder.blob_builder.Writer.init(io, a, output); defer writer.deinit();
    writer.language_codes = codes;
    // Authored ich labels/structure and lexical witnesses, with a finite synthetic
    // table and prefix. This is not a captured Worker expansion of the page.
    const source = "[[ich|prefix]]\n==Algemein Gesjreve Limburgs==\n===Persuunlik veurnaamwaord===\n'''ich'''\n* Mofers: [[ich#Mofers|ich]]\n" ++
        "==Mofers==\n===Persuuenlik veurnaamwaord===\n====Lemma====\n'''ich'''\n# verwies nao de ''spraeker'' of de sjriever zelf\n#: ''Ich zing dit leed veur dich.''\n" ++
        "====Grammaer====\n[[miener]]\n====Taofel====\n{|\n! Persoean !! nominatief\n|-\n| ieëste || [[ich]]\n|}\n";
    const dutch = "==Nederlandjs==\n===Persuuenlik veurnaamwaord===\n====Lemma====\n'''ik'''\n# [[ich]]\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "ich", source, source, null);
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "ik", dutch, dutch, null);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 4), stats.language_records);
    try std.testing.expectEqual(@as(usize, 4), stats.language_blobs);
    const prefix = try F.entry(io, a, output, "Unclassified", "ich");
    const agl = try F.entry(io, a, output, "Algemein Gesjreve Limburgs", "ich");
    const mofers = try F.entry(io, a, output, "Mofers", "ich");
    const nl = try F.entry(io, a, output, "Nederlands", "ik");
    try std.testing.expectEqualStrings("", prefix.language_code);
    try std.testing.expectEqualStrings("li", agl.language_code);
    try std.testing.expectEqualStrings("li", mofers.language_code);
    try std.testing.expectEqualStrings("nl", nl.language_code);
    const full = try F.full(a, "ich", source, &ns);
    try std.testing.expectEqual(@as(usize, 8), full.sections.len);
    try std.testing.expectEqualDeep(full.sections[0..1], prefix.sections);
    try std.testing.expectEqualDeep(full.sections[1..3], agl.sections);
    try std.testing.expectEqualDeep(full.sections[3..], mofers.sections);
    try std.testing.expectEqualDeep((try F.full(a, "ik", dutch, &ns)).sections, nl.sections);
    try std.testing.expectEqual(@as(usize, 0), prefix.organization.lexemes.len);
    try std.testing.expectEqual(@as(usize, 1), agl.organization.lexemes.len);
    try std.testing.expectEqual(@as(usize, 0), agl.organization.lexemes[0].definitions.len);
    const lexical = mofers.organization.lexemes[0];
    try std.testing.expectEqual(@as(usize, 1), mofers.organization.lexemes.len);
    try std.testing.expectEqualStrings("Mofers", lexical.language);
    try std.testing.expectEqualStrings("Pronoun", lexical.kind);
    try std.testing.expectEqual(@as(usize, 2), lexical.section);
    try std.testing.expectEqual(@as(usize, 1), lexical.definitions.len);
    try std.testing.expectEqual(@as(usize, 1), lexical.definitions[0].block);
    try std.testing.expectEqualSlices(usize, &.{2}, lexical.definitions[0].examples);
    try std.testing.expect(lexical.definitions[0].form == null);
    try std.testing.expectEqualSlices(usize, &.{3, 4}, lexical.related_sections);
    try std.testing.expectEqual(@as(usize, 1), nl.organization.lexemes.len);
    try std.testing.expectEqual(@as(usize, 1), nl.organization.lexemes[0].definitions.len);
}

test "Writer declines absent reviewed variety proof and raw rendered variety disagreement" {
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator(); const io = std.testing.io; const F = LiVarietyWriterTest;
    var ns = try namespace_registry.Registry.init(a, F.namespaces); defer ns.deinit();
    const input = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/negative-input", .{tmp.sub_path});
    const output = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/negative-output", .{tmp.sub_path});
    var registry = try F.load(io, a, input, &ns, true); defer registry.deinit();
    var absent = try F.load(io, a, try std.fs.path.join(a, &.{ input, "absent" }), &ns, false); defer absent.deinit();
    const codes = languageCodes(&registry, &ns);
    var writer = try encoder.blob_builder.Writer.init(io, a, output); defer writer.deinit();
    writer.language_codes = codes;
    const body = "\n===Persuuenlik veurnaamwaord===\n====Lemma====\n# [[ich]]\n";
    const mismatch = "==Mofers==" ++ body;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "mismatch", mismatch, "==Algemein Gesjreve Limburgs==" ++ body, null);
    const protected = "<nowiki>==Mofers==\n===Persuuenlik veurnaamwaord===\n====Lemma====\n# literal</nowiki>\n[[retained]]\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "protected", protected, protected, null);
    writer.language_codes = languageCodes(&absent, &ns);
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "missing-proof", mismatch, mismatch, null);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 3), stats.language_records);
    try std.testing.expectEqual(@as(usize, 1), stats.language_blobs);
    for ([_]struct { title: []const u8, source: []const u8 }{
        .{ .title = "mismatch", .source = mismatch }, .{ .title = "protected", .source = protected }, .{ .title = "missing-proof", .source = mismatch },
    }) |case| {
        const actual = try F.entry(io, a, output, "Unclassified", case.title);
        try std.testing.expectEqualStrings("", actual.language_code);
        try std.testing.expectEqualDeep((try F.full(a, case.title, case.source, &ns)).sections, actual.sections);
        if (std.mem.eql(u8, case.title, "protected")) try std.testing.expectEqual(@as(usize, 0), actual.organization.lexemes.len);
    }
}

const NativeWriterFixtureCheck = struct {
    fn expect(ok: bool, comptime location: std.lang.SourceLocation) !void {
        if (!ok) std.debug.print("Writer oracle {s}:{d} ({s})\n", .{ location.file, location.line, location.fn_name });
        try std.testing.expect(ok);
    }

    fn missing(comptime location: std.lang.SourceLocation) error{TestUnexpectedResult} {
        std.debug.print("Writer required value absent {s}:{d} ({s})\n", .{ location.file, location.line, location.fn_name });
        return error.TestUnexpectedResult;
    }
};

const MnwDefaultlessUrlSavedTest = struct {
    const title = "ဗီုပြၚ်သိုၚ်တၟိ:အိန်ဒဝ်-ယူရဝ်ပဳယာန်-အခိုက်ကၞာ/kewk-";
    const raw = @embedFile("testdata/mnw-kewk/mnw-kewk.raw.wikitext");
    const expanded = @embedFile("testdata/mnw-kewk/mnw-kewk.expanded.wikitext");
    const display_title = @embedFile("testdata/mnw-kewk/mnw-kewk.display-title.wikitext");
    const raw_url = "https://archive.org/details/etymological-dictionary-of-the-slavic-inherited-lexicon/page/{{{1}}}/mode/2up?view=theater";
    const encoded_url = "https://archive.org/details/etymological-dictionary-of-the-slavic-inherited-lexicon/page/%7B%7B%7B1%7D%7D%7D/mode/2up?view=theater";
    const archive_targets = [_][]const u8{
        "https://archive.org/details/etymological-dictionary-of-proto-germanic/page/215?view=theater",
        "https://archive.org/details/ESSJa/ESSJa_4/page/n125/mode/1up?view=theater",
        "https://archive.org/details/ESSJa/ESSJa_4/page/n130/mode/1up?view=theater",
        "https://archive.org/details/etymological-dictionary-of-the-baltic-inherited-lexicon/page/232?view=theater",
        raw_url,
    };
    const archive_labels = [_][]const u8{ "page 215", "*čučati", "*čuka", "page 232", "[1]" };
    const Report = struct { namespace: u32, title: []const u8, reasons: []const []const u8 };

    fn payload(a: std.mem.Allocator, root: []const u8) ![]const u8 {
        const path = try std.fs.path.join(a, &.{ root, encoder.blob_catalog.featureBlobFilename(.supplemental).? });
        const bytes = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, path, a, .limited(4 * 1024 * 1024));
        const blob = try encoder.blob_format.inspect(bytes);
        try NativeWriterFixtureCheck.expect(blob.kind == .supplemental, @src());
        var index = try blob.buildTrustedIndexAlloc(a);
        defer index.deinit(a);
        const record = (try index.find(title)) orelse return NativeWriterFixtureCheck.missing(@src());
        try std.testing.expectEqualStrings(title, record.title);
        return a.dupe(u8, record.payload);
    }

    fn report(a: std.mem.Allocator, root: []const u8) !std.json.Parsed(Report) {
        const path = try std.fs.path.join(a, &.{ root, "fallback-pages.jsonl" });
        const bytes = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, path, a, .limited(64 * 1024));
        return std.json.parseFromSlice(Report, a, bytes, .{});
    }

    fn hasReason(report_value: Report, expected: []const u8) bool {
        for (report_value.reasons) |reason| if (std.mem.eql(u8, reason, expected)) return true;
        return false;
    }

    const Scan = struct {
        visible: std.ArrayList(u8) = .empty,
        archive_labels: [5]std.ArrayList(u8) = @splat(.empty),
        definitions: usize = 0,
        tables: usize = 0,
        headword_bold: bool = false,
        citation_italic: bool = false,
        parameter_action_spans: usize = 0,

        fn headwordSpan(span: encoder.presentation_types.Span) bool {
            return span.kind == .text and span.image == null and span.bold and
                std.mem.eql(u8, span.language, "ine-pro") and (span.text.len != 0 or span.trail.len != 0);
        }

        fn hasHeadwordRun(values: []const encoder.presentation_types.Span) bool {
            const expected = "*kewk-";
            for (values, 0..) |first, start| {
                if (first.text.len == 0 or first.text[0] != expected[0] or
                    (start != 0 and headwordSpan(values[start - 1]))) continue;
                var matched: usize = 0;
                candidate: for (values[start..], start..) |span, index| {
                    if (!headwordSpan(span)) break :candidate;
                    // Preserve every character and style across the entity split;
                    // neither skip an interruption nor join separate spans arrays.
                    for ([_][]const u8{ span.text, span.trail }) |part| {
                        if (part.len > expected.len - matched or
                            !std.mem.eql(u8, part, expected[matched .. matched + part.len])) break :candidate;
                        matched += part.len;
                    }
                    if (matched == expected.len) {
                        if (index + 1 == values.len or !headwordSpan(values[index + 1])) return true;
                        break :candidate;
                    }
                }
            }
            return false;
        }

        fn spans(self: *@This(), a: std.mem.Allocator, values: []const encoder.presentation_types.Span) !void {
            self.headword_bold = self.headword_bold or hasHeadwordRun(values);
            for (values) |span| {
                try self.visible.appendSlice(a, span.text);
                try self.visible.appendSlice(a, span.trail);
                if (std.mem.eql(u8, span.text, "Etymological Dictionary of the Slavic Inherited Lexicon") and span.italic) self.citation_italic = true;
                if (span.kind == .link or span.kind == .external_link) {
                    const literal_path = span.kind == .external_link and std.mem.eql(u8, span.target, MnwDefaultlessUrlSavedTest.raw_url);
                    if (!literal_path) {
                        try NativeWriterFixtureCheck.expect(std.mem.indexOf(u8, span.target, "{{") == null, @src());
                        try NativeWriterFixtureCheck.expect(std.mem.indexOf(u8, span.target, "}}") == null, @src());
                    }
                    try NativeWriterFixtureCheck.expect(!std.mem.eql(u8, span.target, "https://archive.org/details/etymological-dictionary-of-the-slavic-inherited-lexicon/page/256/mode/2up?view=theater"), @src());
                }
                if (span.kind != .external_link) continue;
                for (MnwDefaultlessUrlSavedTest.archive_targets, 0..) |target, i| if (std.mem.eql(u8, target, span.target)) {
                    try self.archive_labels[i].appendSlice(a, span.text);
                    if (i == 4) {
                        try NativeWriterFixtureCheck.expect(span.superscript, @src());
                        self.parameter_action_spans += 1;
                    }
                };
            }
        }

        fn table(self: *@This(), a: std.mem.Allocator, value: encoder.presentation_types.Table) anyerror!void {
            self.tables += 1;
            try self.spans(a, value.caption);
            for (value.rows) |row| for (row.cells) |cell| {
                if (cell.blocks) |cell_blocks| {
                    try self.blocks(a, cell_blocks);
                } else {
                    try self.spans(a, cell.spans);
                    if (cell.nested_table) |nested| try self.table(a, nested);
                }
            };
        }

        fn blocks(self: *@This(), a: std.mem.Allocator, values: []const encoder.presentation_types.Block) anyerror!void {
            const meanings = [_][]const u8{ "သကဵုသမၠုၚ်ပ္တိန်။", "သၠုၚ်။" };
            for (values) |block| {
                if (block.kind == .definition) {
                    try NativeWriterFixtureCheck.expect(self.definitions < meanings.len, @src());
                    var text: std.ArrayList(u8) = .empty;
                    for (block.spans) |span| {
                        try text.appendSlice(a, span.text);
                        try text.appendSlice(a, span.trail);
                    }
                    try std.testing.expectEqualStrings(meanings[self.definitions], text.items);
                    try std.testing.expectEqualStrings("#", block.list_path);
                    try std.testing.expectEqualStrings(if (self.definitions == 0) "1" else "2", block.number);
                    self.definitions += 1;
                }
                try self.spans(a, block.spans);
                if (block.table) |value| try self.table(a, value);
            }
        }
    };
    fn restoreLiteralSpans(values: []const encoder.presentation_types.Span) usize {
        var count: usize = 0;
        for (@constCast(values)) |*span| if (span.kind == .external_link and std.mem.eql(u8, span.target, encoded_url)) {
            span.target = raw_url;
            count += 1;
        };
        return count;
    }
    fn restoreLiteralBlocks(values: []const encoder.presentation_types.Block) usize {
        var count: usize = 0;
        for (values) |block| {
            count += restoreLiteralSpans(block.spans);
            if (block.table) |table| count += restoreLiteralTable(table);
        }
        return count;
    }
    fn restoreLiteralTable(table: encoder.presentation_types.Table) usize {
        var count = restoreLiteralSpans(table.caption);
        for (table.rows) |row| for (row.cells) |cell| {
            count += restoreLiteralSpans(cell.spans);
            if (cell.blocks) |cell_blocks| count += restoreLiteralBlocks(cell_blocks);
            if (cell.nested_table) |nested| count += restoreLiteralTable(nested);
        };
        return count;
    }
    fn restoreLiteralTarget(entry: encoder.presentation_types.Entry) usize {
        var count = restoreLiteralSpans(entry.display_title) + restoreLiteralSpans(entry.preamble_spans);
        for (entry.sections) |section| count += restoreLiteralBlocks(section.blocks);
        for (entry.references) |reference| {
            count += restoreLiteralSpans(reference.spans);
            if (reference.blocks) |reference_blocks| count += restoreLiteralBlocks(reference_blocks);
        }
        return count;
    }
};

test "normal Writer retained Mon supplemental page preserves complete body and numbered literal parameter URL" {
    const F = MnwDefaultlessUrlSavedTest;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
