    try std.testing.expectEqualStrings("mnwwiktionary", namespaces.wiki);
    try std.testing.expectEqualStrings("20261001", namespaces.dump_date);
    try std.testing.expectEqualStrings("mnw", namespaces.content_language);
    const main_namespace = namespaces.byId(0) orelse return error.TestUnexpectedResult;
    try std.testing.expect(main_namespace.role == .main);
    const behavior_source = @embedFile("testdata/mnw-kewk/mnw-behavior-switches.tsv");
    var behavior = try namespace_registry.behavior_switches.Registry.init(a, behavior_source, namespaces.wiki, namespaces.dump_date, namespaces.content_language, namespaces.source_sha256);
    defer behavior.deinit();
    var behavior_sha: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(behavior_source, &behavior_sha, .{});
    var images = try namespace_registry.image_options.Registry.init(a, @embedFile("testdata/mnw-kewk/mnw-image-options.tsv"), namespaces.wiki, namespaces.dump_date, namespaces.content_language, namespaces.source_sha256, behavior_sha);
    defer images.deinit();
    var styles = try encoder.table_style_profile.parseAlloc(a, @embedFile("testdata/mnw-kewk/mnw-common.css"));
    defer styles.deinit();
    const registry_root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/mnw-ost-metadata", .{tmp.sub_path});
    try std.Io.Dir.cwd().createDirPath(io, try std.fs.path.join(a, &.{ registry_root, "modules" }));
    const inputs = [_][2][]const u8{
        .{ "language-registry.tsv", @embedFile("testdata/mnw-ost/mnw-language-registry.tsv") },
        .{ "language-names.tsv", @embedFile("testdata/mnw-ost/mnw-language-names.tsv") },
        .{ "manifest.jsonl", @embedFile("testdata/mnw-ost/mnw-canonical-names-722.manifest.jsonl") },
        .{ "modules/722.lua", @embedFile("testdata/mnw-ost/mnw-canonical-names-722.lua") },
    };
    for (inputs) |input| try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = try std.fs.path.join(a, &.{ registry_root, input[0] }), .data = input[1] });
    // The ordinary loader authenticates the original manifest row before addLua.
    // No hand-installed alias or direct addLua call stands in for that path.
    var registry = try loadLanguageRegistry(io, a, registry_root, &namespaces);
    defer registry.deinit();
    var codes = languageCodes(&registry, &namespaces);
    codes.behavior_switches = &behavior;
    codes.image_options = &images;
    codes.table_styles = &styles;
    var figure_inputs198 = try RetainedFigureInputs198.init("mnw", io, a, try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/normal-figure-inputs-mnw", .{tmp.sub_path}), &namespaces);
    defer figure_inputs198.sizing.deinit();
    codes.figure_sizing = figure_inputs198.authority();
    var typed_figure_files198: std.StringHashMapUnmanaged(void) = .empty;

    const swedish = codes.resolveStrong(F.unresolved_heading) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("sv", swedish.code);
    try std.testing.expectEqualStrings(F.unresolved_heading, swedish.heading);
    // Strong canonical names and trusted snapshot aliases are separate API sets.
    // addStrongCanonical replaces headings[sv], retaining the old trusted alias.
    try std.testing.expect(codes.resolveTrusted(F.unresolved_heading) == null);
    const trusted_old = codes.resolveTrusted("ဆွီဒင်") orelse return error.TestUnexpectedResult;
    const source_trusted_old = registry.resolveSourceTrusted("ဆွီဒင်") orelse return error.TestUnexpectedResult;
    for ([_]encoder.blob_builder.ResolvedLanguage{
        trusted_old,
        .{ .code = source_trusted_old.code, .heading = source_trusted_old.heading },
    }) |resolved| {
        try std.testing.expectEqualStrings("sv", resolved.code);
        try std.testing.expectEqualStrings(F.unresolved_heading, resolved.heading);
    }

    var saved: [2]F.Saved = undefined;
    var reports: [2][]const u8 = undefined;
    var manifests: [2][]const u8 = undefined;
    var stats: [2]encoder.blob_builder.BuildStats = undefined;
    for ([_][]const u8{ F.expanded, control }, 0..) |source, arm| {
        const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/mnw-ost-normal-{d}", .{ tmp.sub_path, arm });
        var writer = try encoder.blob_builder.Writer.init(io, a, root);
        defer writer.deinit();
        writer.language_codes = codes;
        try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, F.title, source, F.raw, null);
        stats[arm] = try writer.finish(codes);
        try std.testing.expectEqual(@as(usize, 1), stats[arm].language_records);
        try std.testing.expectEqual(@as(usize, 1), stats[arm].language_blobs);
        try std.testing.expectEqual(@as(usize, 0), stats[arm].supplemental_records);
        saved[arm] = try G.saved(a, root);
        reports[arm] = try F.reportBytes(a, root);
        manifests[arm] = try std.Io.Dir.cwd().readFileAlloc(io, try std.fs.path.join(a, &.{ root, encoder.blob_catalog.manifest_filename }), a, .limited(64 * 1024));
        var entries = try encoder.blob_catalog.Iterator.init(manifests[arm]);
        const entry = (try entries.next()) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings(F.unresolved_heading, entry.heading);
        try std.testing.expect((try entries.next()) == null);
        try std.testing.expectEqual(@as(usize, if (std.mem.trim(u8, reports[arm], " \t\r\n").len == 0) 0 else 1), stats[arm].fallback_pages);
    }
    // Complete disambig-see-also hatnotes become shared_prefix in the Writer.
    // The sole sv group owns that context; no arbitrary unclassified prefix row.
    try std.testing.expectEqualSlices(u8, manifests[1], manifests[0]);
    try std.testing.expectEqualDeep(stats[1], stats[0]);
    try std.testing.expectEqualSlices(u8, reports[1], reports[0]);
    try std.testing.expectEqualSlices(u8, saved[1].payload, saved[0].payload);
    try std.testing.expectEqualDeep(saved[1].metadata, saved[0].metadata);
    const stored = try encoder.presentation_codec.decodeAlloc(a, saved[0].payload, F.title, .language, saved[0].metadata);
    const expected = try encoder.presentation_codec.decodeAlloc(a, saved[1].payload, F.title, .language, saved[1].metadata);
    errdefer savedOwnerStored295(a, "Mon-loader", stored);
    try std.testing.expectEqualDeep(expected, stored);
    try std.testing.expectEqualSlices(u8, saved[0].payload, try encoder.presentation_codec.encodeAlloc(a, stored));
    try std.testing.expectEqualSlices(u8, saved[1].payload, try encoder.presentation_codec.encodeAlloc(a, expected));
    try std.testing.expectEqualStrings(F.title, stored.entry.title);
    try std.testing.expect(stored.entry.kind == .language);
    try std.testing.expectEqualStrings(F.unresolved_heading, stored.entry.language orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings("sv", stored.entry.language_code);
    try std.testing.expectEqual(@as(usize, 0), stored.entry.references.len);

    errdefer Native154BodyWitness.emit(a, "MON154-normal-loader", stored.entry) catch |secondary| std.debug.print("NATIVE154_BODY_WITNESS secondary error={s}\n", .{@errorName(secondary)});
    var scan: F.Scan = .{};
    try RetainedFigureInputs198.collectEntryFiles(a, stored.entry, &typed_figure_files198);
    errdefer std.debug.print("MON ost normal-loader final definitions={d} tables={d} audio_rows={d} image_owners={any} caption_offsets={any} headword={any} etymology={any} file_link={any}\n", .{ scan.definitions, scan.tables, scan.audio_rows, scan.image_owners, scan.caption_offsets, scan.headword_bold, scan.etymology_italic, scan.explicit_audio_link });
    try scan.spans(a, stored.entry.preamble_spans);
    const headings = [_][]const u8{ F.unresolved_heading, "ဗွဟ်ရမ္သာၚ်", "နိရုတ်", "နာမ်", "ပွံၚ်နဲတၞဟ်", "ကြိယာဝိသေသန" };
    var heading_counts: [headings.len]usize = @splat(0);
    for (stored.entry.sections) |section| {
        for (headings, 0..) |heading, heading_index| if (std.mem.eql(u8, heading, section.title)) {
            heading_counts[heading_index] += 1;
            try std.testing.expectEqual(@as(u8, if (heading_index == 0) 2 else 3), section.level);
        };
        try scan.blocks(a, section.blocks);
    }
    // Builder's initial owner-labelled section contains the shared hatnote.
    // It has no authored heading anchor. The following same-title section is
    // the sole actual L2 from the source, with its own stable anchor.
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, F.raw, "==သွဳဒေန်=="));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, F.expanded, "==သွဳဒေန်=="));
    try std.testing.expectEqualSlices(usize, &.{ 2, 1, 1, 2, 1, 1 }, &heading_counts);
    try std.testing.expect(stored.entry.sections.len >= 2);
    const prefix_section = stored.entry.sections[0];
    const authored_section = stored.entry.sections[1];
    try std.testing.expectEqualStrings(F.unresolved_heading, prefix_section.title);
    try std.testing.expectEqual(@as(u8, 2), prefix_section.level);
    try std.testing.expectEqualStrings("", prefix_section.anchor);
    try std.testing.expectEqualStrings("", prefix_section.anchor_fallback);
    try std.testing.expectEqualStrings(F.unresolved_heading, authored_section.title);
    try std.testing.expectEqual(@as(u8, 2), authored_section.level);
    try std.testing.expect(authored_section.anchor.len != 0);
    var prefix_only: G.Prefix = .{};
    var prefix_text: std.ArrayList(u8) = .empty;
    for (prefix_section.blocks) |block| {
        try std.testing.expect(block.table == null and block.kind != .heading and block.kind != .definition);
        for (block.spans) |span| {
            try prefix_text.appendSlice(a, span.text);
            try prefix_text.appendSlice(a, span.trail);
        }
    }
    try prefix_only.blocks(a, prefix_section.blocks);
    try std.testing.expectEqualStrings(G.prefix_visible, prefix_text.items);
    try std.testing.expect(prefix_only.italic_intro);
    for (G.prefix_targets, prefix_only.labels) |target, label| try std.testing.expectEqualStrings(target, label.items);
    try std.testing.expectEqual(@as(usize, 3), scan.definitions);
    // Inline audio stays a typed list row; the compass is the one block grid.
    try std.testing.expectEqual(@as(usize, 1), scan.audio_rows);
    try std.testing.expectEqual(@as(usize, 1), scan.tables);
    try std.testing.expect(scan.headword_bold and scan.etymology_italic and scan.explicit_audio_link);
    for (F.typed_caption_text, scan.caption_offsets) |caption, length| try std.testing.expectEqual(caption.len, length);
    try std.testing.expect(std.mem.indexOf(u8, scan.visible.items, "[ʊst]") != null);
    try std.testing.expect(std.mem.indexOf(u8, scan.visible.items, "kompasspunkt") != null);
    try std.testing.expectEqual(@as(usize, 1), scan.image_owners[0]);
    try std.testing.expectEqual(@as(usize, 1), scan.logo_blocks);
    try scan.interproject_owners.finish();

    try std.testing.expectEqual(F.files.len, stored.entry.media.len);
    var media_seen: [F.files.len]usize = @splat(0);
    errdefer std.debug.print("MON ost normal-loader media_seen={any}\n", .{media_seen});
    for (stored.entry.media) |media| {
        var known = false;
        for (F.files, 0..) |file, file_index| if (std.mem.eql(u8, file, media.file)) {
            known = true;
            media_seen[file_index] += 1;
            if (file_index == 5) try std.testing.expect(media.kind == .audio) else try std.testing.expect(media.kind == .image);
            if (file_index == 3 or file_index == 4) try std.testing.expectEqualStrings(F.caption_text[file_index - 3], media.caption);
        };
        try std.testing.expect(known);
    }
    for (media_seen) |count| try std.testing.expectEqual(@as(usize, 1), count);
    var prefix: G.Prefix = .{};
    try prefix.spans(a, stored.entry.preamble_spans);
    for (stored.entry.sections) |section| try prefix.blocks(a, section.blocks);
    for (G.prefix_targets, prefix.labels) |target, label| try std.testing.expectEqualStrings(target, label.items);
    // Independent plain prefix fidelity, in addition to every typed action and
    // whole-record parity. No source reconstruction is used by the reader.
    try std.testing.expect(std.mem.indexOf(u8, scan.visible.items, G.prefix_visible) != null);
    try std.testing.expect(prefix.italic_intro);
    if (std.mem.trim(u8, reports[0], " \t\r\n").len != 0) {
        const parsed_report = try std.json.parseFromSlice(F.Report, a, reports[0], .{});
        defer parsed_report.deinit();
        try std.testing.expectEqual(@as(u32, 0), parsed_report.value.namespace);
        try std.testing.expectEqualStrings(F.title, parsed_report.value.title);
        for (parsed_report.value.reasons) |reason| {
            try std.testing.expect(!std.mem.eql(u8, reason, "unresolved_language_heading"));
            try std.testing.expect(!std.mem.eql(u8, reason, "missing_language_heading"));
        }
    }
    try RetainedFigureInputs198.expectFiles("mnw", typed_figure_files198);
}

test "normal Writer retained SV bard preserves complete page paint actions owner and codec" {
    const F = struct {
        const title = "bård";
        const raw = @embedFile("testdata/sv-bard/bard.raw.wikitext");
        const source = @embedFile("testdata/sv-bard/bard.expanded.wikitext");
        const url = "https://www.saob.se/artikel/?unik=B_4693-0057.bZw9&pz=3";
        const rejected = "[" ++ url ++ "> bård]";
        const spaced = "[" ++ url ++ " > bård]";
        const translations = [_][]const u8{
            "https://da.wiktionary.org/wiki/bort", "https://en.wiktionary.org/wiki/border",
            "https://fr.wiktionary.org/wiki/bord", "https://fr.wiktionary.org/wiki/bordure",
            "https://de.wiktionary.org/wiki/Borte", "https://de.wiktionary.org/wiki/Bord%C3%BCre",
        };
        const media_files = [_][]const u8{
            "Stridsvagn m21-29 Axvall 31.05.00.jpg", "4032861226 wallpaper.jpg",
            "Hor barileto avgraensare i 222 18 px trans.png",
        };
        fn hash(bytes: []const u8, expected: []const u8) !void {
            var digest: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(bytes, &digest, .{});
            const hex = std.fmt.bytesToHex(digest, .lower);
            try std.testing.expectEqualStrings(expected, &hex);
        }
        fn dumpStored(a: std.mem.Allocator, side: []const u8, ordinal: usize, value: encoder.presentation_types.Entry, remaining: *usize) void {
            const json = std.json.Stringify.valueAlloc(a, encoder.presentation_types.Stored{ .entry = value }, .{}) catch |err| {
                std.debug.print("SV failure Stored side={s} ordinal={d} serialization_error={s}\n", .{ side, ordinal, @errorName(err) });
                return;
            };
            defer a.free(json);
            const emitted = @min(json.len, remaining.*);
            std.debug.print("SV failure Stored side={s} ordinal={d} total_bytes={d} emitted_bytes={d} complete={}\n{s}\n", .{ side, ordinal, json.len, emitted, emitted == json.len, json[0..emitted] });
            remaining.* -= emitted;
        }
        const Observed = struct {
            sizing: *const figure_sizing.Registry,
            const options = [_][]const u8{
                "miniatyr|stående|&#32;kamouflagemönster med svart '''bård''' (kant, rand) mellan färgfälten",
                "miniatyr|stående|&#32;'''bård''' (tapetbård)",
            };
            // Callback requests arrive after the existing wiki-quote pass.
            // Bind only these two exact stage representations to the original options.
            const request_options = [_][]const u8{
                "miniatyr|stående|&#32;kamouflagemönster med svart <b>bård</b> (kant, rand) mellan färgfälten",
                "miniatyr|stående|&#32;<b>bård</b> (tapetbård)",
            };
            fn init(a: std.mem.Allocator, page_title: []const u8, page_source: []const u8, namespaces: *const namespace_registry.Registry, site: FigureSite, sizing: *const figure_sizing.Registry) !@This() {
                if (!std.mem.eql(u8, page_title, title)) return error.InvalidFigureSizingSource;
                try hash(source, "c28700e0c37927302b414993be50703adac7d6aa83bbbff3f6cc72b895c03fba");
                // The only noncaptured input is the original test's exact
                // citation-separator control. Its two image occurrences do not change.
                const control_source = try std.mem.replaceOwned(u8, a, source, rejected, spaced);
                defer a.free(control_source);
                if (!std.mem.eql(u8, page_source, source) and !std.mem.eql(u8, page_source, control_source)) return error.InvalidFigureSizingSource;
                try hash(@embedFile("testdata/sv-bard/sv-namespace-registry.tsv"), "79741d98c96355c5fdb601861686b5fb5e6265a02d320b66f7dcc3027cea1992");
                var namespace_digest: [32]u8 = undefined;
                std.crypto.hash.sha2.Sha256.hash(@embedFile("testdata/sv-bard/sv-namespace-registry.tsv"), &namespace_digest, .{});
                if (!std.mem.eql(u8, &namespaces.source_sha256, &namespace_digest) or !std.mem.eql(u8, &site.source_context.namespace_sha256, &namespace_digest)) return error.InvalidFigureSizingSource;
                if (!std.mem.eql(u8, site.core_revision, "0470f6c99a6456a366635bf25a517a1f951de6f5") or site.source_context.defaults.default_thumbnail_width != 250) return error.InvalidFigureSizingSource;
                try hash(@embedFile("testdata/figure-inputs198/sv/figure-siteinfo.raw.json"), "249a3ff9c2b95d09b1353a1ed78e27c13ea9af2064d562cf3b9ee35c7c9b78f7");
                var site_digest: [32]u8 = undefined;
                std.crypto.hash.sha2.Sha256.hash(@embedFile("testdata/figure-inputs198/sv/figure-siteinfo.raw.json"), &site_digest, .{});
                if (!std.mem.eql(u8, &site.source_sha256, &site_digest)) return error.InvalidFigureSizingSource;
                try hash(@embedFile("testdata/figure-inputs198/sv/occurrence-sizing-witness01.json"), "48ac87b15f574546c47cda5a86c8e0b47eec3675f86e3a148b2b81c99337a0bb");
                if (sizing.records.len != 2) return error.InvalidFigureSizingSource;
                const original_widths = [_]u32{1798, 1500};
                const original_heights = [_]u32{1199, 1000};
                const sha1s = [_][]const u8{"7610bd9150f1f3e78eb9fdd724fe8f84fe47f612", "d46f6bf275547ab90b272c3f067997faa43c0067"};
                const timestamps = [_][]const u8{"2013-03-25T08:58:50Z", "2012-10-24T19:44:39Z"};
                for (media_files[0..2], 0..) |file, index| {
                    const occurrence = try std.fmt.allocPrint(a, "[[Fil:{s}|{s}]]", .{file, options[index]});
                    defer a.free(occurrence);
                    if (std.mem.count(u8, page_source, occurrence) != 1) return error.InvalidFigureSizingSource;
                    if (std.mem.count(u8, options[index], "'''bård'''") != 1) return error.InvalidFigureSizingSource;
                    const normalized_request = try std.mem.replaceOwned(u8, a, options[index], "'''bård'''", "<b>bård</b>");
                    defer a.free(normalized_request);
                    if (!std.mem.eql(u8, normalized_request, request_options[index])) return error.InvalidFigureSizingSource;
                    var found = false;
                    for (sizing.records) |record| {
                        const canonical = try std.mem.concat(a, u8, &.{"Fil:", file});
                        defer a.free(canonical);
                        if (!std.mem.eql(u8, record.canonical_file, canonical)) continue;
                        if (record.format != .thumbnail or record.width_px != 190 or record.height_px != null or record.sizing != .requested_fit or record.original_width != original_widths[index] or record.original_height != original_heights[index] or !std.mem.eql(u8, record.file_sha1, sha1s[index]) or !std.mem.eql(u8, record.file_timestamp, timestamps[index])) return error.InvalidFigureSizingSource;
                        if (found) return error.InvalidFigureSizingSource;
                        found = true;
                    }
                    if (!found) return error.InvalidFigureSizingSource;
                }
                return .{ .sizing = sizing };
            }
            fn width(raw_ctx: ?*const anyopaque, a: std.mem.Allocator, file: []const u8, format_value: encoder.presentation_types.FigureFormat, raw_options: []const u8, base_width: u32) std.mem.Allocator.Error!?u32 {
                _ = a;
                const self: *const @This() = @ptrCast(@alignCast(raw_ctx orelse return null));
                _ = self;
                if (format_value != .thumbnail or base_width != 250) return null;
                for (media_files[0..2], 0..) |expected, index| {
                    if (std.mem.eql(u8, file, expected) and std.mem.eql(u8, raw_options, request_options[index])) return 190;
                }
                return null;
            }
            fn resolve(raw_ctx: ?*const anyopaque, a: std.mem.Allocator, file: []const u8, format_value: encoder.presentation_types.FigureFormat, width_px: ?u32, height_px: ?u32) std.mem.Allocator.Error!?encoder.presentation_types.FigureSizingPolicy {
                const self: *const @This() = @ptrCast(@alignCast(raw_ctx orelse return null));
                return figure_sizing.Registry.resolve(self.sizing, a, file, format_value, width_px, height_px);
            }
        };
        const Scan = struct {
            visible: std.ArrayList(u8) = .empty,
            figures: usize = 0,
            definitions: usize = 0,
            tables: usize = 0,
            citations: usize = 0,
            bold_headword: bool = false,
            italic_label: bool = false,
            translations_seen: [translations.len]bool = @splat(false),
            media_seen: [media_files.len]bool = @splat(false),
            fn media(self: *@This(), file: []const u8) void {
                for (media_files, 0..) |expected, i| if (std.mem.eql(u8, expected, file)) { self.media_seen[i] = true; };
            }
            fn spans(self: *@This(), a: std.mem.Allocator, values: []const encoder.presentation_types.Span) !void {
                for (values) |span| {
                    var predicate: []const u8 = "append visible span";
                    errdefer std.debug.print("SV failure span predicate={s} kind={s} text={s} target={s} bold={} italic={} superscript={}\n", .{ predicate, @tagName(span.kind), span.text[0..@min(span.text.len, 256)], span.target[0..@min(span.target.len, 512)], span.bold, span.italic, span.superscript });
                    try self.visible.appendSlice(a, span.text);
                    try self.visible.appendSlice(a, span.trail);
                    if (span.image) |image| self.media(image.file);
                    if (std.mem.eql(u8, span.text, title) and span.bold) self.bold_headword = true;
                    if (std.mem.indexOf(u8, span.text, "(allmänt)") != null and span.italic) self.italic_label = true;
                    if (span.kind == .external_link) {
                        if (std.mem.eql(u8, span.target, url)) {
                            self.citations += 1;
                            predicate = "citation exact label";
                            try std.testing.expectEqualStrings("> bård", span.text);
                            predicate = "citation bold and italic absent";
                            try std.testing.expect(!span.bold and !span.italic);
                        }
                        for (translations, 0..) |expected, i| if (std.mem.eql(u8, span.target, expected)) {
                            predicate = "translation action superscript";
                            try std.testing.expect(span.superscript);
                            self.translations_seen[i] = true;
                        };
                    }
                }
            }
            fn table(self: *@This(), a: std.mem.Allocator, value: encoder.presentation_types.Table) anyerror!void {
                var predicate: []const u8 = "table row count";
                errdefer std.debug.print("SV failure table predicate={s} rows={d} style_present={} background={s}\n", .{ predicate, value.rows.len, value.style != null, if (value.style) |observed_style| observed_style.background orelse "<null>" else "<no style>" });
                self.tables += 1;
                try std.testing.expectEqual(@as(usize, 4), value.rows.len);
                predicate = "first table row cell count";
                try std.testing.expectEqual(@as(usize, 3), value.rows[0].cells.len);
                predicate = "first header colspan";
                try std.testing.expectEqual(@as(u16, 2), value.rows[0].cells[1].colspan);
                predicate = "second header colspan";
                try std.testing.expectEqual(@as(u16, 2), value.rows[0].cells[2].colspan);
                predicate = "table style present";
                const style = value.style orelse return error.TestUnexpectedResult;
                predicate = "table background present and exact";
                try std.testing.expectEqualStrings("#fffafa", style.background orelse return error.TestUnexpectedResult);
                predicate = "table caption scan";
                try self.spans(a, value.caption);
                for (value.rows, 0..) |row, row_index| {
                    predicate = "later table row cell count";
                    if (row_index != 0) try std.testing.expectEqual(@as(usize, 5), row.cells.len);
                    for (row.cells) |cell| {
                        var cell_predicate: []const u8 = "cell background present and exact";
                        errdefer std.debug.print("SV failure cell predicate={s} row={d} header={} background={s} block_content={} nested_table={}\n", .{ cell_predicate, row_index, cell.header, cell.background orelse "<null>", cell.blocks != null, cell.nested_table != null });
                        try std.testing.expectEqualStrings(if (cell.header) "#eee9bf" else "#fffafa", cell.background orelse return error.TestUnexpectedResult);
                        cell_predicate = "cell body scan";
                        if (cell.blocks) |cell_blocks| try self.blocks(a, cell_blocks) else {
                            try self.spans(a, cell.spans);
                            cell_predicate = "cell has no nested table";
                            try std.testing.expect(cell.nested_table == null);
                        }
                    }
                }
            }
            fn figure(self: *@This(), a: std.mem.Allocator, value: encoder.presentation_types.Figure) anyerror!void {
                const image = value.content.image.span.image orelse return error.TestUnexpectedResult;
                try std.testing.expect(self.figures < 2);
                try std.testing.expectEqualStrings(media_files[self.figures], image.file);
                self.figures += 1;
                try std.testing.expect(value.format == .thumbnail and value.content.image.sizing == .requested_fit);
                try std.testing.expectEqual(@as(?u32, 190), image.width_px);
                try std.testing.expect(image.height_px == null);
                try std.testing.expect(value.content.image.span.kind == .link and value.content.image.span.text.len == 0 and value.content.image.span.trail.len == 0);
                try std.testing.expectEqualStrings(try std.mem.concat(a, u8, &.{"File:", image.file}), value.content.image.span.target);
                self.media(image.file);
                if (value.caption_blocks) |children| try self.blocks(a, children) else try self.spans(a, value.caption);
            }
            fn flow(self: *@This(), a: std.mem.Allocator, parts: []const encoder.presentation_types.FlowPart) anyerror!void {
                for (parts) |part| switch (part.kind) {
                    .@"inline" => try self.spans(a, part.spans),
                    .figure => try self.figure(a, part.figure orelse return error.TestUnexpectedResult),
                    .scope => try self.flow(a, (part.scope orelse return error.TestUnexpectedResult).parts),
                };
            }
            fn blocks(self: *@This(), a: std.mem.Allocator, values: []const encoder.presentation_types.Block) anyerror!void {
                for (values) |block| {
                    if (block.kind == .definition) self.definitions += 1;
                    if (block.flow) |parts| try self.flow(a, parts) else if (block.figure) |value| try self.figure(a, value) else try self.spans(a, block.spans);
                    if (block.table) |value| try self.table(a, value);
                    try self.visible.append(a, '\n');
                }
            }
            fn entry(self: *@This(), a: std.mem.Allocator, value: encoder.presentation_types.Entry) !void {
                try self.spans(a, value.preamble_spans);
                for (value.sections) |section| {
                    try self.visible.appendSlice(a, section.title);
                    try self.blocks(a, section.blocks);
                }
                try std.testing.expectEqual(@as(usize, 0), value.references.len);
                for (value.media) |item| self.media(item.file);
            }
        };
    };
    var tmp = std.testing.tmpDir(.{});
