    for ([_][]const u8{ "Lua error in Module:el-nouns-decl: The function \"δύναμη\" does not exist.", "ˈʝi.o.si", "αγώγιμη", "σύνδεση", "μηδενικού δυναμικού", "γειώ(νω)", "Λεξικό της Κοινής Νεοελληνικής", "Ευάγγελος Πετρούνιας" }) |text| {
