    var behavior = try namespace_registry.behavior_switches.Registry.init(a, behavior_source, ns.wiki, ns.dump_date, ns.content_language, ns.source_sha256);
    defer behavior.deinit();
    var behavior_sha: [32]u8 = undefined;
