    try std.testing.expectEqual(@as(usize, 0), stats.language_blobs);
    const path = try std.fs.path.join(a, &.{ output, encoder.blob_catalog.featureBlobFilename(.supplemental).? });
    const bytes = try std.Io.Dir.cwd().readFileAlloc(io, path, a, .limited(16 * 1024 * 1024));
    const blob = try encoder.blob_format.inspect(bytes);
    var index = try blob.buildTrustedIndexAlloc(a);
    defer index.deinit(a);
    try std.testing.expectEqual(@as(usize, 1), index.recordCount());
    const record = (try index.find(F.title)) orelse return error.TestUnexpectedResult;
    // The authored negative-margin label is now a real M Container.
    try std.testing.expectEqualStrings(codec.container_fonts_magic, record.payload[0..4]);
    const stored = try codec.decodeAlloc(a, record.payload, F.title, .supplemental, null);
    try std.testing.expect(stored.entry.language == null and stored.entry.language_code.len == 0);
    try std.testing.expectEqual(@as(usize, 0), stored.entry.organization.lexemes.len);
    try std.testing.expectEqual(@as(usize, 193), stored.entry.media.len);
    phase = "complete direct document versus Writer body and codec";
    var report: doc.Fallbacks = .{};
    const expected_payload = try doc.compileReportedWithOptionsAndPhasesAndTableStylesAlloc(a, F.title,
        .supplemental, null, "", doc.MissingText.untracked(F.source), null, codes.link_trail,
        &ns, &behavior, &images, &report, null, &profile);
    const expected = try codec.decodeAlloc(a, expected_payload, F.title, .supplemental, null);
    try std.testing.expectEqualDeep(expected, stored);
    try std.testing.expectEqualSlices(u8, expected_payload, record.payload);
    try std.testing.expectEqualSlices(u8, record.payload, try codec.encodeAlloc(a, stored));
    // The complete counterpart drops only the separately verified owner,
    // retaining its bold linked tooltip label and every other Stored field.
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, F.source, "margin-bottom: -0.5em;"));
    const legacy = try RetainedReferencesOwner347Test.legacy(a, stored);
    const legacy_bytes = try codec.encodeAlloc(a, legacy);
    try std.testing.expectEqualStrings(codec.tooltips_magic, legacy_bytes[0..4]);
    try std.testing.expectEqualDeep(legacy, try codec.decodeAlloc(a, legacy_bytes, F.title, .supplemental, null));
    phase = "all authored flags tables references and source order";
    var scan: F.Scan = .{};
    try scan.spans(a, stored.entry.display_title, false);
    try scan.spans(a, stored.entry.preamble_spans, false);
    for (stored.entry.sections) |section| try scan.blocks(a, section.blocks, false);
    try std.testing.expectEqual(@as(usize, 193), scan.images.items.len);
    try std.testing.expectEqual(@as(usize, 1), scan.reference_title_tooltips);
    try std.testing.expectEqual(@as(usize, 1), scan.reference_owners);
    var flags = std.mem.splitScalar(u8, std.mem.trimEnd(u8, F.flags, "\n"), '\n');
    var flag_count: usize = 0;
    while (flags.next()) |file| : (flag_count += 1) {
        try std.testing.expect(flag_count < stored.entry.media.len);
        try std.testing.expectEqualStrings(file, stored.entry.media[flag_count].file);
        try std.testing.expect(stored.entry.media[flag_count].kind == .image);
        try std.testing.expectEqualStrings(file, scan.images.items[flag_count]);
    }
    try std.testing.expectEqual(@as(usize, 193), flag_count);
    try std.testing.expectEqual(@as(usize, 2), scan.tables);
    try std.testing.expectEqual(@as(usize, 1), scan.country_tables);
    try std.testing.expectEqual(@as(usize, 1119), scan.citation_markers);
    try std.testing.expect(scan.bold_intro);
    var names = std.mem.splitScalar(u8, std.mem.trimEnd(u8, F.reference_names, "\n"), '\n');
    var note_count: usize = 0;
    for (stored.entry.references) |reference| {
        if (reference.kind != .note) continue;
        try std.testing.expectEqualStrings(names.next() orelse return error.TestUnexpectedResult, reference.name);
        note_count += 1;
        if (reference.blocks) |blocks| try scan.blocks(a, blocks, true) else try scan.spans(a, reference.spans, true);
    }
    try std.testing.expect(names.next() == null);
    try std.testing.expectEqual(@as(usize, 194), note_count);
    try std.testing.expectEqual(@as(usize, 194), scan.pdf_links);
    try std.testing.expectEqual(@as(usize, 194), scan.italic_book_titles);
    for ([_][]const u8{ "Afganistan", "Palau", "Zjednoczone Emiraty Arabskie", "Quellen:", "{{#isbn:978-83-239-9999-7}}" }) |text|
        try std.testing.expect(std.mem.indexOf(u8, scan.visible.items, text) != null);
    const report_path = try std.fs.path.join(a, &.{ output, "fallback-pages.jsonl" });
    const report_bytes = try std.Io.Dir.cwd().readFileAlloc(io, report_path, a, .limited(128 * 1024));
    const parsed = try std.json.parseFromSlice(struct { reasons: []const []const u8 }, a, report_bytes, .{ .ignore_unknown_fields = true });
    defer parsed.deinit();
    var unsupported = false;
    for (parsed.value.reasons) |reason| {
        if (std.mem.eql(u8, reason, "unsupported_parser_function")) unsupported = true;
        try std.testing.expect(!std.mem.eql(u8, reason, "render_limit"));
    }
    try std.testing.expect(unsupported);
}

// Optional request-lifetime observer. Ordinary builds retain their normal reads.
threadlocal var captured_writer_inputs: ?*CapturedWriterInputs = null;
const CapturedWriterInputs = struct {
    const Record = struct {
        path: []const u8,
        role: []const u8,
        identity: ?CapturedWriterSourceFileIdentity,
        sha256: ?[]const u8 = null,
        error_name: ?[]const u8 = null,
        file: ?std.Io.File = null,
    };
    io: std.Io,
    a: std.mem.Allocator,
    records: std.ArrayList(Record) = .empty,
    record_limit: usize = std.math.maxInt(usize),

    fn deinit(self: *CapturedWriterInputs) void {
        for (self.records.items) |record| {
            if (record.file) |file| file.close(self.io);
            self.a.free(record.path);
            self.a.free(record.role);
            if (record.sha256) |value| self.a.free(value);
            if (record.error_name) |value| self.a.free(value);
        }
        self.records.deinit(self.a);
    }
    fn find(self: *const CapturedWriterInputs, path: []const u8) ?usize {
        for (self.records.items, 0..) |record, i| if (std.mem.eql(u8, record.path, path)) return i;
        return null;
    }
    fn hold(self: *CapturedWriterInputs, path: []const u8, role: []const u8) !usize {
        if (!std.fs.path.isAbsolute(path)) return error.InvalidCapturedWriterPath;
        if (self.find(path)) |index| return index;
        if (self.records.items.len >= self.record_limit) return error.CapturedWriterInputLimitExceeded;
        var open_error: ?anyerror = null;
        const file: ?std.Io.File = std.Io.Dir.cwd().openFile(self.io, path, .{}) catch |err| failed: {
            open_error = err;
            break :failed null;
        };
        var adopted = false;
        errdefer { if (!adopted) { if (file) |value| value.close(self.io); } }
        const identity = if (file) |value| try capturedWriterSourceFileIdentity(value) else null;
        const owned_path = try self.a.dupe(u8, path);
        errdefer if (!adopted) self.a.free(owned_path);
        const owned_role = try self.a.dupe(u8, role);
        errdefer if (!adopted) self.a.free(owned_role);
        const owned_error = if (open_error) |err| try self.a.dupe(u8, @errorName(err)) else null;
        errdefer { if (!adopted) { if (owned_error) |value| self.a.free(value); } }
        try self.records.append(self.a, .{ .path = owned_path, .role = owned_role, .identity = identity, .file = file, .error_name = owned_error });
        adopted = true;
        // The record owns its allocations and handle before propagating an open
        // failure. FileNotFound remains an observable optional-input state.
        if (open_error) |err| if (err != error.FileNotFound) return err;
        return self.records.items.len - 1;
    }
    fn checkRecord(self: *CapturedWriterInputs, index: usize) !void {
        const record = self.records.items[index];
        if (record.identity) |before| {
            const held = try capturedWriterSourceFileIdentity(record.file.?);
            const path = try capturedWriterSourcePathIdentity(self.io, record.path);
            if (!std.meta.eql(before, held) or !std.meta.eql(before, path)) return error.CapturedWriterInputsChanged;
        } else {
            if (std.Io.Dir.cwd().access(self.io, record.path, .{})) |_| return error.CapturedWriterUnexpectedDependency else |err| switch (err) {
                error.FileNotFound => {},
                else => return err,
            }
        }
    }
    fn verify(self: *CapturedWriterInputs) !void {
        for (0..self.records.items.len) |i| try self.checkRecord(i);
    }
    fn acceptBytes(self: *CapturedWriterInputs, index: usize, bytes: []const u8) !void {
        var digest: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(bytes, &digest, .{});
        try self.acceptDigest(index, bytes.len, digest);
    }
    fn acceptDigest(self: *CapturedWriterInputs, index: usize, length: usize, hash: [32]u8) !void {
        try self.checkRecord(index);
        const record = &self.records.items[index];
        const identity = record.identity orelse return error.CapturedWriterFileMissing;
        if (identity.size != length) return error.CapturedWriterInputsChanged;
        const digest = try self.a.dupe(u8, &std.fmt.bytesToHex(hash, .lower));
        errdefer self.a.free(digest);
        if (record.sha256) |old| {
            if (!std.mem.eql(u8, old, digest)) return error.CapturedWriterInputsChanged;
            self.a.free(digest);
        } else record.sha256 = digest;
    }
    fn fail(self: *CapturedWriterInputs, index: usize, err: anyerror) !void {
        const record = &self.records.items[index];
        const replacement = try self.a.dupe(u8, @errorName(err));
        if (record.error_name) |old| self.a.free(old);
        record.error_name = replacement;
    }
    fn pin(self: *CapturedWriterInputs, expected: CapturedWriterFile) !void {
        const index = try self.hold(expected.path, "request-input");
        const record = &self.records.items[index];
        const identity = record.identity orelse return error.CapturedWriterFileMissing;
        if (identity.size != expected.bytes) return error.CapturedWriterFileMismatch;
        if (record.sha256 == null) {
            var hash = std.crypto.hash.sha2.Sha256.init(.{});
            var buffer: [65536]u8 = undefined;
            var offset: u64 = 0;
            while (true) {
                const n = try record.file.?.readPositionalAll(self.io, &buffer, offset);
                if (n == 0) break;
                hash.update(buffer[0..n]);
                offset = try std.math.add(u64, offset, n);
            }
            if (offset != identity.size) return error.CapturedWriterInputsChanged;
            var digest: [32]u8 = undefined;
            hash.final(&digest);
            record.sha256 = try self.a.dupe(u8, &std.fmt.bytesToHex(digest, .lower));
        }
        try self.checkRecord(index);
        if (!std.mem.eql(u8, record.sha256.?, expected.sha256)) return error.CapturedWriterFileMismatch;
    }
    fn mapped(self: *CapturedWriterInputs, path: []const u8, file: std.Io.File) !void {
        const index = try self.hold(path, "normal-mapped-input");
        const held = self.records.items[index].identity orelse return error.CapturedWriterFileMissing;
        if (!std.meta.eql(held, try capturedWriterSourceFileIdentity(file))) return error.CapturedWriterInputsChanged;
        try self.checkRecord(index);
    }
    fn exportRecords(self: *CapturedWriterInputs, output: []const u8) !void {
        const PublicRecord = struct { path: []const u8, role: []const u8, identity: ?CapturedWriterSourceFileIdentity, sha256: ?[]const u8, error_name: ?[]const u8 };
        const rows = try self.a.alloc(PublicRecord, self.records.items.len);
        defer self.a.free(rows);
        for (self.records.items, rows) |record, *row| row.* = .{ .path = record.path, .role = record.role, .identity = record.identity, .sha256 = record.sha256, .error_name = record.error_name };
        try writeDiagnosticJson(self.io, self.a, output, "consumed-inputs.json", .{ .schema = "wikidict.captured-writer.consumed-inputs.v1", .inputs = rows }, 2 * 1024 * 1024);
    }
};

fn readLanguageMetadataSource(io: std.Io, a: std.mem.Allocator, path: []const u8, limit: usize, expected: []const u8) ![]u8 {
    const observed = if (captured_writer_inputs) |inputs| try inputs.hold(path, "normal-language-module") else null;
    const source = std.Io.Dir.cwd().readFileAlloc(io, path, a, .limited(limit)) catch |err| {
        if (observed) |index| captured_writer_inputs.?.fail(index, err) catch {};
        return err;
    };
    errdefer a.free(source);
    var hash: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(source, &hash, .{});
    if (observed) |index| try captured_writer_inputs.?.acceptDigest(index, source.len, hash);
    if (!std.mem.eql(u8, expected, &std.fmt.bytesToHex(hash, .lower))) {
        if (observed) |index| captured_writer_inputs.?.fail(index, error.LanguageSourceIdentityMismatch) catch {};
        return error.LanguageSourceIdentityMismatch;
    }
    return source;
}

fn openLanguageTemplateSource(io: std.Io, a: std.mem.Allocator, root: []const u8, index: []const u8) !?dump_source.TemplateSource {
    var observed: [2]?usize = .{ null, null };
    if (captured_writer_inputs) |inputs| {
        inline for (.{ "template-source.idx", "template-source.bin" }, 0..) |name, i| {
            const path = try std.fs.path.join(a, &.{ root, name });
            defer a.free(path);
            observed[i] = try inputs.hold(path, "normal-template-sidecar");
        }
    }
    var result = dump_source.TemplateSource.open(io, a, root, index) catch |err| {
        if (captured_writer_inputs) |inputs| for (observed) |slot| if (slot) |i| inputs.fail(i, err) catch {};
        return err;
    };
    errdefer if (result) |*value| value.deinit();
    if (captured_writer_inputs) |inputs| {
        if (result) |value| {
            try inputs.acceptBytes(observed[0].?, value.index.bytes);
            try inputs.acceptBytes(observed[1].?, value.data.bytes);
        } else for (observed) |slot| if (slot) |i| try inputs.checkRecord(i);
    }
    return result;
}

const CapturedWriterFile = struct { path: []const u8, bytes: usize, sha256: []const u8 };
const CapturedWriterRequest = struct {
    schema: []const u8,
    source_fingerprint: []const u8,
    expander_root: []const u8,
    figure_input_root: ?[]const u8 = null,
    wiki: []const u8,
    date: []const u8,
    content_language: []const u8,
    // Exact retained capture receipt, authenticated by the opportunity owner.
    capture_receipt: CapturedWriterFile,
    audit_capture: ?CapturedWriterAuditCapture = null,
    figure_page_observations_root: ?[]const u8 = null,
    original_error_name: []const u8,
    // Fixed normal input roles only. Actual module/template reads are observed
    // during the unchanged normal loader; unused module bodies are not scanned.
    dependencies: []const CapturedWriterFile,
    absent_dependencies: []const []const u8 = &.{},
    // The retained normal dump and SourceReceipt are required in this mode.
    // They provide ordinary source-backed owner/style inputs, never defaults.
    source_category_dump: ?struct { path: []const u8 } = null,
    source_category_identity: ?CapturedWriterFile = null,
    source_relocation: ?CapturedWriterSourceRelocation = null,
    // Separate fresh normal indexes; the original capture row and coordinates never change.
    source_index_rebase: ?CapturedWriterSourceIndexRebase = null,
    // A separately derived normal registry profile preserves original page/source inputs.
    language_registry_root: ?[]const u8 = null,
    language_registry_manifest: ?CapturedWriterFile = null,
    language_registry_lineage: ?CapturedWriterFile = null,
    page: struct {
        title: []const u8,
        namespace: u32,
        page_id: u64,
        revision_id: u64,
        ordinal: u64,
        index_offset: u64,
        // Only already-dispatched, nonredirect page replies are supported.
        // Alias/site-metadata routing is a different ordinary entry contract.
        ordinary_page_reply: bool,
        raw_encoding: enum { decoded_wikitext, xml_encoded_once },
        raw: CapturedWriterFile,
        expanded: CapturedWriterFile,
        index_row: CapturedWriterFile,
        display_title: ?CapturedWriterFile = null,
        poem_metadata: ?CapturedWriterFile = null,
        missing_dependency_metadata: ?CapturedWriterFile = null,
        unsupported_parser_function: bool,
    },
};

fn capturedWriterCheckFile(io: std.Io, a: std.mem.Allocator, value: CapturedWriterFile) !void {
    if (!std.fs.path.isAbsolute(value.path) or value.sha256.len != 64) return error.InvalidCapturedWriterFile;
    if (captured_writer_inputs) |inputs| return inputs.pin(value);
    const stamp = try auditFileStamp(io, a, value.path);
    defer if (stamp.sha256) |bytes| a.free(bytes);
    const identity_value = stamp.identity orelse return error.CapturedWriterFileMissing;
    if (identity_value.size != value.bytes or !std.mem.eql(u8, stamp.sha256 orelse return error.CapturedWriterFileMissing, value.sha256)) return error.CapturedWriterFileMismatch;
}
fn capturedWriterRead(io: std.Io, a: std.mem.Allocator, value: CapturedWriterFile, limit: usize) ![]const u8 {
    if (value.bytes > limit) return error.CapturedWriterPayloadLimit;
    try capturedWriterCheckFile(io, a, value);
    const bytes = try std.Io.Dir.cwd().readFileAlloc(io, value.path, a, .limited(limit));
    errdefer a.free(bytes);
    if (bytes.len != value.bytes) return error.CapturedWriterFileMismatch;
    const digest = try auditHash(a, bytes);
    defer a.free(digest);
    if (!std.mem.eql(u8, digest, value.sha256)) return error.CapturedWriterFileMismatch;
    return bytes;
}
fn capturedWriterOptional(io: std.Io, a: std.mem.Allocator, value: ?CapturedWriterFile) !?[]const u8 {
    return if (value) |present| try capturedWriterRead(io, a, present, 4 * 1024 * 1024) else null;
}
fn capturedWriterCheckInputs(io: std.Io, a: std.mem.Allocator, request: CapturedWriterRequest) !void {
    try capturedWriterCheckFile(io, a, request.capture_receipt);
    if (request.audit_capture) |audit| {
        try capturedWriterCheckFile(io, a, audit.inputs);
        try capturedWriterCheckFile(io, a, audit.summary);
    }
    _ = try capturedWriterObservationRoot(request, a);
    if (request.language_registry_root) |profile_root| {
        if (!std.fs.path.isAbsolute(profile_root)) return error.InvalidCapturedWriterRegistryProfile;
        try capturedWriterCheckFile(io, a, request.language_registry_manifest orelse return error.InvalidCapturedWriterRegistryProfile);
        try capturedWriterCheckFile(io, a, request.language_registry_lineage orelse return error.InvalidCapturedWriterRegistryProfile);
        try capturedWriterRequireSourceDependency(request, try std.fs.path.join(a, &.{ profile_root, "language-registry.tsv" }));
    } else if (request.language_registry_manifest != null or request.language_registry_lineage != null) return error.InvalidCapturedWriterRegistryProfile;
    if (request.source_index_rebase == null and (request.source_category_dump == null) != (request.source_category_identity == null)) return error.InvalidCapturedWriterCategoryInputs;
    if (request.source_index_rebase != null) try capturedWriterCheckIndexRebase(io, a, request);
    if (request.source_category_identity) |value| try capturedWriterCheckFile(io, a, value);
    if (request.source_relocation) |relocation| {
        if (request.source_category_identity == null or
            !capturedWriterSameFile(relocation.capture_receipt, request.capture_receipt) or
            !capturedWriterSameFile(relocation.source_identity, request.source_category_identity.?))
            return error.CapturedWriterSourceEquivalenceMismatch;
        try capturedWriterCheckSourceEquivalence(io, a, relocation.source);
        for (relocation.indexes) |file| if (file) |present| try capturedWriterCheckSourceEquivalence(io, a, present);
    }
    if (request.dependencies.len == 0 or request.dependencies.len > 128) return error.InvalidCapturedWriterDependencies;
    for (request.dependencies) |value| try capturedWriterCheckFile(io, a, value);
    for (request.absent_dependencies) |path| {
        if (!std.fs.path.isAbsolute(path)) return error.InvalidCapturedWriterFile;
        if (captured_writer_inputs) |inputs| _ = try inputs.hold(path, "declared-absent-input");
        if (std.Io.Dir.cwd().access(io, path, .{})) |_| return error.CapturedWriterUnexpectedDependency else |err| switch (err) {
            error.FileNotFound => {},
            else => return err,
        }
    }
    try capturedWriterCheckFile(io, a, request.page.raw);
    try capturedWriterCheckFile(io, a, request.page.expanded);
    try capturedWriterCheckFile(io, a, request.page.index_row);
    inline for (.{ "display_title", "poem_metadata", "missing_dependency_metadata" }) |field|
        if (@field(request.page, field)) |value| try capturedWriterCheckFile(io, a, value);
}

fn capturedWriterValidateRequest(request: CapturedWriterRequest, compiled_source_fingerprint: []const u8) !void {
    const first_capture = std.mem.eql(u8, request.schema, "wikidict.captured-writer.request.v2");
    const audit_capture = std.mem.eql(u8, request.schema, "wikidict.captured-writer.request.v3");
    if ((!first_capture and !audit_capture) or
        (first_capture and (request.audit_capture != null or request.figure_page_observations_root != null)) or
        (audit_capture and request.audit_capture == null) or
        !std.mem.eql(u8, request.source_fingerprint, compiled_source_fingerprint) or
        !std.fs.path.isAbsolute(request.expander_root) or !request.page.ordinary_page_reply or
        request.page.page_id == 0 or request.page.revision_id == 0 or request.page.title.len == 0 or
        !std.unicode.utf8ValidateSlice(request.page.title)) return error.InvalidCapturedWriterRequest;
}

pub fn runCapturedWriterDiagnostic(io: std.Io, a: std.mem.Allocator, request_path: []const u8, output_root: []const u8, compiled_source_fingerprint: []const u8) !void {
    return runCapturedWriterDiagnosticWithShared(io, a, request_path, output_root, compiled_source_fingerprint, null, null);
}

fn runCapturedWriterDiagnosticWithShared(io: std.Io, a: std.mem.Allocator, request_path: []const u8, output_root: []const u8, compiled_source_fingerprint: []const u8, shared: ?*CapturedWriterSharedInputs, expected_request: ?CapturedWriterFile) !void {
    if (!std.fs.path.isAbsolute(request_path) or !std.fs.path.isAbsolute(output_root)) return error.InvalidCapturedWriterPath;
    const bytes = try std.Io.Dir.cwd().readFileAlloc(io, request_path, a, .limited(2 * 1024 * 1024));
    defer a.free(bytes);
    const parsed = try std.json.parseFromSlice(CapturedWriterRequest, a, bytes, .{});
    defer parsed.deinit();
    const request = parsed.value;
    if (expected_request) |expected| {
        if (!std.mem.eql(u8, expected.path, request_path) or bytes.len != expected.bytes or
            !std.mem.eql(u8, try auditHash(a, bytes), expected.sha256)) return error.CapturedWriterFileMismatch;
        try shared.?.inputs.pin(expected);
    }
    try capturedWriterValidateRequest(request, compiled_source_fingerprint);
    if (captured_writer_inputs != null) return error.CapturedWriterAlreadyActive;
    // createDir refuses an existing output, preserving every prior diagnosis.
    try std.Io.Dir.cwd().createDir(io, output_root, .default_dir);
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = try std.fs.path.join(a, &.{ output_root, "captured-request.json" }), .data = bytes });
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = try std.fs.path.join(a, &.{ output_root, ".diagnostic-only" }), .data = "captured Writer diagnostic; not a corpus publication\n" });
    var local_inputs: CapturedWriterInputs = .{ .io = io, .a = a };
    defer if (shared == null) local_inputs.deinit();
    const inputs = if (shared) |value| &value.inputs else &local_inputs;
    captured_writer_inputs = inputs;
    defer captured_writer_inputs = null;
    var rejection: encoder.presentation_document.RejectedFieldCapture = .{};
    const rejection_scope = rejection.begin();
    defer rejection_scope.deinit();
    var stage: []const u8 = "input-authentication";
    try writeDiagnosticJson(io, a, output_root, "diagnostic-result.json", .{ .schema = "wikidict.captured-writer.result.v1", .complete = false, .diagnostic_only = true, .semantic_acceptance = false }, 64 * 1024);
    capturedWriterRun(io, a, request, output_root, &stage, shared) catch |err| {
        var input_integrity_after = true;
        var integrity_error: ?[]const u8 = null;
        inputs.verify() catch |secondary| {
            input_integrity_after = false;
            integrity_error = @errorName(secondary);
            diagnostics.printLine("captured Writer input integrity failed: original={s} integrity={s}\n", .{ @errorName(err), @errorName(secondary) });
        };
        inputs.exportRecords(output_root) catch |export_error| {
            diagnostics.printLine("captured Writer dependency export failed: {s}\n", .{@errorName(export_error)});
        };
        writeDiagnosticJson(io, a, output_root, "diagnostic-result.json", .{
            .schema = "wikidict.captured-writer.result.v1", .complete = true, .passed = false,
            .stage = stage, .error_name = @errorName(err), .input_integrity_after = input_integrity_after, .integrity_error = integrity_error, .failed_field = if (encoder.presentation_document.rejectedFieldSnapshot(err)) |field| @as(?[]const u8, @tagName(field.location.field)) else null,
            .failed_field_available = encoder.presentation_document.rejectedFieldSnapshot(err) != null,
            .rejected_field = encoder.presentation_document.rejectedFieldSnapshot(err),
            .compiler_rejection = encoder.presentation_document.rejectedCompilerSnapshot(err), .title = request.page.title,
            .page_id = request.page.page_id, .revision_id = request.page.revision_id,
            .source_fingerprint = compiled_source_fingerprint, .diagnostic_only = true,
            .publication_created = false, .semantic_acceptance = false,
        }, 64 * 1024) catch |diagnostic_error| {
            diagnostics.printLine("captured Writer result unavailable: original={s} diagnostic={s}\n", .{ @errorName(err), @errorName(diagnostic_error) });
        };
        return err;
    };
    try writeDiagnosticJson(io, a, output_root, "diagnostic-result.json", .{
        .schema = "wikidict.captured-writer.result.v1", .complete = true, .passed = true, .input_integrity_after = true,
        .title = request.page.title, .page_id = request.page.page_id,
        .revision_id = request.page.revision_id, .source_fingerprint = compiled_source_fingerprint,
        .diagnostic_only = true, .publication_created = false, .semantic_acceptance = false,
    }, 64 * 1024);
}

const CapturedWriterSourceOrigin = struct {
    dump_path: []const u8,
    expander_root: []const u8,
    figure_input_root: ?[]const u8 = null,
    figure_page_observations_snapshot: ?[]const u8 = null,
    stylesheet_imports_snapshot: ?[]const u8 = null,
};
const CapturedWriterSourceFileIdentity = struct { device_major: u32, device_minor: u32, inode: u64, size: u64, mtime_ns: i128, ctime_ns: i128 };
const CapturedWriterSourceIdentity = struct { version: u32, source: CapturedWriterSourceFileIdentity, indexes: [3]?CapturedWriterSourceFileIdentity, namespace_sha256: [32]u8, redirects_sha256: ?[32]u8 };
fn capturedWriterSourceFileIdentity(file: std.Io.File) !CapturedWriterSourceFileIdentity {
    const linux = std.os.linux;
    var stat: linux.Statx = undefined;
    if (linux.statx(file.handle, "", linux.AT.EMPTY_PATH, linux.STATX.BASIC_STATS, &stat) != 0 or !stat.mask.INO or !stat.mask.SIZE or !stat.mask.MTIME or !stat.mask.CTIME or !stat.mask.TYPE or (stat.mode & linux.S.IFMT) != linux.S.IFREG) return error.SourceStatFailed;
    return .{ .device_major = stat.dev_major, .device_minor = stat.dev_minor, .inode = stat.ino, .size = stat.size,
        .mtime_ns = @as(i128, stat.mtime.sec) * std.time.ns_per_s + stat.mtime.nsec,
        .ctime_ns = @as(i128, stat.ctime.sec) * std.time.ns_per_s + stat.ctime.nsec };
}
fn capturedWriterSourcePathIdentity(io: std.Io, path: []const u8) !CapturedWriterSourceFileIdentity {
    var file = try std.Io.Dir.cwd().openFile(io, path, .{});
    defer file.close(io);
    return capturedWriterSourceFileIdentity(file);
}
fn capturedWriterRequireSourceDependency(request: CapturedWriterRequest, path: []const u8) !void {
    for (request.dependencies) |file| if (std.mem.eql(u8, file.path, path)) return;
    return error.UnpinnedCapturedWriterSourceDependency;
}
fn capturedWriterRequireSourceAbsence(request: CapturedWriterRequest, path: []const u8) !void {
    for (request.absent_dependencies) |file| if (std.mem.eql(u8, file, path)) return;
    return error.UnpinnedCapturedWriterSourceDependency;
}
// Match extraction modules.sourceReceipt: all three indexed identities, zeroed
// index ctime, full source ctime, namespace digest and optional redirects hash.
fn capturedWriterSourceSnapshot(io: std.Io, a: std.mem.Allocator, request: CapturedWriterRequest, source: CapturedWriterSourceFileIdentity, kind: dump_source.PageIndexKind, namespace_sha256: [32]u8) !CapturedWriterSourceIdentity {
    var indexes: [3]?CapturedWriterSourceFileIdentity = .{ null, null, null };
    for (0..3) |i| {
        const path = try capturedWriterIndexPath(a, request, i);
        if (std.Io.Dir.cwd().access(io, path, .{})) |_| {
            const observed = try captured_writer_inputs.?.hold(path, "source-receipt-index");
            indexes[i] = captured_writer_inputs.?.records.items[observed].identity orelse return error.MissingCapturedWriterSourceIndex;
            indexes[i].?.ctime_ns = 0;
        } else |err| switch (err) {
            error.FileNotFound => {
                if (i != 2 or dump_source.isMultistream(kind)) return error.MissingCapturedWriterSourceIndex;
                _ = try captured_writer_inputs.?.hold(path, "absent-source-index");
            },
            else => return err,
        }
    }
    const redirects_path = try std.fs.path.join(a, &.{ request.expander_root, "transclusion-redirects.tsv" });
    var redirects_sha256: ?[32]u8 = null;
    if (std.Io.Dir.cwd().access(io, redirects_path, .{})) |_| {
        try capturedWriterRequireSourceDependency(request, redirects_path);
        const bytes = try std.Io.Dir.cwd().readFileAlloc(io, redirects_path, a, .limited(16 * 1024 * 1024));
        var digest: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(bytes, &digest, .{});
        redirects_sha256 = digest;
    } else |err| switch (err) {
        error.FileNotFound => try capturedWriterRequireSourceAbsence(request, redirects_path),
        else => return err,
    }
    return .{ .version = 2, .source = source, .indexes = indexes, .namespace_sha256 = namespace_sha256, .redirects_sha256 = redirects_sha256 };
}
const CapturedWriterRelocatedFile = struct {
    role: enum { dump, page_index, title_index, dump_streams },
    original: CapturedWriterFile,
    original_identity: CapturedWriterSourceFileIdentity,
    current: CapturedWriterFile,
    current_identity: CapturedWriterSourceFileIdentity,
    // An independently closed, content-equivalence receipt. Original physical
    // identity is historical; it is never installed as the current identity.
    equivalence: CapturedWriterFile,
};
const CapturedWriterSourceRelocation = struct {
    capture_receipt: CapturedWriterFile,
    source_identity: CapturedWriterFile,
    source: CapturedWriterRelocatedFile,
    indexes: [3]?CapturedWriterRelocatedFile,
};
const CapturedWriterSourceIndexRebase = struct {
    capture_receipt: CapturedWriterFile,
    original_repack: CapturedWriterFile,
    current_repack: CapturedWriterFile,
    dump: CapturedWriterFile,
    repack_index: CapturedWriterFile,
    source_identity: CapturedWriterFile,
    inputs: []const struct { wiki: []const u8, date: []const u8, name: []const u8, size: u64, sha1: []const u8 },
    indexes: [3]CapturedWriterFile,
    page: struct { ordinal: u64, index_offset: u64, index_row: CapturedWriterFile },
};
const CapturedWriterRepackReceipt = struct {
    version: []const u8,
    part_order: ?[]const u8 = null,
    input_sha256: []const u8,
    dump_codec: []const u8,
    dump_stream_kind: []const u8,
    source_pages: u64,
    dump_size: u64,
    dump_sha256: []const u8,
    index_size: u64,
    index_sha256: []const u8,
};
const CapturedWriterRepackRow = @Tuple(&.{ []const u8, []const u8, []const u8, u64, []const u8 });
fn capturedWriterRepackFingerprintBytes(a: std.mem.Allocator, rows: []const CapturedWriterRepackRow, version: []const u8, part_order: ?[]const u8) ![]u8 {
    if (part_order) |order| {
        if (!std.mem.eql(u8, order, "page-range-v1")) return error.CapturedWriterSourceContextMismatch;
        return std.json.Stringify.valueAlloc(a, .{ .files = rows, .part_order = order, .version = version }, .{});
    }
    // Keep the exact historical sorted-manifest encoding when no new recipe
    // was selected. The marker's physical dump/index digests remain required.
    return std.json.Stringify.valueAlloc(a, .{ .files = rows, .version = version }, .{});
}
fn capturedWriterCheckIndexRebase(io: std.Io, a: std.mem.Allocator, request: CapturedWriterRequest) !void {
    const rebase = request.source_index_rebase orelse return error.CapturedWriterSourceContextMismatch;
    const original_dump = request.source_category_dump orelse return error.InvalidCapturedWriterCategoryInputs;
    if (request.source_category_identity != null or request.source_relocation != null or
        !capturedWriterSameFile(rebase.capture_receipt, request.capture_receipt) or
        !std.mem.eql(u8, std.fs.path.basename(original_dump.path), "pages.xml.zst") or
        !std.mem.eql(u8, std.fs.path.basename(rebase.dump.path), "pages.xml.zst") or
        !std.mem.eql(u8, std.fs.path.basename(rebase.source_identity.path), "extraction-source.json")) return error.CapturedWriterSourceContextMismatch;
    const original_marker = try std.fs.path.join(a, &.{ std.fs.path.dirname(original_dump.path) orelse return error.CapturedWriterSourceContextMismatch, ".complete.json" }); defer a.free(original_marker);
    const current_marker = try std.fs.path.join(a, &.{ std.fs.path.dirname(rebase.dump.path) orelse return error.CapturedWriterSourceContextMismatch, ".complete.json" }); defer a.free(current_marker);
    if (!std.mem.eql(u8, rebase.original_repack.path, original_marker) or !std.mem.eql(u8, rebase.current_repack.path, current_marker) or
        rebase.original_repack.bytes != rebase.current_repack.bytes or !std.mem.eql(u8, rebase.original_repack.sha256, rebase.current_repack.sha256))
        return error.CapturedWriterSourceContextMismatch;
    const marker_bytes = try capturedWriterRead(io, a, rebase.original_repack, 64 * 1024); defer a.free(marker_bytes);
    try capturedWriterCheckFile(io, a, rebase.current_repack);
    const parsed = try std.json.parseFromSlice(CapturedWriterRepackReceipt, a, marker_bytes, .{}); defer parsed.deinit();
    const marker = parsed.value;
    if (!std.mem.eql(u8, marker.version, "page-aligned-zstd-parallel-v2") or !std.mem.eql(u8, marker.dump_codec, "zstd") or
        !std.mem.eql(u8, marker.dump_stream_kind, "multistream-zstd") or marker.source_pages == 0 or
        request.page.ordinal >= marker.source_pages or rebase.page.ordinal >= marker.source_pages or
        marker.dump_size != rebase.dump.bytes or !std.mem.eql(u8, marker.dump_sha256, rebase.dump.sha256) or
        marker.index_size == 0 or marker.index_sha256.len != 64 or marker.input_sha256.len != 64 or
        rebase.inputs.len == 0 or rebase.inputs.len > 64) return error.CapturedWriterSourceContextMismatch;
    // Reproduce the ordinary dump_input_fingerprint, including edition/date and official SHA1 rows.
    const rows = try a.alloc(CapturedWriterRepackRow, rebase.inputs.len); defer a.free(rows);
    const prefix = try std.fmt.allocPrint(a, "{s}-{s}-", .{ request.wiki, request.date }); defer a.free(prefix);
    for (rebase.inputs, 0..) |item, i| {
        if (!std.mem.eql(u8, item.wiki, request.wiki) or !std.mem.eql(u8, item.date, request.date) or
            !std.mem.startsWith(u8, item.name, prefix) or std.mem.indexOfAny(u8, item.name, "/\\") != null or
            item.size == 0 or item.sha1.len != 40 or (i != 0 and std.mem.order(u8, rebase.inputs[i-1].name, item.name) != .lt))
            return error.CapturedWriterSourceContextMismatch;
        for (item.sha1) |char| if (!(char >= '0' and char <= '9') and !(char >= 'a' and char <= 'f')) return error.CapturedWriterSourceContextMismatch;
        rows[i] = .{ item.wiki, item.date, item.name, item.size, item.sha1 };
    }
    const encoded = try capturedWriterRepackFingerprintBytes(a, rows, marker.version, marker.part_order); defer a.free(encoded);
    const digest = try auditHash(a, encoded); defer a.free(digest);
    if (!std.mem.eql(u8, marker.input_sha256, digest)) return error.CapturedWriterSourceContextMismatch;
    if (request.audit_capture) |audit| if (audit.dump.bytes != rebase.dump.bytes or !std.mem.eql(u8, audit.dump.sha256, rebase.dump.sha256)) return error.CapturedWriterAuditMismatch;
    const archive_index = try std.fs.path.join(a, &.{ std.fs.path.dirname(rebase.dump.path).?, "pages-index.txt.bz2" }); defer a.free(archive_index);
    if (!std.mem.eql(u8, rebase.repack_index.path, archive_index) or rebase.repack_index.bytes != marker.index_size or
        !std.mem.eql(u8, rebase.repack_index.sha256, marker.index_sha256)) return error.CapturedWriterSourceContextMismatch;
    try capturedWriterCheckFile(io, a, rebase.dump);
    try capturedWriterCheckFile(io, a, rebase.repack_index);
    try capturedWriterCheckFile(io, a, rebase.source_identity);
    const root = std.fs.path.dirname(rebase.source_identity.path) orelse return error.CapturedWriterSourceContextMismatch;
    const names = [_][]const u8{ "page-index.tsv", dump_source.page_title_index_filename, "dump-streams.tsv" };
    for (rebase.indexes, names) |file, name| {
        const path = try std.fs.path.join(a, &.{ root, name }); defer a.free(path);
        if (!std.mem.eql(u8, file.path, path)) return error.CapturedWriterSourceContextMismatch;
        try capturedWriterCheckFile(io, a, file);
    }
    try capturedWriterCheckFile(io, a, rebase.page.index_row);
}
const CapturedWriterSourceEquivalence = struct {
    schema: []const u8,
    passed: bool,
    closed: bool,
    original: CapturedWriterFile,
    original_identity: CapturedWriterSourceFileIdentity,
    current: CapturedWriterFile,
    current_identity: CapturedWriterSourceFileIdentity,
    // Exact retained content/retirement authority and actual verification
    // closure, already joined by the captured-input binder. No inode alias claim.
    evidence: []const CapturedWriterFile,
};
fn capturedWriterSameFile(left: CapturedWriterFile, right: CapturedWriterFile) bool {
    return left.bytes == right.bytes and std.mem.eql(u8, left.path, right.path) and std.mem.eql(u8, left.sha256, right.sha256);
}
fn capturedWriterCheckSourceEquivalence(io: std.Io, a: std.mem.Allocator, file: CapturedWriterRelocatedFile) !void {
    const bytes = try capturedWriterRead(io, a, file.equivalence, 2 * 1024 * 1024);
    defer a.free(bytes);
    const parsed = try std.json.parseFromSlice(CapturedWriterSourceEquivalence, a, bytes, .{});
    defer parsed.deinit();
    const proof = parsed.value;
    if (!std.mem.eql(u8, proof.schema, "wikidict.captured-source-equivalence.v1") or !proof.passed or !proof.closed or
        proof.evidence.len < 2 or proof.evidence.len > 16 or
        !capturedWriterSameFile(proof.original, file.original) or !capturedWriterSameFile(proof.current, file.current) or
        !std.meta.eql(proof.original_identity, file.original_identity) or !std.meta.eql(proof.current_identity, file.current_identity) or
        file.original.bytes != file.current.bytes or file.original.bytes != file.original_identity.size or
        file.current.bytes != file.current_identity.size or !std.mem.eql(u8, file.original.sha256, file.current.sha256))
        return error.CapturedWriterSourceEquivalenceMismatch;
    for (proof.evidence) |evidence| {
        if (evidence.bytes > 16 * 1024 * 1024) return error.CapturedWriterPayloadLimit;
        try capturedWriterCheckFile(io, a, evidence);
    }
    try capturedWriterCheckFile(io, a, file.current);
    if (!std.meta.eql(file.current_identity, try capturedWriterSourcePathIdentity(io, file.current.path)))
        return error.CapturedWriterSourceContextMismatch;
}
fn capturedWriterIndexPath(a: std.mem.Allocator, request: CapturedWriterRequest, index: usize) ![]const u8 {
    if (request.source_index_rebase) |rebase| return rebase.indexes[index].path;
    if (request.source_relocation) |relocation| {
        if (relocation.indexes[index]) |file| return file.current.path;
    }
    const names = [_][]const u8{ "page-index.tsv", dump_source.page_title_index_filename, "dump-streams.tsv" };
    return std.fs.path.join(a, &.{ request.expander_root, names[index] });
}
fn capturedWriterRelocatedIdentity(identity: CapturedWriterSourceFileIdentity, index: bool) CapturedWriterSourceFileIdentity {
    var result = identity;
    if (index) result.ctime_ns = 0;
    return result;
}
fn capturedWriterValidateRelocation(request: CapturedWriterRequest, origin: CapturedWriterSourceOrigin,
    snapshot: CapturedWriterSourceIdentity, actual: CapturedWriterSourceIdentity) !void
{
    const relocation = request.source_relocation orelse return error.CapturedWriterSourceContextMismatch;
    if (!capturedWriterSameFile(relocation.capture_receipt, request.capture_receipt) or
        !capturedWriterSameFile(relocation.source_identity, request.source_category_identity.?) or
        relocation.source.role != .dump or !std.mem.eql(u8, relocation.source.original.path, origin.dump_path) or
        !std.meta.eql(relocation.source.original_identity, snapshot.source) or
        !std.meta.eql(relocation.source.current_identity, actual.source) or
        !std.meta.eql(snapshot.namespace_sha256, actual.namespace_sha256) or
        !std.meta.eql(snapshot.redirects_sha256, actual.redirects_sha256)) return error.CapturedWriterSourceContextMismatch;
    const names = [_][]const u8{ "page-index.tsv", dump_source.page_title_index_filename, "dump-streams.tsv" };
    const roles = [_]@FieldType(CapturedWriterRelocatedFile, "role"){ .page_index, .title_index, .dump_streams };
    for (relocation.indexes, 0..) |maybe_file, i| {
        if (maybe_file) |file| {
            if (snapshot.indexes[i] == null or actual.indexes[i] == null or file.role != roles[i] or
                !std.mem.eql(u8, std.fs.path.basename(file.original.path), names[i]) or
                !std.mem.eql(u8, std.fs.path.dirname(file.original.path) orelse "", origin.expander_root) or
                !std.meta.eql(capturedWriterRelocatedIdentity(file.original_identity, true), snapshot.indexes[i].?) or
                !std.meta.eql(capturedWriterRelocatedIdentity(file.current_identity, true), actual.indexes[i].?))
                return error.CapturedWriterSourceContextMismatch;
        } else if (snapshot.indexes[i] != null or actual.indexes[i] != null) return error.CapturedWriterSourceContextMismatch;
    }
}

fn capturedWriterValidateCategoryContext(request: CapturedWriterRequest, origin: CapturedWriterSourceOrigin, identity_path: []const u8, snapshot: CapturedWriterSourceIdentity, actual: CapturedWriterSourceIdentity) !void {
    const dump = request.source_category_dump orelse return error.InvalidCapturedWriterCategoryInputs;
    if (request.source_index_rebase) |rebase| {
        if (request.source_category_identity != null or request.source_relocation != null or
            !std.mem.eql(u8, dump.path, origin.dump_path) or !std.mem.eql(u8, request.expander_root, origin.expander_root) or
            !std.mem.eql(u8, rebase.source_identity.path, identity_path) or snapshot.version != 2 or !std.meta.eql(snapshot, actual) or
            actual.source.size != rebase.dump.bytes) return error.CapturedWriterSourceContextMismatch;
        for (rebase.indexes, 0..) |file, i| if (actual.indexes[i] == null or file.bytes != actual.indexes[i].?.size)
            return error.CapturedWriterSourceContextMismatch;
        return;
    }
    const identity = request.source_category_identity orelse return error.InvalidCapturedWriterCategoryInputs;
    if (!std.fs.path.isAbsolute(dump.path) or !std.mem.eql(u8, dump.path, origin.dump_path) or
        !std.mem.eql(u8, request.expander_root, origin.expander_root) or !std.mem.eql(u8, identity.path, identity_path) or
        snapshot.version != 2 or actual.version != 2) return error.CapturedWriterSourceContextMismatch;
    if (request.source_relocation != null) {
        try capturedWriterValidateRelocation(request, origin, snapshot, actual);
    } else if (!std.meta.eql(snapshot, actual)) return error.CapturedWriterSourceContextMismatch;
}

fn capturedWriterRun(io: std.Io, a: std.mem.Allocator, request: CapturedWriterRequest, output_root: []const u8, stage: *[]const u8, shared: ?*CapturedWriterSharedInputs) !void {
    try capturedWriterCheckInputs(io, a, request);
    const captured = try capturedWriterAuthenticatedOriginWithShared(io, a, request, shared);
    defer captured.deinit(a);
    try capturedWriterRequireNormalRoles(io, a, request);
    const root = request.expander_root;
    var local_figure_inputs: ?WriterFigureInputs = if (shared == null) if (request.figure_input_root) |selected|
        try WriterFigureInputs.init(io, a, root, selected) else null else null;
    defer if (local_figure_inputs) |*value| value.deinit();
    const figure_inputs: ?*WriterFigureInputs = if (shared) |value| try value.figureInputs(io, root, request.figure_input_root)
        else if (local_figure_inputs) |*value| value else null;
    stage.* = "namespace-loader";
    var local_namespaces: ?namespace_registry.Registry = null;
    defer if (local_namespaces) |*value| value.deinit();
    const namespaces: *namespace_registry.Registry = if (shared) |value| try value.namespace(io, root) else ns: {
        local_namespaces = try namespace_registry.Registry.load(io, a, root);
        break :ns &local_namespaces.?;
    };
    if (!std.mem.eql(u8, namespaces.wiki, request.wiki) or !std.mem.eql(u8, namespaces.dump_date, request.date) or
        !std.mem.eql(u8, namespaces.content_language, request.content_language)) return error.CapturedWriterEditionMismatch;
    if (shared == null or !shared.?.namespace_ready) {
        errdefer if (shared) |value| { value.failed_loader = true; };
        const interwiki_path = try std.fs.path.join(a, &.{ root, "interwiki-map.tsv" });
        const interwiki_bytes = std.Io.Dir.cwd().readFileAlloc(io, interwiki_path, a, .limited(4 * 1024 * 1024)) catch |err| switch (err) { error.FileNotFound => null, else => return err };
        defer if (interwiki_bytes) |value| a.free(value);
        if (interwiki_bytes) |value| try namespaces.attachInterwikiMap(value);
    }
    stage.* = "page-identity";
    var page_index = try mmapPath(io, try capturedWriterIndexPath(a, request, 0));
    defer page_index.deinit();
    const selected_offset = if (request.source_index_rebase) |rebase| rebase.page.index_offset else request.page.index_offset;
    const selected_ordinal = if (request.source_index_rebase) |rebase| rebase.page.ordinal else request.page.ordinal;
    const selected_row = if (request.source_index_rebase) |rebase| rebase.page.index_row else request.page.index_row;
    if (request.source_index_rebase != null and dump_source.pageIndexKind(page_index.bytes) != .multistream_zstd) return error.CapturedWriterSourceContextMismatch;
    const offset = std.math.cast(usize, selected_offset) orelse return error.InvalidPageIndex;
    if (offset >= page_index.bytes.len or (offset != 0 and page_index.bytes[offset - 1] != '\n')) return error.InvalidPageIndex;
    const end = std.mem.indexOfScalarPos(u8, page_index.bytes, offset, '\n') orelse page_index.bytes.len;
    const line = page_index.bytes[offset..end];
    const page = try dump_source.parsePageIndexLine(dump_source.pageIndexKind(page_index.bytes), line);
    const retained_row = try capturedWriterRead(io, a, selected_row, 1024 * 1024);
    if (!std.mem.eql(u8, retained_row, line)) return error.CapturedWriterPageMismatch;
    if (page.ns != request.page.namespace or page.page_id != request.page.page_id or page.revision_id != request.page.revision_id or
        !std.mem.eql(u8, page.title, request.page.title) or !page.has_source or page.redirect != null) return error.CapturedWriterPageMismatch;
    var title_index = try mmapPath(io, try capturedWriterIndexPath(a, request, 1));
    defer title_index.deinit();
    const titles = try dump_source.PageTitleIndex.init(title_index.bytes);
    if (titles.page_index_size != page_index.bytes.len or titles.kind != dump_source.pageIndexKind(page_index.bytes)) return error.PageTitleIndexMismatch;
    const row = (try titles.lookup(page_index.bytes, page.title)) orelse return error.InvalidPageTitleIndex;
    if (dump_source.pageRowRefOrdinal(row) != selected_ordinal or dump_source.pageRowRefOffset(row) != offset) return error.CapturedWriterPageMismatch;
    // Declared before Writer: its destructor therefore runs after Writer's,
    // while the page/title maps, namespace and registry still remain alive.
    var category_dump: ?dump_source.SourceReader = null;
    defer if (category_dump) |*value| value.deinit();
    var category_context: ?source_category_language.Context = null;
    var category_identity: ?CapturedWriterSourceIdentity = null;
    if (request.source_category_dump) |input| {
        stage.* = "category-source-context";
        const identity_file = if (request.source_index_rebase) |rebase| rebase.source_identity else request.source_category_identity orelse return error.InvalidCapturedWriterCategoryInputs;
        const identity_path = if (request.source_index_rebase != null) identity_file.path else try std.fs.path.join(a, &.{ root, "extraction-source.json" });
        const identity_bytes = try capturedWriterRead(io, a, identity_file, 64 * 1024);
        const snapshot = try std.json.parseFromSlice(CapturedWriterSourceIdentity, a, identity_bytes, .{});
        defer snapshot.deinit();
        const kind = dump_source.pageIndexKind(page_index.bytes);
        const streams = try capturedWriterIndexPath(a, request, 2);
        if (dump_source.isMultistream(kind)) _ = try captured_writer_inputs.?.hold(streams, "source-receipt-streams");
        const current_dump = if (request.source_index_rebase) |rebase| rebase.dump.path else if (request.source_relocation) |relocation| relocation.source.current.path else input.path;
        category_dump = try dump_source.SourceReader.open(io, a, a, current_dump, kind, if (dump_source.isMultistream(kind)) streams else null);
        try captured_writer_inputs.?.mapped(current_dump, category_dump.?.file);
        const actual = try capturedWriterSourceSnapshot(io, a, request, try capturedWriterSourceFileIdentity(category_dump.?.file), kind, namespaces.source_sha256);
        try capturedWriterValidateCategoryContext(request, captured.origin, identity_path, snapshot.value, actual);
        if (captured.audit_dump) |stamp| {
            if (request.source_index_rebase != null) {
                if (stamp.size != snapshot.value.source.size) return error.CapturedWriterAuditMismatch;
            } else {
            const original = snapshot.value.source;
            if (original.device_major != stamp.device_major or original.device_minor != stamp.device_minor or
                original.inode != stamp.inode or original.size != stamp.size or original.mtime_ns != stamp.mtime_ns)
                return error.CapturedWriterAuditMismatch;
            }
        }
        category_identity = actual;
        try writeDiagnosticJson(io, a, output_root, "category-source-context.json", .{
            .enabled = true, .dump = input, .identity = identity_file,
            .capture = request.capture_receipt, .page_index_size = page_index.bytes.len,
            .original_source_identity = snapshot.value.source, .current_source_identity = actual.source,
            .source_relocation = request.source_relocation, .source_index_rebase = request.source_index_rebase,
            .original_index_offset = request.page.index_offset, .current_index_offset = selected_offset,
            .original_ordinal = request.page.ordinal, .current_ordinal = selected_ordinal,
            .original_source_receipt_preserved = request.source_index_rebase == null,
            .owner_semantic_acceptance = false,
        }, 64 * 1024);
    }
    stage.* = "language-loader";
    stage.* = "site-profile-loader";
    if (shared == null or !shared.?.namespace_ready) {
        errdefer if (shared) |value| { value.failed_loader = true; };
        const site_mainpage = try loadSiteMainPage(io, a, root, namespaces);
        defer if (site_mainpage) |site| a.free(site.title);
        try loadManualAutomaticIdentity(io, a, root, namespaces, page_index.bytes, titles);
        if (shared) |value| { try value.inputs.verify(); value.namespace_ready = true; }
    }
    stage.* = "language-loader";
    const language_root = request.language_registry_root orelse root;
    try writeDiagnosticJson(io, a, output_root, "normal-loader-selection.json", .{
        .original_expander_root = root, .language_registry_root = language_root,
        .derived_registry_manifest = request.language_registry_manifest,
        .derived_registry_lineage = request.language_registry_lineage,
        .manual_conversion_context = namespaces.manual_conversion_context,
    }, 64 * 1024);
    var local_registry: ?language_registry.Registry = null;
    defer if (local_registry) |*value| value.deinit();
    const registry: *language_registry.Registry = if (shared) |value| try value.language(io, language_root, namespaces) else reg: {
        local_registry = try loadLanguageRegistry(io, a, language_root, namespaces);
        break :reg &local_registry.?;
    };
    stage.* = "behavior-loader";
    const behavior_path = try std.fs.path.join(a, &.{ root, "behavior-switches.tsv" });
    const behavior_bytes = std.Io.Dir.cwd().readFileAlloc(io, behavior_path, a, .limited(1024 * 1024)) catch |err| switch (err) { error.FileNotFound => null, else => return err };
    defer if (behavior_bytes) |value| a.free(value);
    var behavior: ?namespace_registry.behavior_switches.Registry = if (behavior_bytes) |value| try namespace_registry.behavior_switches.Registry.init(a, value, namespaces.wiki, namespaces.dump_date, namespaces.content_language, namespaces.source_sha256) else null;
    defer if (behavior) |*value| value.deinit();
    stage.* = "image-loader";
    const image_path = try std.fs.path.join(a, &.{ root, "image-options.tsv" });
    const image_bytes = std.Io.Dir.cwd().readFileAlloc(io, image_path, a, .limited(1024 * 1024)) catch |err| switch (err) { error.FileNotFound => null, else => return err };
    defer if (image_bytes) |value| a.free(value);
    if (image_bytes != null and behavior_bytes == null) return error.ImageIdentityMismatch;
    var behavior_digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(behavior_bytes orelse "", &behavior_digest, .{});
    var images: ?namespace_registry.image_options.Registry = if (image_bytes) |value| try namespace_registry.image_options.Registry.init(a, value, namespaces.wiki, namespaces.dump_date, namespaces.content_language, namespaces.source_sha256, behavior_digest) else null;
    defer if (images) |*value| value.deinit();
    const figure_site = try loadWriterFigureSite(io, a, root, request.figure_input_root, namespaces);
    var local_anchor_inputs: ?source_internal_link.Inputs = null;
    defer if (local_anchor_inputs) |*value| value.deinit();
    const anchor_inputs: ?*const source_internal_link.Inputs = if (shared) |value|
        try value.sourceAnchors(io, root, request.figure_input_root, namespaces, figure_site)
    else loaded: {
        local_anchor_inputs = if (figure_site) |site| try loadSourceAnchorInputs(io, a, root, request.figure_input_root, namespaces, site) else null;
        break :loaded if (local_anchor_inputs) |*value| value else null;
    };
    const anchor_provider = if (anchor_inputs) |value| value.provider(namespaces, page_index.bytes, titles) else null;
    var local_sizing: ?figure_sizing.Registry = null;
    defer if (local_sizing) |*value| value.deinit();
    const sizing_authority: ?*figure_sizing.Registry = if (shared) |value| try value.writerFigures(io, root, request.figure_input_root, namespaces, figure_site) else sizing: {
        local_sizing = try loadWriterFigureSizing(io, a, root, request.figure_input_root, namespaces, figure_site);
        break :sizing if (local_sizing) |*value| value else null;
    };
    var page_languages = try loadPageLanguage(io, a, root, namespaces); defer page_languages.deinit();
    const observations_path = try capturedWriterObservationPath(request, captured.origin, a);
    defer a.free(observations_path);
    try writeDiagnosticJson(io, a, output_root, "normal-book-selection.json", .{
        .original_expander_root = root,
        .original_figure_page_observations_snapshot = captured.origin.figure_page_observations_snapshot,
        .audit_replacement_root = request.figure_page_observations_root,
        .selected_snapshot = observations_path,
    }, 64 * 1024);
    var page_observations = try loadFigurePageObservationsAt(io, a, observations_path,
        captured.origin.figure_page_observations_snapshot != null or request.figure_page_observations_root != null,
        captured_writer_inputs, namespaces, if (sizing_authority) |value| value else null, figure_site);
    defer if (page_observations) |*value| value.deinit();
    if (request.figure_page_observations_root != null and page_observations == null) return error.CapturedWriterFileMissing;
    var codes = languageCodes(registry, namespaces);
    codes.behavior_switches = if (behavior) |*value| value else null;
    codes.image_options = if (images) |*value| value else null;
    codes.figure_sizing = if (sizing_authority) |value| .{ .ctx = value, .resolve_fn = figure_sizing.Registry.resolve,
        .resolve_canonical_file_fn = figure_sizing.Registry.resolveCanonicalFile,
        .resolve_svg_explicit_box_fn = figure_sizing.Registry.resolveSvgExplicitBox,
        .resolve_height_only_width_fn = figure_sizing.Registry.resolveHeightOnlyWidth,
        .resolve_width_limit_fn = figure_sizing.Registry.resolveWidthLimit,
        .resolve_height_occurrence_fn = figure_sizing.Registry.resolveHeightOccurrence } else null;

    if (category_dump != null) {
        category_context = .{ .allocator = a, .registry = registry, .namespace_catalog = namespaces,
            .source = &category_dump.?, .page_index = page_index.bytes, .title_index = titles };
        try category_context.?.installYiddishCategoryHeading(registry);
        codes.source_category_ctx = &category_context.?;
        codes.source_category_fn = source_category_language.Context.callback;
        codes.source_category_agreement_fn = source_category_language.Context.agreementCallback;
        codes.source_category_heading_fn = source_category_language.Context.headingCallback;
    }
    // The ordinary source and its authenticated indexes outlive profile and Writer.
    // These exact captures require the normal source-backed owner/style route.
    if (category_dump == null) return error.MissingCapturedWriterNormalSource;
    stage.* = "table-style-loader";
    const stylesheet_snapshot = try capturedWriterReadStylesheet(io, a, request, captured.origin.stylesheet_imports_snapshot);
    defer if (stylesheet_snapshot) |bytes| a.free(bytes);
    const style_observation = try source_table_styles.observeWithImportsForTarget(a, namespaces, &category_dump.?, page_index.bytes, titles, stylesheet_snapshot, .screen);
    var table_styles = style_observation.authority;
    defer if (table_styles) |*authority| authority.deinit();
    codes.table_styles = if (table_styles) |*authority| &authority.profile else null;
    if (codes.figure_sizing) |*sizing_source| sizing_source.source_context =
        try figureSourceContext(figure_site orelse return error.InvalidFigureSizingSource, style_observation.absence);
    const spec = namespaces.byId(std.math.cast(i32, page.ns) orelse return error.InvalidNamespace) orelse return error.InvalidNamespace;
    const role = compiledKind(spec) orelse return error.CapturedWriterCompileOnlyPage;
    if (!std.mem.eql(u8, @tagName(role), captured.namespace_kind)) return error.CapturedWriterCaptureMismatch;
    const raw_file = try capturedWriterRead(io, a, request.page.raw, 8 * 1024 * 1024);
    const raw = raw_file;
    if (request.source_index_rebase != null) {
        if (!std.mem.eql(u8, page.content_model, "wikitext") or dump_source.sourceLen(page.source) > 64 * 1024 * 1024) return error.CapturedWriterPayloadLimit;
        const source_raw = try category_dump.?.readAlloc(a, page.source); defer a.free(source_raw);
        const decoded = if (page.source_needs_decode) try xml_decode.decodeSinglePassAlloc(a, source_raw) else null;
        defer if (decoded) |value| a.free(value);
        if (!std.mem.eql(u8, raw, decoded orelse source_raw)) return error.CapturedWriterRebasedRawMismatch;
    }
    const expanded: bundle_expander.Expansion = .{
        .source = try capturedWriterRead(io, a, request.page.expanded, 8 * 1024 * 1024),
        .display_title = try capturedWriterOptional(io, a, request.page.display_title),
        .poem_metadata = try capturedWriterOptional(io, a, request.page.poem_metadata),
        .missing_dependency_metadata = try capturedWriterOptional(io, a, request.page.missing_dependency_metadata),
        .unsupported_parser_function = request.page.unsupported_parser_function,
    };
    if (codes.figure_sizing) |*sizing| {
        if (std.math.cast(i32, page.ns)) |page_language_namespace| {
            sizing.page_language = capturedPageLanguage(&page_languages, page.page_id, page.revision_id, page_language_namespace, page.title, raw, expanded.source,
                .{ .source_core_revision = if (figure_site) |site| site.core_revision else null, .normal_no_target = true, .interface_message = false });
        }
    }
    if (anchor_provider) |*provider| codes.local_link_targets = try provider.bindTargets(a, expanded.source);
    try attachFigurePageObservation(a, &codes, if (page_observations) |*value| value else null,
        if (figure_site) |site| site.source_sha256 else null, std.math.cast(i32, page.ns) orelse return error.InvalidNamespace,
        page.page_id, page.revision_id, page.title, raw, expanded.source);
    if (figure_inputs) |inputs| try inputs.verify();
    stage.* = "writer-init";
    const data_root = try std.fs.path.join(a, &.{ output_root, "data" });
    var writer = try encoder.blob_builder.Writer.init(io, a, data_root);
    defer writer.deinit();
    writer.language_codes = codes;
    writer.stats.pages_seen = 1;
    try writer.namespace_coverage.input(a, page.ns, spec.name, role, page.has_source);
    const before = writer.stats.fallback_pages;
    stage.* = "writer-add-strict-presentation";
    // This is the exact ordinary consumer, including reason/phase handling and
    // Writer-owned strict semantic validation. No audit swallowing of errors.
    _ = try consumeExpandedPage(&writer, .{
        .ordinal = selected_ordinal, .index_offset = selected_offset,
        .ns = .{ .id = page.ns, .kind = role }, .title = page.title,
        .source = raw, .page_id = page.page_id, .revision_id = page.revision_id,
        .index_line = line,
    }, expanded, a, null);
    try writer.namespace_coverage.outcome(page.ns, if (writer.stats.fallback_pages != before) .fallback else .expanded);
    stage.* = "writer-finish";
    const stats = try writer.finish(codes);
    if (figure_inputs) |inputs| try inputs.verify();
    stage.* = "stored-export-and-codec";
    const records = try capturedWriterExportCurrent(io, a, output_root, request.page.title);
    try capturedWriterRequireRecords(records.len);
    stage.* = "input-reauthentication";
    try captured_writer_inputs.?.verify();
    if (category_dump) |*value| {
        const actual = try capturedWriterSourceSnapshot(io, a, request, try capturedWriterSourceFileIdentity(value.file), dump_source.pageIndexKind(page_index.bytes), namespaces.source_sha256);
        if (!std.meta.eql(category_identity.?, actual)) return error.CapturedWriterSourceContextMismatch;
    }
    try writeDiagnosticJson(io, a, output_root, "writer-stats.json", stats, 64 * 1024);
    try captured_writer_inputs.?.exportRecords(output_root);
}


// Retained-page diagnostic Stored export. This is a loader/export
// helper only; it never reconstructs or manually serializes presentation fields.
const CapturedWriterCurrentStored = struct {
    const e = @import("encoder");
    const A = std.mem.Allocator;
    const Stored = e.presentation_types.Stored;
    const Kind = e.blob_format.BlobKind;

    pub const Record = struct {
        owner: []const u8,
        kind: Kind,
        title: []const u8,
        language: ?e.blob_format.LanguageMetadata,
        blob_record_count: usize,
        stored: Stored,
    };

    fn completeStoredJson(a: A, stored: Stored) ![]u8 {
        var json: std.Io.Writer.Allocating = .init(a);
        errdefer json.deinit();
        try std.json.Stringify.value(stored, .{}, &json.writer);
        return json.toOwnedSlice();
    }

    pub fn decodeRecord(a: A, blob: e.blob_format.BlobView, record: e.blob_format.RecordView) !Stored {
        const language = if (blob.kind == .language) try blob.languageMetadata() else null;
        const stored = try e.presentation_codec.decodeAlloc(a, record.payload, record.title, blob.kind, language);
        const encoded = try e.presentation_codec.encodeAlloc(a, stored);
        defer a.free(encoded);
        if (!std.mem.eql(u8, encoded, record.payload)) return error.CodecRoundtripMismatch;
        const again = try e.presentation_codec.decodeAlloc(a, encoded, record.title, blob.kind, language);
        const original_json = try completeStoredJson(a, stored);
        defer a.free(original_json);
        const roundtrip_json = try completeStoredJson(a, again);
        defer a.free(roundtrip_json);
        if (!std.mem.eql(u8, original_json, roundtrip_json)) return error.CodecRoundtripMismatch;
        return stored;
    }

    fn addBlob(io: std.Io, a: A, path: []const u8, owner: []const u8, expected_kind: Kind, expected_heading: ?[]const u8, title: []const u8, optional: bool, out: *std.ArrayList(Record)) !void {
        const bytes = std.Io.Dir.cwd().readFileAlloc(io, path, a, .limited(256 * 1024 * 1024)) catch |err| {
            if (optional and err == error.FileNotFound) return;
            return err;
        };
        const blob = try e.blob_format.inspect(bytes);
        if (blob.kind != expected_kind) return error.BlobKindMismatch;
        try blob.validate();
        const language = if (blob.kind == .language) try blob.languageMetadata() else null;
        if (expected_heading) |heading| {
            if (language == null or !std.mem.eql(u8, heading, language.?.heading)) return error.CatalogOwnerMismatch;
        }
        var index = try blob.buildTrustedIndexAlloc(a);
        defer index.deinit(a);
        if (try index.find(title)) |record| {
            if (blob.kind == .alias) return error.SelectedAliasRequiresAliasCodec;
            if (!std.mem.eql(u8, record.title, title)) return error.SelectedTitleMismatch;
            try out.append(a, .{
                .owner = owner,
                .kind = blob.kind,
                .title = record.title,
                .language = language,
                .blob_record_count = index.recordCount(),
                .stored = try decodeRecord(a, blob, record),
            });
        }
    }

    // `a` must retain all loaded blob/catalog bytes and decoded slices until the
    // caller finishes using the returned records; the capture tests use an arena.
    pub fn load(io: std.Io, a: A, data_root: []const u8, title: []const u8) ![]Record {
        var out: std.ArrayList(Record) = .empty;
        errdefer out.deinit(a);
        const catalog_path = try std.fs.path.join(a, &.{ data_root, e.blob_catalog.manifest_filename });
        const catalog = try std.Io.Dir.cwd().readFileAlloc(io, catalog_path, a, .limited(16 * 1024 * 1024));
        var seen: std.StringHashMap(void) = .init(a);
        defer seen.deinit();
        var iterator = try e.blob_catalog.Iterator.init(catalog);
        while (try iterator.next()) |owner| {
            const slot = try seen.getOrPut(owner.heading);
            if (slot.found_existing) return error.DuplicateCatalogOwner;
            var filename: [e.blob_catalog.language_blob_filename_len]u8 = undefined;
            try addBlob(io, a, try std.fs.path.join(a, &.{ data_root, e.blob_catalog.language_directory, e.blob_catalog.languageBlobFilename(owner.heading, &filename) }), owner.heading, .language, owner.heading, title, false, &out);
        }
        for (std.meta.tags(Kind)) |kind| {
            if (kind == .language) continue;
            const filename = e.blob_catalog.featureBlobFilename(kind) orelse return error.InvalidFeatureBlobKind;
            try addBlob(io, a, try std.fs.path.join(a, &.{ data_root, filename }), filename, kind, null, title, true, &out);
        }
        std.mem.sort(Record, out.items, {}, struct {
            fn less(_: void, left: Record, right: Record) bool {
                if (left.kind != right.kind) return @backingInt(left.kind) < @backingInt(right.kind);
                return std.mem.order(u8, left.owner, right.owner) == .lt;
            }
        }.less);
        return out.toOwnedSlice(a);
    }
};

// Called after ordinary Writer.finish and before terminal diagnostic success.
// Complete Stored export precedes every capture-specific semantic assertion.
fn capturedWriterExportCurrent(io: std.Io, a: std.mem.Allocator, output_root: []const u8, title: []const u8) ![]CapturedWriterCurrentStored.Record {
    const records = try CapturedWriterCurrentStored.load(io, a, try std.fs.path.join(a, &.{ output_root, "data" }), title);
    var json: std.Io.Writer.Allocating = .init(a);
    defer json.deinit();
    try std.json.Stringify.value(.{
        .schema = "wikidict.captured-current-stored.v1",
        .selected_title = title,
        .full_export = records.len != 0,
        .codec_roundtrip = records.len != 0,
        .semantic_acceptance = false,
        .records = records,
    }, .{ .whitespace = .indent_2 }, &json.writer);
    try json.writer.writeByte('\n');
    try std.Io.Dir.cwd().writeFile(io, .{
        .sub_path = try std.fs.path.join(a, &.{ output_root, "complete-stored-records.json" }),
        .data = json.written(),
    });
    return records;
}

const CapturedWriterAuditIdentity = struct { bytes: u64, sha256: []const u8 };
const CapturedWriterAuditCapture = struct {
    inputs: CapturedWriterFile,
    summary: CapturedWriterFile,
    row_offset: usize,
    row_bytes: usize,
    row_sha256: []const u8,
    producer: CapturedWriterAuditIdentity,
    dump: CapturedWriterAuditIdentity,
};
const CapturedWriterAuditStamp = struct { device_major: u32, device_minor: u32, inode: u64, size: u64, mtime_ns: i128 };
const CapturedWriterAuditInputs = struct {
    schema: []const u8,
    context: struct {
        dump_path: []const u8, expander_root: []const u8, tool_path: []const u8,
        figure_input_root: ?[]const u8 = null,
        figure_page_observations_snapshot: ?[]const u8 = null,
        stylesheet_imports_snapshot: ?[]const u8 = null,
        start_page: u64, requested_limit: ?u64, index_byte_offset: ?u64,
    },
    files: []const struct {
        path: []const u8,
        identity: ?CapturedWriterAuditStamp,
        sha256: ?[]const u8,
    },
};
const CapturedWriterAuditSummary = struct {
    schema: []const u8, diagnostic_only: bool, inventory_complete: bool,
    range_complete: bool, expansion_complete: bool, failure_index_complete: bool,
    semantic_acceptance: bool, publication_created: bool, error_name: ?[]const u8,
    audit_scope: []const u8, start_page: u64, requested_limit: ?u64,
    selected_end_exclusive: u64, selected: u64, dispatched: u64, consumed: u64,
    skipped: u64, direct_aliases: u64, expansion_input_failures: u64,
    expansion_fallbacks: u64, compile_attempts: u64, succeeded: u64,
    failed: u64, failure_records: u64, presentation_failures: u64, report_bytes: u64,
};
const CapturedWriterAuditRow = struct {
    schema: []const u8, error_name: []const u8, ordinal: u64, index_offset: u64,
    namespace: u32, namespace_kind: []const u8, page_id: u64, revision_id: u64,
    title: []const u8, title_bytes: usize, title_truncated: bool, title_sha256: []const u8,
    alias: bool, unsupported_parser_function: bool,
    raw_source: AuditPayload, expanded: AuditPayload, display_title: AuditPayload,
    poem_metadata: AuditPayload, missing_dependency_metadata: AuditPayload,
    index_row: AuditPayload, alias_record: AuditPayload,
};
fn capturedWriterAuditSelectedLine(a: std.mem.Allocator, bytes: []const u8, audit: CapturedWriterAuditCapture) ![]const u8 {
    if (audit.row_bytes == 0 or audit.row_offset >= bytes.len or audit.row_bytes > bytes.len - audit.row_offset or
        (audit.row_offset != 0 and bytes[audit.row_offset - 1] != '\n')) return error.CapturedWriterAuditMismatch;
    const end = audit.row_offset + audit.row_bytes;
    if (end < bytes.len and bytes[end] != '\n') return error.CapturedWriterAuditMismatch;
    const line = bytes[audit.row_offset..end];
    if (std.mem.indexOfScalar(u8, line, '\n') != null) return error.CapturedWriterAuditMismatch;
    const hash = try auditHash(a, line); defer a.free(hash);
    if (!std.mem.eql(u8, hash, audit.row_sha256)) return error.CapturedWriterAuditMismatch;
    return line;
}
fn capturedWriterJoinAudit(a: std.mem.Allocator, request: CapturedWriterRequest, inputs: CapturedWriterAuditInputs,
    summary: CapturedWriterAuditSummary, row: CapturedWriterAuditRow) !void
{
    const audit = request.audit_capture orelse return error.CapturedWriterAuditMismatch;
    if (!std.mem.eql(u8, request.schema, "wikidict.captured-writer.request.v3") or
        !std.mem.eql(u8, inputs.schema, "wikidict.presentation-audit.inputs.v1") or
        !std.mem.eql(u8, summary.schema, "wikidict.presentation-audit.summary.v1") or
        !std.mem.eql(u8, row.schema, "wikidict.presentation-audit.failure.v1") or
        !summary.diagnostic_only or summary.publication_created or summary.semantic_acceptance or
        !summary.range_complete or !summary.expansion_complete or !summary.failure_index_complete or
        summary.error_name != null or summary.expansion_input_failures != 0 or summary.expansion_fallbacks != 0 or
        summary.failed == 0 or summary.failed != summary.failure_records or summary.presentation_failures != summary.failed or
        summary.report_bytes != request.capture_receipt.bytes or summary.dispatched != summary.consumed or
