const CapturedWriterAuthenticatedCapture = struct {
    origin: CapturedWriterSourceOrigin, namespace_kind: []const u8, audit_dump: ?CapturedWriterAuditStamp,
    fn deinit(self: @This(), a: std.mem.Allocator) void {
        a.free(self.origin.dump_path); a.free(self.origin.expander_root);
        if (self.origin.figure_input_root) |root| a.free(root);
        if (self.origin.figure_page_observations_snapshot) |path| a.free(path);
        if (self.origin.stylesheet_imports_snapshot) |path| a.free(path);
        a.free(self.namespace_kind);
    }
};
fn capturedWriterOwnCapture(a: std.mem.Allocator, origin: CapturedWriterSourceOrigin, kind: []const u8, stamp: ?CapturedWriterAuditStamp) !CapturedWriterAuthenticatedCapture {
    const dump_path = try a.dupe(u8, origin.dump_path); errdefer a.free(dump_path);
    const root = try a.dupe(u8, origin.expander_root); errdefer a.free(root);
    const figure_root = if (origin.figure_input_root) |path| try a.dupe(u8, path) else null;
    errdefer if (figure_root) |path| a.free(path);
    const book = if (origin.figure_page_observations_snapshot) |path| try a.dupe(u8, path) else null;
    errdefer if (book) |path| a.free(path);
    const stylesheet = if (origin.stylesheet_imports_snapshot) |path| try a.dupe(u8, path) else null;
    errdefer if (stylesheet) |path| a.free(path);
    return .{ .origin = .{ .dump_path = dump_path, .expander_root = root, .figure_input_root = figure_root, .figure_page_observations_snapshot = book, .stylesheet_imports_snapshot = stylesheet }, .namespace_kind = try a.dupe(u8, kind), .audit_dump = stamp };
}
fn capturedWriterReadStylesheet(io: std.Io, a: std.mem.Allocator, request: CapturedWriterRequest, selected: ?[]const u8) !?[]const u8 {
    if (selected) |path| {
        if (!std.fs.path.isAbsolute(path)) return error.InvalidCapturedWriterPath;
        return try capturedWriterRead(io, a, try capturedWriterDependency(request, path), 2 * 1024 * 1024);
    }
    const path = try std.fs.path.join(a, &.{ request.expander_root, "stylesheet-imports.json" });
    defer a.free(path);
    std.Io.Dir.cwd().access(io, path, .{}) catch |err| switch (err) {
        error.FileNotFound => {
            try capturedWriterRequireSourceAbsence(request, path);
            return null;
        },
        else => return err,
    };
    return try capturedWriterRead(io, a, try capturedWriterDependency(request, path), 2 * 1024 * 1024);
}
fn capturedWriterObservationRoot(request: CapturedWriterRequest, a: std.mem.Allocator) ![]const u8 {
    const root = request.figure_page_observations_root orelse return request.expander_root;
    if (!std.mem.eql(u8, request.schema, "wikidict.captured-writer.request.v3") or request.audit_capture == null or !std.fs.path.isAbsolute(root))
        return error.InvalidCapturedWriterObservationRoot;
    const path = try std.fs.path.join(a, &.{ root, figure_page_observations.filename }); defer a.free(path);
    try capturedWriterRequireSourceDependency(request, path);
    return root;
}
// The original Book selector is receipt authority, not an optional request
// hint. A separate v3 audit replacement retains its existing explicit contract.
fn capturedWriterObservationPath(request: CapturedWriterRequest, origin: CapturedWriterSourceOrigin, a: std.mem.Allocator) ![]const u8 {
    if (origin.figure_page_observations_snapshot) |path| {
        if (!std.fs.path.isAbsolute(path)) return error.InvalidCapturedWriterObservationRoot;
        try capturedWriterRequireSourceDependency(request, path);
    }
    if (request.figure_page_observations_root != null) {
        const root = try capturedWriterObservationRoot(request, a);
        return std.fs.path.join(a, &.{ root, figure_page_observations.filename });
    }
    if (origin.figure_page_observations_snapshot) |path| return a.dupe(u8, path);
    return std.fs.path.join(a, &.{ request.expander_root, figure_page_observations.filename });
}

fn capturedWriterAuthenticatedOrigin(io: std.Io, a: std.mem.Allocator, request: CapturedWriterRequest) !CapturedWriterAuthenticatedCapture {
    return capturedWriterAuthenticatedOriginWithShared(io, a, request, null);
}

fn capturedWriterAuthenticatedOriginWithShared(io: std.Io, a: std.mem.Allocator, request: CapturedWriterRequest, shared: ?*CapturedWriterSharedInputs) !CapturedWriterAuthenticatedCapture {
    if (request.audit_capture) |audit| {
        const parent = std.fs.path.dirname(request.capture_receipt.path) orelse return error.CapturedWriterAuditMismatch;
        if (!std.mem.eql(u8, std.fs.path.basename(request.capture_receipt.path), "failures.jsonl")) return error.CapturedWriterAuditMismatch;
        const input_path = try std.fs.path.join(a, &.{ parent, "audit-inputs.json" }); defer a.free(input_path);
        const summary_path = try std.fs.path.join(a, &.{ parent, "audit-summary.json" }); defer a.free(summary_path);
        if (!std.mem.eql(u8, input_path, audit.inputs.path) or !std.mem.eql(u8, summary_path, audit.summary.path)) return error.CapturedWriterAuditMismatch;
        const index_bytes = try capturedWriterRead(io, a, request.capture_receipt, 64 * 1024 * 1024); defer a.free(index_bytes);
        const line = try capturedWriterAuditSelectedLine(a, index_bytes, audit);
        const row = try std.json.parseFromSlice(CapturedWriterAuditRow, a, line, .{ .ignore_unknown_fields = true }); defer row.deinit();
        var local_inputs_bytes: ?[]const u8 = null;
        defer if (local_inputs_bytes) |value| a.free(value);
        var local_inputs: ?std.json.Parsed(CapturedWriterAuditInputs) = null;
        defer if (local_inputs) |*value| value.deinit();
        const inputs: CapturedWriterAuditInputs = if (shared) |value| try value.audit(io, audit.inputs) else input: {
            local_inputs_bytes = try capturedWriterRead(io, a, audit.inputs, 64 * 1024 * 1024);
            local_inputs = try std.json.parseFromSlice(CapturedWriterAuditInputs, a, local_inputs_bytes.?,
                .{ .ignore_unknown_fields = true });
            break :input local_inputs.?.value;
        };
        const summary_bytes = try capturedWriterRead(io, a, audit.summary, 64 * 1024); defer a.free(summary_bytes);
        const summary = try std.json.parseFromSlice(CapturedWriterAuditSummary, a, summary_bytes, .{ .ignore_unknown_fields = true }); defer summary.deinit();
        try capturedWriterJoinAudit(a, request, inputs, summary.value, row.value);
        if (index_bytes.len == 0 or index_bytes[index_bytes.len - 1] != '\n' or
            std.mem.indexOf(u8, index_bytes, "\n\n") != null or std.mem.count(u8, index_bytes, "\n") != summary.value.failure_records)
            return error.CapturedWriterAuditMismatch;
        var dump_stamp: ?CapturedWriterAuditStamp = null;
        for (inputs.files) |file| if (std.mem.eql(u8, file.path, inputs.context.dump_path)) { dump_stamp = file.identity; };
        // The historical /proc/self/exe record is data. Never open that path as
        // though it still named the producer of this original audit.
        return capturedWriterOwnCapture(a, .{ .dump_path = inputs.context.dump_path, .expander_root = inputs.context.expander_root, .figure_input_root = inputs.context.figure_input_root, .figure_page_observations_snapshot = inputs.context.figure_page_observations_snapshot, .stylesheet_imports_snapshot = inputs.context.stylesheet_imports_snapshot }, row.value.namespace_kind, dump_stamp);
    }
    const receipt_bytes = try capturedWriterRead(io, a, request.capture_receipt, 2 * 1024 * 1024); defer a.free(receipt_bytes);
    const receipt = try std.json.parseFromSlice(CapturedWriterReceipt, a, receipt_bytes, .{ .ignore_unknown_fields = true }); defer receipt.deinit();
    try capturedWriterJoinReceipt(a, request, receipt.value);
    return capturedWriterOwnCapture(a, receipt.value.input, receipt.value.namespace_kind, null);
}

const CapturedWriterReceipt = struct {
    schema: []const u8,
    record_complete: bool,
    diagnostic_only: bool,
    publication_created: bool,
    semantic_acceptance: bool,
    error_name: []const u8,
    ordinal: u64,
    index_offset: u64,
    namespace: u32,
    namespace_kind: []const u8,
    page_id: u64,
    revision_id: u64,
    title: []const u8,
    title_bytes: usize,
    title_truncated: bool,
    title_sha256: []const u8,
    alias: bool,
    unsupported_parser_function: bool,
    input: CapturedWriterSourceOrigin,
    raw_source: AuditPayload,
    expanded: AuditPayload,
    display_title: AuditPayload,
    poem_metadata: AuditPayload,
    missing_dependency_metadata: AuditPayload,
    index_row: AuditPayload,
    alias_record: AuditPayload,
};

fn capturedWriterJoinPayload(actual: AuditPayload, requested: ?CapturedWriterFile, required: bool) !void {
    if (!actual.present) {
        if (required or requested != null or actual.bytes != 0 or actual.retained_bytes != 0 or actual.path != null or actual.sha256 != null or actual.truncated or actual.unretained) return error.CapturedWriterCaptureMismatch;
        return;
    }
    if (actual.truncated or actual.unretained or actual.retained_bytes != actual.bytes) return error.CapturedWriterIncompleteCapture;
    const file = requested orelse return error.CapturedWriterCaptureMismatch;
    if (actual.bytes != file.bytes or !std.mem.eql(u8, actual.sha256 orelse return error.CapturedWriterCaptureMismatch, file.sha256)) return error.CapturedWriterCaptureMismatch;
    if (actual.path) |path| {
        if (!std.mem.eql(u8, path, file.path)) return error.CapturedWriterCaptureMismatch;
    } else if (actual.bytes != 0) return error.CapturedWriterIncompleteCapture;
}

fn capturedWriterJoinReceipt(a: std.mem.Allocator, request: CapturedWriterRequest, capture: CapturedWriterReceipt) !void {
    if (!std.mem.eql(u8, capture.schema, "wikidict.presentation-first-failure.v1") or !capture.record_complete or
        !capture.diagnostic_only or capture.publication_created or capture.semantic_acceptance or capture.alias or capture.title_truncated or
        capture.title_bytes != capture.title.len or capture.page_id != request.page.page_id or capture.revision_id != request.page.revision_id or
        capture.ordinal != request.page.ordinal or capture.index_offset != request.page.index_offset or capture.namespace != request.page.namespace or
        !std.mem.eql(u8, capture.title, request.page.title) or capture.unsupported_parser_function != request.page.unsupported_parser_function or
        capture.error_name.len == 0 or !std.mem.eql(u8, capture.error_name, request.original_error_name) or
        !std.mem.eql(u8, capture.input.expander_root, request.expander_root) or
        !WriterFigureInputs.sameRoot(capture.input.figure_input_root, request.figure_input_root)) return error.CapturedWriterCaptureMismatch;
    const title_hash = try auditHash(a, capture.title);
    defer a.free(title_hash);
    if (!std.mem.eql(u8, title_hash, capture.title_sha256)) return error.CapturedWriterCaptureMismatch;
    // The ordinary failure sink stores ExpansionJob.source after XML decoding.
    if (request.page.raw_encoding != .decoded_wikitext) return error.CapturedWriterRawEncodingMismatch;
    try capturedWriterJoinPayload(capture.raw_source, request.page.raw, true);
    try capturedWriterJoinPayload(capture.expanded, request.page.expanded, true);
    try capturedWriterJoinPayload(capture.display_title, request.page.display_title, false);
    try capturedWriterJoinPayload(capture.poem_metadata, request.page.poem_metadata, false);
    try capturedWriterJoinPayload(capture.missing_dependency_metadata, request.page.missing_dependency_metadata, false);
    try capturedWriterJoinPayload(capture.index_row, request.page.index_row, true);
    try capturedWriterJoinPayload(capture.alias_record, null, false);
    const dump = request.source_category_dump orelse return error.MissingCapturedWriterNormalSource;
    if (!std.mem.eql(u8, capture.input.dump_path, dump.path)) return error.CapturedWriterCaptureMismatch;
}

fn capturedWriterRequireNormalRole(io: std.Io, a: std.mem.Allocator, request: CapturedWriterRequest, root: []const u8, name: []const u8, required: bool) !void {
    const path = try std.fs.path.join(a, &.{ root, name });
    defer a.free(path);
    if (std.Io.Dir.cwd().access(io, path, .{})) |_| {
        try capturedWriterRequireSourceDependency(request, path);
    } else |err| switch (err) {
        error.FileNotFound => {
            if (required) return error.CapturedWriterFileMissing;
            try capturedWriterRequireSourceAbsence(request, path);
        },
        else => return err,
    }
}

fn capturedWriterRequireNormalRoles(io: std.Io, a: std.mem.Allocator, request: CapturedWriterRequest) !void {
    try capturedWriterRequireNormalRole(io, a, request, request.expander_root, "namespace-registry.tsv", true);
    inline for (.{ "interwiki-map.tsv", "behavior-switches.tsv", "image-options.tsv", "namespace-siteinfo.raw.json", "figure-sizing.json", "figure-sizing.raw.json", "figure-sizing.site.json", "figure-siteinfo.raw.json", "figure-page-observations.json", "page-language.json", "page-language.raw.json", "page-language.html" }) |name|
        try capturedWriterRequireNormalRole(io, a, request, request.expander_root, name, false);
    if (request.figure_input_root) |root| {
        if (!std.fs.path.isAbsolute(root)) return error.InvalidCapturedWriterPath;
        inline for (WriterFigureInputs.names ++ [_][]const u8{"site-info.namespace-registry.tsv"}) |name|
            try capturedWriterRequireNormalRole(io, a, request, root, name, true);
        try capturedWriterRequireNormalRole(io, a, request, request.expander_root, "file-metadata.tsv", true);
    }
    const language_root = request.language_registry_root orelse request.expander_root;
    try capturedWriterRequireNormalRole(io, a, request, language_root, "manifest.jsonl", true);
    inline for (.{ "language-registry.tsv", "language-names.tsv", "behavior-switches.tsv" }) |name|
        try capturedWriterRequireNormalRole(io, a, request, language_root, name, false);
    if (request.language_registry_root) |profile| {
        try capturedWriterJoinRegistryDerivation(io, a, request, profile);
        // A normal registry substitution changes only its derived registry. All
        // other loader inputs remain the original retained source identities.
        inline for (.{ "manifest.jsonl", "language-names.tsv", "behavior-switches.tsv", "page-index.tsv", "page-title-index.bin", "template-source.idx", "template-source.bin" }) |name| {
            const original = try std.fs.path.join(a, &.{ request.expander_root, name });
            defer a.free(original);
            const selected = try std.fs.path.join(a, &.{ profile, name });
            defer a.free(selected);
            const left = capturedWriterSourcePathIdentity(io, original) catch |err| switch (err) {
                error.FileNotFound => null,
                else => return err,
            };
            const right = capturedWriterSourcePathIdentity(io, selected) catch |err| switch (err) {
                error.FileNotFound => null,
                else => return err,
            };
            if (!std.meta.eql(left, right)) return error.CapturedWriterRegistryProfileSourceMismatch;
