    const site_file = try CapturedWriterCliTest.put(io, a, root, "namespace-siteinfo.raw.json", try std.json.Stringify.valueAlloc(a, site_value, .{}));
    var dependencies: std.ArrayList(CapturedWriterFile) = .empty;
