    const inline_reference = try std.mem.replaceOwned(u8, a, reference, "<div class=\"rellink\">", "<div class=\"rellink\" style=\"padding-left:1.6em;margin-bottom:.5em\">");
    // Actual joined proof above authenticates the imported leaf. This arm is
    // explicitly a controlled reference, not a restamped capture/snapshot.
    const imported = try std.json.parseFromSlice(struct { @"import": struct { start: usize, end: usize }, resource: struct { css: []const u8, base_url: []const u8 } }, a, snapshot, .{ .ignore_unknown_fields = true }); defer imported.deinit();
    try std.testing.expectEqual(@as(usize, 3), joined.proof.sources.len);
    try std.testing.expect(std.mem.indexOf(u8, css, geometry_declarations).? > imported.value.@"import".end);
    var reference_styles = try encoder.table_style_profile.parseSourcesAlloc(a, &.{
        .{ .css = css_reference[0..imported.value.@"import".start], .base_url = joined.proof.sources[0].base_url },
        .{ .css = imported.value.resource.css, .base_url = imported.value.resource.base_url },
        .{ .css = css_reference[imported.value.@"import".end..], .base_url = joined.proof.sources[2].base_url, .byte_start = imported.value.@"import".end },
    }); defer reference_styles.deinit();

    try std.testing.expect(joined.proof.joined);
    var codes = languageCodes(&registry, &ns); codes.behavior_switches = &behavior; codes.image_options = &images; codes.table_styles = &styles;
    var payloads: [3][]const u8 = undefined; var roots: [3][]const u8 = undefined;
    checkpoint = "normal complete supplemental Writer";
    for ([_][]const u8{ F.source, reference, inline_reference }, 0..) |source, i| {
        codes.table_styles = if (i == 2) &reference_styles else &styles;
        roots[i] = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/pt-embebido67-{d}", .{ tmp.sub_path, i });
        var writer = try encoder.blob_builder.Writer.init(io, a, roots[i]); defer writer.deinit(); writer.language_codes = codes;
        try writer.addExpandedPage(a, .{ .id = 108, .kind = .supplemental }, F.title, source, F.raw, null);
        const stats = try writer.finish(codes);
        try std.testing.expectEqual(@as(usize, 1), stats.supplemental_records);
        try std.testing.expectEqual(@as(usize, 0), stats.language_records);
        try std.testing.expectEqual(@as(usize, 0), stats.language_blobs);
        payloads[i] = try F.payload(a, roots[i]);
    }
    checkpoint = "every saved field and both codec streams";
    try std.testing.expectEqualSlices(u8, payloads[1], payloads[0]);
    try std.testing.expectEqualSlices(u8, payloads[2], payloads[0]);
    try std.testing.expectEqualStrings("DPRI", payloads[0][0..4]);
    const actual = try encoder.presentation_codec.decodeAlloc(a, payloads[0], F.title, .supplemental, null);
    const expected = try encoder.presentation_codec.decodeAlloc(a, payloads[1], F.title, .supplemental, null);
    try std.testing.expectEqualDeep(expected, actual);
    try std.testing.expectEqualSlices(u8, payloads[0], try encoder.presentation_codec.encodeAlloc(a, actual));
    try std.testing.expect(actual.entry.kind == .supplemental and actual.entry.language == null and actual.entry.language_code.len == 0);
    try std.testing.expectEqualStrings(F.title, actual.entry.title);
    // The exact captured Common.css rule applies to this authored header DIV.
    // Its single transparent source box now has distinct physical outer/inner edges.
    try std.testing.expect(actual.entry.sections.len != 0 and actual.entry.sections[0].blocks.len != 0);
    const header = actual.entry.sections[0].blocks[0];
    try std.testing.expect(header.kind == .paragraph and header.depth == 0 and header.table == null);
    const margins = header.style.?.margins.?;
    const padding = header.style.?.padding.?;
    const zero: T.StyleLength = .{ .unit = .px, .value = 0 };
    try std.testing.expectEqualDeep(T.StyleEdges{ .top = zero, .right = zero, .bottom = .{ .unit = .em, .value = 0.5 }, .left = zero }, margins);
    try std.testing.expectEqualDeep(T.StyleEdges{ .top = zero, .right = zero, .bottom = zero, .left = .{ .unit = .em, .value = 1.6 } }, padding);

    var header_text: std.ArrayList(u8) = .empty;
    for (header.spans) |span| {
        try std.testing.expect(span.italic);
        try header_text.appendSlice(a, span.text);
        try header_text.appendSlice(a, span.trail);
    }
    try std.testing.expectEqualStrings("Ver a entrada embebido.", header_text.items);
    try std.testing.expectEqual(@as(usize, 0), actual.entry.references.len);
    try std.testing.expectEqual(@as(usize, 0), actual.entry.media.len);
    var scan: F.Scan = .{}; try scan.spans(a, actual.entry.preamble_spans);
    for (actual.entry.sections) |section| try scan.blocks(a, section.blocks);
    try std.testing.expectEqual(F.actions.len, scan.action_index);
    try std.testing.expectEqual(@as(usize, 40), scan.block_count);
    try std.testing.expectEqual(@as(usize, 131), scan.span_count);
    try std.testing.expectEqual(@as(usize, 1), scan.geometry_count);
    try std.testing.expectEqual(@as(usize, 7), scan.definitions);
    try std.testing.expectEqual(@as(usize, 16), scan.bold_keywords);
    try std.testing.expectEqual(@as(usize, 1), scan.script_name);
    try std.testing.expectEqual(@as(usize, 2), scan.script_angles);
    try std.testing.expectEqual(@as(usize, 1), scan.scope_label);
    for ([_][]const u8{ "Outro método consiste em inocular", "A obra,", "Foi para pilhar os thesoiros", "Theodomiro tinha já desencravado", "Muitas vezes tem acontecido a Naires", "Uma taboa", "A um aceno de D. Leonor", "Num braço de ferro", "O estágio final neste caso", "Na altura do Carbono", "com prováveis bons achados", "Por exemplo, uma amostra de rocha", "corpo do edificio", "Cabe notar que um gerador automático", "O código está integrado e", "O marcador <SCRIPT> informa o navegador web", "provêm estes exemplares da Wesselton Mine", "Thesouro da lingua portugueza", "Desenvolvimento para Web", "JavaScript: Um Guia para Aprender" }) |text|
        try std.testing.expect(std.mem.indexOf(u8, scan.visible.items, text) != null);
    const report_bytes = try std.Io.Dir.cwd().readFileAlloc(io, try std.fs.path.join(a, &.{ roots[0], "fallback-pages.jsonl" }), a, .limited(64 * 1024));
    const report = try std.json.parseFromSlice(struct { namespace: u32, title: []const u8, reasons: []const []const u8 }, a, report_bytes, .{}); defer report.deinit();
    try std.testing.expectEqual(@as(u32, 108), report.value.namespace);
    try std.testing.expectEqualStrings(F.title, report.value.title);
    var unsupported = false;
    for (report.value.reasons) |reason| if (std.mem.eql(u8, reason, "unsupported_element")) { unsupported = true; };
    try std.testing.expect(unsupported);
}

test "Writer plain HTML H1 uses trusted owner without lending unknown or nested headings language authority" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator(); const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    const F = GaHtmlLanguageBoundaryFixture;
    var ns = try namespace_registry.Registry.init(a, F.namespaces); defer ns.deinit();
    const input = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/plain-h1-input", .{tmp.sub_path});
    var registry = try F.load(io, a, input, &ns); defer registry.deinit();
    const codes = languageCodes(&registry, &ns);
    const known = registry.resolveTrusted("Béarla") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("en", known.code);
    try std.testing.expect(registry.resolveTrusted("Unknown label") == null);
    const sources = [_][]const u8{
        "<h1>Béarla</h1>\n===Noun===\n# [[Meaning|meaning]] with ''style''.\n",
        "<h1>Unknown label</h1>\n# [[Meaning|meaning]] with ''style''.\n",
        "<h1>Unknown label</h1>\n# [[Meaning|meaning]] with ''style''.\n{|\n|\n<h1>Béarla</h1>\n[[Nested|nested]]\n|}\n",
        "<h1>Unknown label</h1>\n# [[Meaning|meaning]] with ''style''.\n<ref><h1>Béarla</h1>note</ref><references/>\n",
    };
    for (sources, 0..) |source, i| {
        const title = try std.fmt.allocPrint(a, "plain-h1-{d}", .{i});
        const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/plain-h1-{d}", .{tmp.sub_path, i});
        var writer = try encoder.blob_builder.Writer.init(io, a, root); defer writer.deinit(); writer.language_codes = codes;
        try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, title, source, source, null);
        const stats = try writer.finish(codes);
        try std.testing.expectEqual(@as(usize, 1), stats.language_records);
        const heading = if (i == 0) known.heading else "Unclassified";
        const actual = try F.requiredEntry(io, a, root, heading, title);
        try std.testing.expectEqualStrings(if (i == 0) "en" else "", actual.language_code);
        try std.testing.expectEqualStrings(heading, actual.language.?);
        const full = try F.whole(a, title, source, &ns);
        // Ownership can organize a known leading header; unknown and nested
        // candidates retain the complete original source organization unchanged.
        if (i != 0) try std.testing.expectEqualDeep(full.sections, actual.sections);
        try std.testing.expectEqual(@as(usize, 1), F.targetCount(actual, "Meaning"));
        var italic = false;
        for (actual.sections) |section| for (section.blocks) |block| for (block.spans) |span| {
            if (std.mem.eql(u8, span.text, "style")) { try std.testing.expect(span.italic); italic = true; }
        };
        try std.testing.expect(italic);
        try std.testing.expectEqual(full.media.len, actual.media.len);
        try std.testing.expectEqualDeep(full.references, actual.references);
        const bytes = try encoder.presentation_codec.encodeAlloc(a, .{ .entry = actual });
        const decoded = try encoder.presentation_codec.decodeAlloc(a, bytes, title, .language, .{ .code = if (i == 0) "en" else "", .heading = heading });
        try std.testing.expectEqualDeep(actual, decoded.entry);
        try std.testing.expectEqualSlices(u8, bytes, try encoder.presentation_codec.encodeAlloc(a, decoded));
    }
}

test "normal Writer retained SR current events keeps timestamp conversion signatures complete discussion and codec" {
    const T = encoder.presentation_types;
    const F = struct {
        const title = "Тренутни догађаји";
        const source = @embedFile("testdata/sr-current-events/page.wikitext");
        fn hash(bytes: []const u8, expected: []const u8) !void {
            var digest: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(bytes, &digest, .{});
            try std.testing.expectEqualStrings(expected, &std.fmt.bytesToHex(digest, .lower));
        }
        const targets = [_][]const u8{
            "http://www.metak.com/", "https://web.archive.org/web/20091006220820/http://www.krstarica.com/dictionary/", "http://dict.leo.org",
            "Корисник:Kaster", "User:Саша.Стефановић", "User talk:Саша.Стефановић", "User talk:Саша.Стефановић",
            "Корисник:Dungodung", "Корисник:Dungodung", "Корисник:Dungodung", "Разговор са корисником:Dungodung",
            "Корисник:Kaster", "Корисник:Kaster", "Корисник:Crveni Baron", "Разговор са корисником:Crveni Baron", "Корисник:Crveni Baron", "Разговор са корисником:Crveni Baron",
        };
        const Scan = struct {
            visible: std.ArrayList(u8) = .empty,
            action_index: usize = 0,
            red_small: bool = false,
            blue_small: bool = false,
            gray_small: bool = false,
            blue_bold: usize = 0,
            red_bold: bool = false,
            italic_word: bool = false,
            fn spans(self: *@This(), a: std.mem.Allocator, values: []const T.Span) !void {
                for (values) |span| {
                    errdefer std.debug.print("SR discussion span failure action_index={d} kind={s} text_bytes={d} text_prefix={s} trail_prefix={s} target_prefix={s} scale={any} basis={any} foreground={s} bold={} italic={} small={} code={} role={s} classes_prefix={s}\n", .{
                        self.action_index, @tagName(span.kind), span.text.len, span.text[0..@min(span.text.len, 128)],
                        span.trail[0..@min(span.trail.len, 64)], span.target[0..@min(span.target.len, 256)],
                        span.font_scale, span.font_scale_basis, span.foreground orelse "(none)", span.bold, span.italic,
                        span.small, span.code, @tagName(span.role), span.classes[0..@min(span.classes.len, 64)],
                    });
                    try self.visible.appendSlice(a, span.text); try self.visible.appendSlice(a, span.trail);
                    try std.testing.expect(std.mem.indexOf(u8, span.text, "-{") == null and std.mem.indexOf(u8, span.text, "}-") == null);
                    if (span.kind == .link or span.kind == .external_link) {
                        try std.testing.expect(self.action_index < targets.len);
                        try std.testing.expectEqualStrings(targets[self.action_index], span.target);
                        try std.testing.expect(span.kind == (if (self.action_index < 3) T.InlineKind.external_link else T.InlineKind.link));
                        self.action_index += 1;
                    } else try std.testing.expect(span.kind == .text and span.target.len == 0);
                    if (std.mem.eql(u8, span.text, "Саша") or std.mem.eql(u8, span.text, "Стефа") or std.mem.eql(u8, span.text, "новић")) {
                        const scale = span.font_scale orelse return error.TestUnexpectedResult;
                        try std.testing.expectApproxEqAbs(@as(f32, 0.85), scale, 0.00001);
                        const color = span.foreground orelse return error.TestUnexpectedResult;
                        if (std.mem.eql(u8, span.text, "Саша")) { try std.testing.expect(span.bold); try std.testing.expectEqualStrings("#ff0000", color); self.red_small = true; }
                        if (std.mem.eql(u8, span.text, "Стефа")) { try std.testing.expectEqualStrings("#0000ff", color); self.blue_small = true; }
                        if (std.mem.eql(u8, span.text, "новић")) { try std.testing.expectEqualStrings("#d3d3d3", color); self.gray_small = true; }
                    }
                    if (std.mem.eql(u8, span.text, "Фи") or std.mem.eql(u8, span.text, "ип") or std.mem.eql(u8, span.text, "§")) {
                        try std.testing.expect(span.bold); try std.testing.expectEqualStrings("#0000ff", span.foreground orelse return error.TestUnexpectedResult); self.blue_bold += 1;
                    }
                    if (std.mem.eql(u8, span.text, "л")) { try std.testing.expect(span.bold); try std.testing.expectEqualStrings("#ff0000", span.foreground orelse return error.TestUnexpectedResult); self.red_bold = true; }
                    if (std.mem.eql(u8, span.text, "exciting")) { try std.testing.expect(span.italic); self.italic_word = true; }
                }
            }
            fn debugWitnesses(value: T.Entry) void {
                var shown: usize = 0;
                for (value.sections) |section| for (section.blocks) |block| for (block.spans) |span| {
                    var selected = std.mem.indexOf(u8, span.text, "exciting") != null;
                    for ([_]usize{ 4, 5, 7, 10 }) |target_index| {
                        selected = selected or std.mem.eql(u8, span.target, targets[target_index]);
                    }
                    if (!selected or shown == 12) continue;
                    shown += 1;
                    std.debug.print("SR style witness {d} kind={s} scale={any} color={s} bold={} italic={} text_bytes={d} text_prefix={s} target_prefix={s}\n", .{
                        shown, @tagName(span.kind), span.font_scale, span.foreground orelse "(none)", span.bold, span.italic,
                        span.text.len, span.text[0..@min(span.text.len, 48)], span.target[0..@min(span.target.len, 72)],
                    });
                };
            }
            fn entry(self: *@This(), a: std.mem.Allocator, value: T.Entry) !void {
                try self.spans(a, value.preamble_spans);
                for (value.sections) |section| for (section.blocks) |block| {
                    errdefer std.debug.print("SR discussion block failure kind={s} table={} spans={d}\n", .{ @tagName(block.kind), block.table != null, block.spans.len });
                    try std.testing.expect(block.table == null);
                    try self.spans(a, block.spans);
                };
                try std.testing.expectEqual(@as(usize, 0), value.references.len);
                try std.testing.expectEqual(@as(usize, 0), value.media.len);
            }
        };
    };
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
