                    if (std.mem.eql(u8, span.text, "Hy-աչք.ogg")) self.audio_playback += 1;
                    if (std.mem.eql(u8, span.text, "file")) {
                        self.audio_details += 1;
                        if (span.font_scale) |scale| if (scale == 0.8) { self.audio_small = true; };
                    }
