test "diagnostic audit consumes typed expansion input failures without expanded bodies or publication" {
    const io = std.testing.io;
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const inputs = try auditControlInputs(a, "input-failure-continuation", 1024);
    defer std.Io.Dir.cwd().deleteTree(io, inputs.root) catch {};
    var audit = try PresentationAudit.init(io, a, inputs.audit_root, inputs.context);
    defer audit.deinit();
    var writer = try encoder.blob_builder.Writer.init(io, a, inputs.writer_root);
    defer writer.deinit();
    writer.language_codes = .{ .get_fn = auditControlLanguages, .boundary_fn = auditControlBoundary };
    var completion: std.Io.Event = .unset;
    const raw = "{{#tag:phonos|Listen|file=Fr-poissonnier.ogg}}";
    const index = "42\t270\tpoissonnier\t\t101\t202";
    const job: ExpansionJob = .{ .ordinal = 4659, .index_offset = 77, .ns = .{ .id = 0, .kind = .language }, .title = "poissonnier", .source = raw, .page_id = 101, .revision_id = 202, .index_line = index };
    var slot = PreparedSlotControl.init(io, &completion, job);
    defer slot.arena.deinit();
    inline for (.{ error.FileMetadataSnapshotMissing, error.InterfaceMessageSnapshotMissing, error.LanguageNameSnapshotMissing }) |err| {
        slot.failure = err;
        slot.worker.last_failure = .{ .stage = "expand", .error_name = @errorName(err), .detail = "original worker detail\nnot a provider-query binding" };
        slot.busy = true;
        slot.done.store(true, .release);
        const stats = writer.stats;
        try std.testing.expect(try slot.consumeReady(&writer, &audit));
        try std.testing.expectEqualDeep(stats, writer.stats);
        try std.testing.expect(!slot.busy and !slot.done.load(.acquire));
        try std.testing.expect(slot.worker.last_failure == null);
        try auditControlEmptySpools(&writer);
        // A later ordinary Writer page still compiles after each failed input.
        try std.testing.expect(try consumeExpandedPage(&writer, job, .{ .source = "==English==\n# retained [[later]]" }, a, &audit));
    }
    try std.testing.expect(!try consumeExpandedPage(&writer, job, .{ .source = "[https:// broken" }, a, &audit));
    try auditControlEmptySpools(&writer);
    audit.selected = 7;
    audit.dispatched = 7;
    audit.consumed += 4; // Four direct Writer calls, in addition to three consumed slots.
    try audit.finish(true, true, 7);
    const summary = try auditControlSummary(a, inputs.audit_root);
    try std.testing.expect(summary.object.get("range_complete").?.bool);
    try std.testing.expect(summary.object.get("failure_index_complete").?.bool);
    try std.testing.expect(!summary.object.get("inventory_complete").?.bool);
    try std.testing.expect(!summary.object.get("expansion_complete").?.bool);
    try std.testing.expectEqual(@as(i64, 3), summary.object.get("expansion_input_failures").?.integer);
    try std.testing.expectEqual(@as(i64, 1), summary.object.get("presentation_failures").?.integer);
    try std.testing.expectEqual(@as(i64, 4), summary.object.get("compile_attempts").?.integer);
    try std.testing.expectEqual(@as(i64, 3), summary.object.get("succeeded").?.integer);
    try std.testing.expectEqual(@as(i64, 4), summary.object.get("failed").?.integer);
    try std.testing.expectEqual(@as(i64, 0), summary.object.get("expansion_fallbacks").?.integer);
    const lines = try std.Io.Dir.cwd().readFileAlloc(io, try std.fs.path.join(a, &.{ inputs.audit_root, "failures.jsonl" }), a, .limited(64 * 1024));
    var rows = std.mem.splitScalar(u8, lines, '\n');
    inline for (.{ error.FileMetadataSnapshotMissing, error.InterfaceMessageSnapshotMissing, error.LanguageNameSnapshotMissing }) |err| {
        const row = (try std.json.parseFromSliceLeaky(std.json.Value, a, rows.next().?, .{})).object;
        try std.testing.expectEqualStrings("wikidict.presentation-audit.input-failure.v1", row.get("schema").?.string);
        try std.testing.expectEqualStrings(@errorName(err), row.get("error_name").?.string);
        try std.testing.expectEqual(@as(i64, 4659), row.get("ordinal").?.integer);
        try std.testing.expectEqual(@as(i64, 77), row.get("index_offset").?.integer);
        try std.testing.expectEqual(@as(i64, 101), row.get("page_id").?.integer);
        try std.testing.expectEqual(@as(i64, 202), row.get("revision_id").?.integer);
        try std.testing.expect(!row.get("record_complete").?.bool and !row.get("writer_attempted").?.bool);
        try std.testing.expect(row.get("provider_query").? == .null);
        inline for (.{ "expanded", "display_title", "poem_metadata", "missing_dependency_metadata" }) |field|
            try std.testing.expect(!row.get(field).?.object.get("present").?.bool);
        inline for (.{ "raw_source", "index_row" }, .{ raw, index }) |field, expected| {
            const payload = row.get(field).?.object;
            const retained = try std.Io.Dir.cwd().readFileAlloc(io, payload.get("path").?.string, a, .limited(1024));
            try std.testing.expectEqualStrings(expected, retained);
            try std.testing.expectEqualStrings(try auditControlHash(a, expected), payload.get("sha256").?.string);
        }
        const reply_bytes = try std.Io.Dir.cwd().readFileAlloc(io, row.get("worker_reply").?.object.get("path").?.string, a, .limited(1024));
        const reply = try std.json.parseFromSliceLeaky(bundle_expander.Failure, a, reply_bytes, .{});
        try std.testing.expectEqualStrings("expand", reply.stage);
        try std.testing.expectEqualStrings(@errorName(err), reply.error_name);
        try std.testing.expectEqualStrings("original worker detail\nnot a provider-query binding", reply.detail);
    }
    const last = (try std.json.parseFromSliceLeaky(std.json.Value, a, rows.next().?, .{})).object;
    try std.testing.expectEqualStrings("wikidict.presentation-audit.failure.v1", last.get("schema").?.string);
    try std.testing.expect(last.get("expanded").?.object.get("present").?.bool);
    try std.testing.expectEqualStrings("", rows.next().?);
    try std.testing.expect(rows.next() == null);
    try auditControlNoPublishedFiles(a, inputs.writer_root);
}

test "diagnostic input continuation keeps normal throws mismatched replies and operational failures fatal" {
    const io = std.testing.io;
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const inputs = try auditControlInputs(a, "input-failure-refusals", 0);
    defer std.Io.Dir.cwd().deleteTree(io, inputs.root) catch {};
    var audit = try PresentationAudit.init(io, a, inputs.audit_root, inputs.context);
    defer audit.deinit();
    var writer = try encoder.blob_builder.Writer.init(io, a, inputs.writer_root);
    defer writer.deinit();
    var completion: std.Io.Event = .unset;
    const job: ExpansionJob = .{ .ordinal = 4, .index_offset = 9, .ns = .{ .id = 0, .kind = .language }, .title = "failed request", .source = "raw" };
    var slot = PreparedSlotControl.init(io, &completion, job);
    defer slot.arena.deinit();
    const cases = [_]struct { err: anyerror, reply: ?bundle_expander.Failure, diagnostic: bool }{
        .{ .err = error.FileMetadataSnapshotMissing, .reply = .{ .stage = "expand", .error_name = "FileMetadataSnapshotMissing", .detail = "normal production" }, .diagnostic = false },
        .{ .err = error.InterfaceMessageSnapshotMissing, .reply = .{ .stage = "expand", .error_name = "InterfaceMessageSnapshotMissing", .detail = "normal production" }, .diagnostic = false },
        .{ .err = error.LanguageNameSnapshotMissing, .reply = .{ .stage = "expand", .error_name = "LanguageNameSnapshotMissing", .detail = "normal production" }, .diagnostic = false },
        .{ .err = error.LanguageNameSnapshotMissing, .reply = null, .diagnostic = true },
        .{ .err = error.LanguageNameSnapshotMissing, .reply = .{ .stage = "load", .error_name = "LanguageNameSnapshotMissing", .detail = "wrong stage" }, .diagnostic = true },
        .{ .err = error.FileMetadataSnapshotMissing, .reply = null, .diagnostic = true },
        .{ .err = error.FileMetadataSnapshotMissing, .reply = .{ .stage = "load", .error_name = "FileMetadataSnapshotMissing", .detail = "wrong stage" }, .diagnostic = true },
        .{ .err = error.FileMetadataSnapshotMissing, .reply = .{ .stage = "expand", .error_name = "InterfaceMessageSnapshotMissing", .detail = "wrong type" }, .diagnostic = true },
        .{ .err = error.OutOfMemory, .reply = .{ .stage = "expand", .error_name = "OutOfMemory", .detail = "operational" }, .diagnostic = true },
        .{ .err = error.Timeout, .reply = .{ .stage = "expand", .error_name = "Timeout", .detail = "operational" }, .diagnostic = true },
    };
    for (cases) |case| {
        slot.failure = case.err;
        slot.worker.last_failure = case.reply;
        slot.busy = true;
        slot.done.store(true, .release);
        try std.testing.expectError(case.err, slot.consumeReady(&writer, if (case.diagnostic) &audit else null));
        try std.testing.expect(!slot.busy and slot.worker.last_failure == null);
        try std.testing.expectEqual(@as(usize, 0), audit.failure_records);
        try std.testing.expectEqual(@as(usize, 0), audit.expansion_input_failures);
        try auditControlEmptySpools(&writer);
    }
    audit.abort(error.FileMetadataSnapshotMissing);
    const summary = try auditControlSummary(a, inputs.audit_root);
    try std.testing.expect(!summary.object.get("range_complete").?.bool);
    try auditControlNoPublishedFiles(a, inputs.writer_root);
}

test "diagnostic input records preserve payload caps and propagate report IO and allocation failures" {
    const io = std.testing.io;
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    inline for (.{ error.FileMetadataSnapshotMissing, error.InterfaceMessageSnapshotMissing, error.LanguageNameSnapshotMissing }) |input_error| {
    inline for (.{ "input-payload-cap", "input-report-cap", "input-io", "input-oom" }) |label| {
        const inputs = try auditControlInputs(a, label, 0);
        defer std.Io.Dir.cwd().deleteTree(io, inputs.root) catch {};
        var audit = try PresentationAudit.init(io, a, inputs.audit_root, inputs.context);
        defer audit.deinit();
        const job: ExpansionJob = .{ .ordinal = 0, .index_offset = 0, .ns = .{ .id = 0, .kind = .language }, .title = "raw request", .source = "raw source" };
        const reply: bundle_expander.Failure = .{ .stage = "expand", .error_name = @errorName(input_error), .detail = "exact detail" };
        if (comptime std.mem.eql(u8, label, "input-payload-cap")) {
            audit.payload_bytes = 64 * 1024 * 1024;
            try audit.recordExpansionInputFailure(input_error, job, reply);
            const lines = try std.Io.Dir.cwd().readFileAlloc(io, try std.fs.path.join(a, &.{ inputs.audit_root, "failures.jsonl" }), a, .limited(64 * 1024));
            const row = (try std.json.parseFromSliceLeaky(std.json.Value, a, std.mem.trim(u8, lines, "\n"), .{})).object;
            inline for (.{ "raw_source", "worker_reply" }) |field| {
                try std.testing.expect(row.get(field).?.object.get("unretained").?.bool);
                try std.testing.expect(row.get(field).?.object.get("path").? == .null);
            }
            try std.testing.expectEqual(@as(usize, 64 * 1024 * 1024), audit.payload_bytes);
        } else if (comptime std.mem.eql(u8, label, "input-report-cap")) {
            audit.report_bytes = 256 * 1024 * 1024;
            try std.testing.expectError(error.AuditReportLimitExceeded, audit.recordExpansionInputFailure(input_error, job, reply));
            try std.testing.expectEqual(@as(usize, 0), audit.failure_records);
        } else if (comptime std.mem.eql(u8, label, "input-io")) {
            const path = try std.fs.path.join(a, &.{ inputs.audit_root, "failure-00000001-raw.wikitext" });
            try std.Io.Dir.cwd().createDir(io, path, .default_dir);
            if (audit.recordExpansionInputFailure(input_error, job, reply)) |_| return error.TestUnexpectedResult else |err| {
                try std.testing.expect(err != input_error);
            }
            try std.testing.expectEqual(@as(usize, 0), audit.failure_records);
        } else {
            var fail = std.testing.FailingAllocator.init(a, .{ .fail_index = 0 });
            const original_allocator = audit.allocator;
            audit.allocator = fail.allocator();
            defer audit.allocator = original_allocator;
            try std.testing.expectError(error.OutOfMemory, audit.recordExpansionInputFailure(input_error, job, reply));
            try std.testing.expectEqual(@as(usize, 0), audit.failure_records);
        }
        audit.abort(input_error);
        const summary = try auditControlSummary(a, inputs.audit_root);
        try std.testing.expect(!summary.object.get("range_complete").?.bool);
        try std.testing.expect(!summary.object.get("expansion_complete").?.bool);
    }
    }
}


test "normal page observation caller clears stale selection and owns OOM paths in its page arena" {
    const F = struct {
        fn run(parent: std.mem.Allocator, base: encoder.blob_builder.LanguageCodes, book: *const figure_page_observations.Book,
            defaults: [32]u8, raw: []const u8, source: []const u8) !void
        {
            // Keep actual page-arena ownership, but make its child growth
            // deterministic for exhaustive allocation-failure injection: the
            // backing debug allocator may otherwise resize a node in place.
            var no_resize = std.testing.FailingAllocator.init(parent, .{ .resize_fail_index = 0 });
            var page_arena = std.heap.ArenaAllocator.init(no_resize.allocator());
            defer page_arena.deinit();
            const a = page_arena.allocator();
            var codes = base;
            attachFigurePageObservation(a, &codes, book, defaults, 0, 4075, 3935048, "poliziotto", raw, source) catch |err| {
                try std.testing.expect(codes.figure_sizing.?.page_observation_ctx == null);
                try std.testing.expect(codes.figure_sizing.?.resolve_observed_width_fn == null);
                try std.testing.expect(codes.figure_sizing.?.resolve_anchor_attributes_fn == null);
                try std.testing.expect(codes.figure_sizing.?.ctx == base.figure_sizing.?.ctx);
                return err;
            };
            const selected = codes.figure_sizing.?.page_observation_ctx orelse return error.TestUnexpectedResult;
            const width = codes.figure_sizing.?.resolve_observed_width_fn orelse return error.TestUnexpectedResult;
            try std.testing.expectEqual(@as(?u32, 190), try width(selected, a,
                "Policía Nacional de Panamá - Motorizado scooter 2010.jpg", .thumbnail,
                "thumb|upright|un poliziotto [[panamense]] [[abilitato]] all'[[utilizzo]]  di mezzi motorizzati", 250));
            try std.testing.expect(codes.figure_sizing.?.ctx == base.figure_sizing.?.ctx);
            try attachFigurePageObservation(a, &codes, book, defaults, 0, 4075, 3935048,
                "poliziotto", "changed raw", source);
            try std.testing.expect(codes.figure_sizing.?.page_observation_ctx == null);
            try std.testing.expect(codes.figure_sizing.?.resolve_observed_width_fn == null);
            try std.testing.expect(codes.figure_sizing.?.resolve_anchor_attributes_fn == null);
            try std.testing.expect(codes.figure_sizing.?.ctx == base.figure_sizing.?.ctx);
        }
    };
    var owner_arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer owner_arena.deinit();
    const a = owner_arena.allocator(); const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    const data = @embedFile("testdata/figure-page-observations/it/figure-page-observations.json");
    const raw = @embedFile("testdata/figure-page-observations/it/page.raw.wikitext");
    const namespace_bytes = @embedFile("testdata/figure-page-observations/it/namespace-registry.tsv");
    const site_bytes = @embedFile("testdata/figure-page-observations/it/figure-siteinfo.raw.json");
    var ns = try namespace_registry.Registry.init(a, namespace_bytes); defer ns.deinit();
    var isolated = try namespace_registry.Registry.init(a, namespace_bytes); defer isolated.deinit();
    const site_page = try parseSiteMainPage(a, site_bytes, &isolated);
    try isolated.attachLanguageConversion(site_bytes);
    const site: FigureSite = .{ .source_context = .{ .namespace_sha256 = ns.source_sha256,
        .defaults = isolated.figure_source_defaults orelse return error.TestUnexpectedResult },
        .core_revision = site_page.figure_core_revision orelse return error.TestUnexpectedResult, .source_sha256 = site_page.digest };
    const behavior_bytes = @embedFile("testdata/figure-page-observations/it/behavior-switches.tsv");
    var behavior = try namespace_registry.behavior_switches.Registry.init(a, behavior_bytes, ns.wiki, ns.dump_date, ns.content_language, ns.source_sha256); defer behavior.deinit();
    var images = try namespace_registry.image_options.Registry.init(a, @embedFile("testdata/figure-page-observations/it/image-options.tsv"),
        ns.wiki, ns.dump_date, ns.content_language, ns.source_sha256, figure_page_observations.Testing.hash(behavior_bytes)); defer images.deinit();
    const doc = try figure_page_observations.Testing.document(a, "it");
    var files = try figure_page_observations.Testing.registry(a, &ns, doc); defer files.deinit();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/page-observation", .{tmp.sub_path});
    try std.Io.Dir.cwd().createDirPath(io, root);
    try std.testing.expect((try loadFigurePageObservations(io, a, root, &ns, &files, site)) == null);
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = try std.fs.path.join(a, &.{ root, figure_page_observations.filename }), .data = data });
    var book = (try loadFigurePageObservations(io, a, root, &ns, &files, site)) orelse return error.TestUnexpectedResult;
    defer book.deinit();
    var codes: encoder.blob_builder.LanguageCodes = .{ .namespace_catalog = &ns, .behavior_switches = &behavior, .image_options = &images };
    codes.figure_sizing = .{ .ctx = &files, .resolve_fn = figure_sizing.Registry.resolve, .source_context = site.source_context };
    const source = try figure_page_observations.Testing.source(a, doc);
    try F.run(std.testing.allocator, codes, &book, site.source_sha256, raw, source);
    try std.testing.checkAllAllocationFailures(std.testing.allocator, F.run, .{ codes, &book, site.source_sha256, raw, source });
}

test "normal Writer retained IT poliziotto binds full supplied page upright widths and preserves every owner body action style and codec" {
    const F = struct {
        const T = encoder.presentation_types;
        const title = "poliziotto";
        const raw = @embedFile("testdata/it-poliziotto-observed251/raw.wikitext");
        const source = @embedFile("testdata/it-poliziotto-observed251/expanded.wikitext");
        const original_first = "[[File:Policía Nacional de Panamá - Motorizado scooter 2010.jpg|thumb|upright|";
        const reference_first = "[[File:Policía Nacional de Panamá - Motorizado scooter 2010.jpg|thumb|upright=0.75|";
        const original_last = "[[File:San Marino poliziotto.jpg|thumb|upright|";
        const reference_last = "[[File:San Marino poliziotto.jpg|thumb|upright=0.75|";
        const media_files = [_][]const u8{
            "Flag of Italy.svg", "Open book 01.svg", "Wikipedia-logo.svg", "Hyph abc.svg",
            "Nuvola apps edu languages.svg", "Nuvola kdict glass.svg", "Icona sinonimi.png",
            "Nuvola apps tree.svg", "Gnome-globe.svg", "Nuvola apps bookcase.svg",
            "Wikipedia-logo-v2.svg", "Commons-logo.svg",
            "Policía Nacional de Panamá - Motorizado scooter 2010.jpg", "HH Polizeihauptmeister MZ.jpg", "San Marino poliziotto.jpg",
        };
        fn hash(bytes: []const u8, expected: []const u8) !void {
            var digest: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(bytes, &digest, .{});
            try std.testing.expectEqualStrings(expected, &std.fmt.bytesToHex(digest, .lower));
        }
        fn witness(ok: bool, kind: []const u8, value: []const u8) !void {
            if (!ok) std.debug.print("IT poliziotto observed page missing {s}: {s}\n", .{kind, value});
            try std.testing.expect(ok);
        }
        const Scan = struct {
            text: std.ArrayList(u8) = .empty,
            targets: std.ArrayList([]const u8) = .empty,
            files: std.StringHashMapUnmanaged(T.MediaKind) = .empty,
            owners: std.StringHashMapUnmanaged(void) = .empty,
            figures: usize = 0,
            tables: usize = 0,
            inflections: usize = 0,
            painted: usize = 0,
            references: usize = 0,
            caption_actions: usize = 0,
            definitions: usize = 0,
            bold_headword: bool = false,
            ipa: bool = false,
            fn spans(self: *@This(), a: std.mem.Allocator, values: []const T.Span) !void {
                for (values) |span| {
                    try self.text.appendSlice(a, span.text);
                    try self.text.appendSlice(a, span.trail);
                    if (span.target.len != 0) try self.targets.append(a, span.target);
                    if (span.bold and std.mem.eql(u8, span.text, "poliziotto")) self.bold_headword = true;
                    if (std.mem.eql(u8, span.text, "/poliˈtsjɔtto/")) {
                        try std.testing.expectEqual(@as(?f32, 1.1), span.font_scale);
                        self.ipa = true;
                    }
                }
            }
            fn figure(self: *@This(), a: std.mem.Allocator, value: T.Figure) anyerror!void {
                const image = value.content.image.span.image orelse return error.TestUnexpectedResult;
                const files = [_][]const u8{ "Policía Nacional de Panamá - Motorizado scooter 2010.jpg", "HH Polizeihauptmeister MZ.jpg", "San Marino poliziotto.jpg" };
                const captions = [_][]const u8{ "un poliziotto panamense abilitato all'utilizzo  di mezzi motorizzati", "un poliziotto con il grado di ufficiale", "un poliziotto di San Marino" };
                const widths = [_]u32{190, 250, 190};
                if (self.figures >= files.len) return error.TestUnexpectedResult;
                const index = self.figures; self.figures += 1;
                try std.testing.expectEqualStrings(files[index], image.file);
                try std.testing.expectEqual(T.FigureFormat.thumbnail, value.format);
                try std.testing.expectEqual(T.FigurePlacement.float_right, value.placement);
