    const proof = source_language_banner.categoryLinkedBoundary(F.iu, &ns, null, &registry, "iu") orelse return error.TestUnexpectedResult;
    try registry.addSourceLanguageBoundary("iu", proof);
    try std.testing.expect(registry.matchesSourceLanguageBoundary("iu", proof.heading, 2));
    try std.testing.expect(!registry.matchesSourceLanguageBanner("iu", proof.heading, 2));
    try std.testing.expectEqualStrings("ike-cans", registry.resolve(proof.label).?.code);
    try std.testing.expect(!registry.matchesSourceLanguageBoundary("fr", proof.heading, 2));
    try std.testing.expect(!registry.matchesSourceLanguageBoundary("iu", proof.heading, 3));
    try std.testing.expect(!registry.matchesSourceLanguageBoundary("iu", "other", 2));
    try std.testing.expect(source_language_banner.categoryLinkedBoundary(F.mul, &ns, null, &registry, "mul") == null);
    try std.testing.expect(source_language_banner.categoryLinkedBoundary(F.iu, &ns, null, &registry, "unknown-code") == null);
    for ([_][2][]const u8{
        .{ "__NOEDITSECTION__", "__TOC__" }, .{ "{{NAMESPACE}}", "{{PAGENAME}}" },
        .{ "Category:", ":Category:" }, .{ "|}}</includeonly>", "|visible}}</includeonly>" },
        .{ "</includeonly>", "</includeonly>\nextra" },
    }) |mutation| {
        const changed = try std.mem.replaceOwned(u8, a, F.iu, mutation[0], mutation[1]);
        try std.testing.expect(source_language_banner.categoryLinkedBoundary(changed, &ns, null, &registry, "iu") == null);
    }
    var conflicting = proof; conflicting.heading = "other";
    try registry.addSourceLanguageBoundary("iu", conflicting);
    try std.testing.expect(!registry.matchesSourceLanguageBoundary("iu", proof.heading, 2));
    try registry.addSourceLanguageBoundary("iu", proof);
    try std.testing.expect(!registry.matchesSourceLanguageBoundary("iu", proof.heading, 2));
}

test "Finnish Writer separates exact authored Bwaidoka and Molima category owners" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const io = std.testing.io;
    const ns_source = @embedFile("testdata/fi-jaamerenvoikukat/namespace-registry.tsv");
    const registry_source = "# wikidict-language-registry-v2\n# content-language\tfi\n# mediawiki\nfi\tsuomi\n# iso-639-3\nbwd\tBwaidoka\tbwd\nmox\tMolima\tmox\n";
    // Finnish dump p11163/r3072206 and p11169/r95065. Both are literal wikitext.
    const auna = "==Bwaidoka==\n===Verbi===\n'''auna'''\n#[[haistaa]]\n\n[[Luokka:Bwaidokan sanat-au|na]]";
    const matauta = "==Bwaidoka==\n===Verbi===\n'''matauta'''\n#[[pelätä]]\n\n==Molima==\n===Verbi===\n'''matauta'''\n#[[pelätä]]\n\n[[Luokka:Bwaidokan sanat-ma|tauta]]\n[[Luokka:Moliman sanat-ma|tauta]]";
    var namespaces = try namespace_registry.Registry.init(a, ns_source);
    defer namespaces.deinit();
    var registry = language_registry.Registry.empty(a);
    defer registry.deinit();
    try registry.addTsv(registry_source);
    try std.testing.expect(registry.resolveTrusted("Bwaidoka") == null);
    try std.testing.expect(registry.resolveTrusted("Molima") == null);
    const codes = languageCodes(&registry, &namespaces);
    for (0..4) |variant| {
        var tmp = std.testing.tmpDir(.{});
        defer tmp.cleanup();
        const root = try tmp.dir.realPathFileAlloc(io, ".", a);
        var writer = try encoder.blob_builder.Writer.init(io, a, root);
        defer writer.deinit();
        writer.language_codes = codes;
        const paired = switch (variant) {
            0 => matauta,
            1 => try std.mem.replaceOwned(u8, a, matauta, "sanat-ma|tauta", "sanat-ma|other"),
            2 => try std.mem.replaceOwned(u8, a, matauta, "[[Luokka:Moliman sanat-ma|tauta]]", "<!--[[Luokka:Moliman sanat-ma|tauta]]-->"),
            else => matauta ++ "\n[[Luokka:Bwaidokan sanat-ma|tauta]]",
        };
        // The companion category sort, protected category and duplicate are
        // independently insufficient to split either owner's body.
        try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "matauta", paired, paired, null);
        if (variant == 0) try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "auna", auna, auna, null);
        const stats = try writer.finish(codes);
        try std.testing.expectEqual(@as(usize, if (variant == 0) 3 else 1), stats.language_records);
        if (variant == 0) {
            for ([_][]const u8{ "Bwaidoka", "Molima" }, [_][]const u8{ "bwd", "mox" }) |heading, code| {
                const entry = try GaHtmlLanguageBoundaryFixture.requiredEntry(io, a, root, heading, "matauta");
                try std.testing.expectEqualStrings(code, entry.language_code);
                try std.testing.expectEqual(@as(usize, 1), GaHtmlLanguageBoundaryFixture.targetCount(entry, "pelätä"));
                try std.testing.expectEqual(@as(usize, 2), entry.sections.len);
                try std.testing.expectEqualStrings(heading, entry.sections[0].title);
                const blocks = entry.sections[1].blocks;
                try std.testing.expectEqualStrings("Verbi", entry.sections[1].title);
                try std.testing.expectEqual(@as(usize, 2), blocks.len);
                try std.testing.expect(blocks[0].spans[0].bold);
                try std.testing.expectEqualStrings("matauta", blocks[0].spans[0].text);
                try std.testing.expectEqual(encoder.presentation_types.BlockKind.definition, blocks[1].kind);
                try std.testing.expectEqualStrings("#", blocks[1].list_path);
            }
            const single = try GaHtmlLanguageBoundaryFixture.requiredEntry(io, a, root, "Bwaidoka", "auna");
            try std.testing.expectEqualStrings("bwd", single.language_code);
            try std.testing.expectEqual(@as(usize, 1), GaHtmlLanguageBoundaryFixture.targetCount(single, "haistaa"));
        } else {
            const fallback = try GaHtmlLanguageBoundaryFixture.requiredEntry(io, a, root, "Unclassified", "matauta");
            try std.testing.expectEqual(@as(usize, 2), GaHtmlLanguageBoundaryFixture.targetCount(fallback, "pelätä"));
        }
    }
}

test "retained MT core6c5 normal Figure defaults preserve source and reject foreign or unreviewed identity" {
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator(); const io = std.testing.io;
    const root = try std.Io.Dir.cwd().realPathFileAlloc(io, try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}", .{tmp.sub_path}), a);
    const namespace_bytes = @embedFile("testdata/core6c5/mt-defaults/site-info.namespace-registry.tsv");
    const response_bytes = @embedFile("testdata/core6c5/mt-defaults/site-info.01.raw.json");
    var response_sha: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(response_bytes, &response_sha, .{});
    try std.testing.expectEqualStrings("d212404606e4d0fd7d1f9e8ed30669ebb52d242a89299ba4fd824b9a724f5abc", &std.fmt.bytesToHex(response_sha, .lower));
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = try std.fs.path.join(a, &.{ root, "namespace-registry.tsv" }), .data = namespace_bytes });
    var ns = try namespace_registry.Registry.init(a, namespace_bytes); defer ns.deinit();
    const ns_digest = std.fmt.bytesToHex(ns.source_sha256, .lower);
    const role_path = try std.fs.path.join(a, &.{ root, "figure-siteinfo.raw.json" });
    for (0..4) |mode| {
        var response = try std.json.parseFromSliceLeaky(std.json.Value, a, response_bytes, .{ .allocate = .alloc_always });
        const query = response.object.getPtr("query").?;
        const general = query.object.getPtr("general").?;
        if (mode == 1) try general.object.put(a, "git-hash", .{ .string = "0000000000000000000000000000000000000000" });
        if (mode == 2) try general.object.put(a, "lang", .{ .string = "as" });
        const data = try std.json.Stringify.valueAlloc(a, .{
            .schema = "wikidict.site-info.v2", .wiki = ns.wiki, .date = ns.dump_date,
            .profile = "general-statistics-and-figure-default-options",
            .content_language = ns.content_language,
            .namespace_registry_sha256 = if (mode == 3) "wrong-registry" else ns_digest[0..],
            .query = query.*,
        }, .{});
        try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = role_path, .data = data });
        if (mode == 0) {
            const main_page = try parseSiteMainPage(a, data, &ns);
            try std.testing.expectEqualStrings("6c5fe215cf45da0b1448e7ece41bde087e7ef4e2", main_page.figure_core_revision orelse return error.TestUnexpectedResult);
            const site = (try loadFigureSite(io, a, root, &ns)) orelse return error.TestUnexpectedResult;
            try std.testing.expectEqualStrings("6c5fe215cf45da0b1448e7ece41bde087e7ef4e2", site.core_revision);
            try std.testing.expectEqual(@as(?u32, 250), site.source_context.defaults.default_thumbnail_width);
            try std.testing.expect(!site.source_context.defaults.rtl);
            try std.testing.expect(site.source_context.missing_media_profile == null);
            var expected_sha: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(data, &expected_sha, .{});
            try std.testing.expectEqualSlices(u8, &expected_sha, &site.source_sha256);
        } else if (mode == 1) {
            try std.testing.expectError(error.InvalidFigureSizingSource, loadFigureSite(io, a, root, &ns));
        } else if (mode == 2) {
            try std.testing.expectError(error.InvalidLanguageConversionProfile, loadFigureSite(io, a, root, &ns));
        } else {
            try std.testing.expectError(error.InvalidSiteMainPage, loadFigureSite(io, a, root, &ns));
        }
        try std.testing.expect(ns.figure_source_defaults == null);
        try std.testing.expect(ns.manual_conversion_context == null);
        try std.testing.expect(ns.language_conversion == null);
    }
}

