    const lexical = try std.json.parseFromSliceLeaky(Lexical, a, @embedFile("testdata/roa-rup-static-banner/original-lexical-sections.json"), .{ .ignore_unknown_fields = true });
    for ([_][]const u8{ "num", "adj", "art" }) |token| {
        const provider = lexical.original_pages.map.get(try std.fmt.allocPrint(a, "Format:-{s}-", .{token})).?;
        var digest: [32]u8 = undefined; std.crypto.hash.sha2.Sha256.hash(provider.text, &digest, .{});
        try std.testing.expectEqualStrings(provider.sha256, &std.fmt.bytesToHex(digest, .lower));
        const selected = source_language_banner.roaRupStaticSupportDeclaration(provider.text, &ns, null, token) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(u8, 3), selected.level);
    }
    const source = (try F.support(a)).selected_rows.map.get("Format:-num-").?;
    const proof = source_language_banner.roaRupStaticSupportDeclaration(source.text, &ns, null, "num") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u8, 3), proof.level);
    try std.testing.expectEqualStrings("[[număr|Númir]]", proof.heading);
    for ([_][2][]const u8{
        .{ "[[număr|Númir]]", "[[Niuafo'ou|Niuafo'ou]]" },
        .{ "[[număr|Númir]]", "[[număr#part|Númir]]" },
        .{ "Category:Template|num", "Category:Template|language" },
        .{ "Category:Numări", "Category:Niuafo'ou" },
        .{ "===", "==" },
        .{ "<includeonly>", "<onlyinclude>" },
    }) |mutation| {
        const bad = try std.mem.replaceOwned(u8, a, source.text, mutation[0], mutation[1]);
        try std.testing.expect(source_language_banner.roaRupStaticSupportDeclaration(bad, &ns, null, "num") == null);
    }
    try std.testing.expect(source_language_banner.roaRupStaticSupportDeclaration(source.text, &ns, null, "en") == null);
    const saved_wiki = ns.wiki; ns.wiki = "anotherwiki";
    try std.testing.expect(source_language_banner.roaRupStaticSupportDeclaration(source.text, &ns, null, "num") == null);
    ns.wiki = saved_wiki;
    var registry = language_registry.Registry.empty(a); defer registry.deinit();
    try registry.addTsv(@embedFile("testdata/roa-rup-static-banner/language-registry.tsv"));
    try registry.addSourceStaticSupport("num", proof);
    try std.testing.expect(registry.sourceStaticSupport("num") != null);
    try std.testing.expectEqualStrings("num", registry.resolve("num").?.code);
    try registry.addSourceStaticSupport("num", .{ .heading = "[[other|Other]]", .level = 3 });
    try std.testing.expect(registry.sourceStaticSupport("num") == null);
    try registry.addSourceStaticSupport("num", proof);
    try std.testing.expect(registry.sourceStaticSupport("num") == null);
    var missing = std.testing.tmpDir(.{}); defer missing.cleanup(); const missing_root = try missing.dir.realPathFileAlloc(io, ".", a);
    try F.install(io, a, missing_root);
    var no_provider = try loadLanguageRegistry(io, a, missing_root, &ns); defer no_provider.deinit();
    try std.testing.expect(no_provider.sourceStaticSupport("num") == null);
    const page = try F.row(a, "uno"); const expanded = try F.expanded(a, page.text);
    const output = try std.fs.path.join(a, &.{missing_root, "output"}); const codes = languageCodes(&no_provider, &ns);
    var writer = try encoder.blob_builder.Writer.init(io, a, output); defer writer.deinit(); writer.language_codes = codes;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, page.title, expanded, page.text, null);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 1), stats.language_records);
    const unknown = try GaHtmlLanguageBoundaryFixture.requiredEntry(io, a, output, "Unclassified", page.title);
    try std.testing.expectEqualStrings("", unknown.language_code);
    // Missing support authority retains the complete article, including both
    // source language headings, both numeral headings and both authored links.
    var meanings: usize = 0; var language_headings: usize = 0;
    for (unknown.sections) |section| {
        if (section.level == 1) language_headings += 1;
        for (section.blocks) |block| for (block.spans) |span| if (span.kind == .link and std.mem.eql(u8, span.target, "un")) { meanings += 1; };
    }
    try std.testing.expectEqual(@as(usize, 2), meanings);
    try std.testing.expectEqual(@as(usize, 2), language_headings);
    var duplicate = std.testing.tmpDir(.{}); defer duplicate.cleanup(); const duplicate_root = try duplicate.dir.realPathFileAlloc(io, ".", a);
    try F.installSupport(io, a, duplicate_root, 2);
    try std.testing.expectError(error.DuplicateLanguageTemplateSource, loadLanguageRegistry(io, a, duplicate_root, &ns));
}

test "retained ET coref03 normal Figure defaults preserve source and reject foreign or unreviewed identity" {
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator(); const io = std.testing.io;
    const root = try std.Io.Dir.cwd().realPathFileAlloc(io, try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}", .{tmp.sub_path}), a);
    const namespace_bytes = @embedFile("testdata/et-coref03/defaults/site-info.namespace-registry.tsv");
    const response_bytes = @embedFile("testdata/et-coref03/defaults/site-info.01.raw.json");
    var response_sha: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(response_bytes, &response_sha, .{});
    try std.testing.expectEqualStrings("b84249401613fd677f1c94b130f068c8e9f0ab8e319282e17e2c9b62d24e8839", &std.fmt.bytesToHex(response_sha, .lower));
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = try std.fs.path.join(a, &.{ root, "namespace-registry.tsv" }), .data = namespace_bytes });
    var ns = try namespace_registry.Registry.init(a, namespace_bytes); defer ns.deinit();
    const ns_digest = std.fmt.bytesToHex(ns.source_sha256, .lower);
    const role_path = try std.fs.path.join(a, &.{ root, "figure-siteinfo.raw.json" });
    for (0..4) |mode| {
        var response = try std.json.parseFromSliceLeaky(std.json.Value, a, response_bytes, .{ .allocate = .alloc_always });
        const query = response.object.getPtr("query").?;
        const general = query.object.getPtr("general").?;
        if (mode == 1) try general.object.put(a, "git-hash", .{ .string = "0000000000000000000000000000000000000000" });
        if (mode == 2) try general.object.put(a, "lang", .{ .string = "as" });
        const data = try std.json.Stringify.valueAlloc(a, .{
            .schema = "wikidict.site-info.v2", .wiki = ns.wiki, .date = ns.dump_date,
            .profile = "general-statistics-and-figure-default-options",
            .content_language = ns.content_language,
            .namespace_registry_sha256 = if (mode == 3) "wrong-registry" else ns_digest[0..],
            .query = query.*,
        }, .{});
        try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = role_path, .data = data });
        if (mode == 0) {
            const main_page = try parseSiteMainPage(a, data, &ns);
            try std.testing.expectEqualStrings("f03f1fdaa2d112807b6ce63170eb50e86de615bd", main_page.figure_core_revision orelse return error.TestUnexpectedResult);
            const site = (try loadFigureSite(io, a, root, &ns)) orelse return error.TestUnexpectedResult;
            try std.testing.expectEqualStrings("f03f1fdaa2d112807b6ce63170eb50e86de615bd", site.core_revision);
            try std.testing.expectEqual(@as(?u32, 250), site.source_context.defaults.default_thumbnail_width);
            try std.testing.expect(!site.source_context.defaults.rtl);
            try std.testing.expect(site.source_context.missing_media_profile == null);
            var expected_sha: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(data, &expected_sha, .{});
            try std.testing.expectEqualSlices(u8, &expected_sha, &site.source_sha256);
        } else if (mode == 1) {
            try std.testing.expectError(error.InvalidFigureSizingSource, loadFigureSite(io, a, root, &ns));
        } else if (mode == 2) {
            try std.testing.expectError(error.InvalidLanguageConversionProfile, loadFigureSite(io, a, root, &ns));
        } else {
            try std.testing.expectError(error.InvalidSiteMainPage, loadFigureSite(io, a, root, &ns));
        }
        try std.testing.expect(ns.figure_source_defaults == null);
        try std.testing.expect(ns.manual_conversion_context == null);
        try std.testing.expect(ns.language_conversion == null);
    }
}

test "normal Aragonese Writer separates authored decimal nouns and retains complete paragraph bodies actions and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator(); const io = std.testing.io;
    var ns = try namespace_registry.Registry.init(a, @embedFile("testdata/an-decimal-noun/namespace-registry.tsv")); defer ns.deinit();
    var registry = language_registry.Registry.empty(a); defer registry.deinit();
    try registry.addTsv(@embedFile("testdata/an-decimal-noun/language-registry.tsv"));
    try std.testing.expectEqualStrings("an", registry.resolveTrusted("Aragonés").?.code);
    const codes = languageCodes(&registry, &ns);
    const cases = .{
        .{ "chirmán", @embedFile("testdata/an-decimal-noun/chirman-source.wikitext"), @embedFile("testdata/an-decimal-noun/chirman-separated.wikitext"), &[_]usize{2} },
        .{ "chirmana", @embedFile("testdata/an-decimal-noun/chirmana-source.wikitext"), @embedFile("testdata/an-decimal-noun/chirmana-separated.wikitext"), &[_]usize{2} },
        .{ "calso", @embedFile("testdata/an-decimal-noun/calso-source.wikitext"), @embedFile("testdata/an-decimal-noun/calso-separated.wikitext"), &[_]usize{ 2, 3, 5, 7, 9 } },
    };
    inline for (cases) |case| {
        var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
        const root = try tmp.dir.realPathFileAlloc(io, ".", a);
        const output = try std.fs.path.join(a, &.{root, "output"});
        var writer = try encoder.blob_builder.Writer.init(io, a, output); defer writer.deinit(); writer.language_codes = codes;
        // Exact original noun-body excerpts plus the literal authenticated
        // provider output. This is source instantiation, not a saved expansion.
        try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, case[0], case[1], case[1], null);
        const stats = try writer.finish(codes);
        try std.testing.expectEqual(@as(usize, 1), stats.language_records);
        var filename: [encoder.blob_catalog.language_blob_filename_len]u8 = undefined;
        const path = try std.fs.path.join(a, &.{output, encoder.blob_catalog.language_directory, encoder.blob_catalog.languageBlobFilename("aragonés", &filename)});
        var mapped = try mmapPath(io, path); defer mapped.deinit(); const blob = try encoder.blob_format.inspect(mapped.bytes); const metadata = try blob.languageMetadata();
        try std.testing.expectEqualStrings("an", metadata.code);
        var index = try blob.buildTrustedIndexAlloc(a); defer index.deinit(a); const record = (try index.find(case[0])).?;
        const decoded = try encoder.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, metadata);
        var unowned_report: encoder.presentation_document.Fallbacks = .{};
        const unowned_bytes = try encoder.presentation_document.compileReportedWithLinkTrailAlloc(a, case[0], .language, "aragonés", "an", case[1], null, .{}, &ns, &unowned_report);
        const unowned = try encoder.presentation_codec.decodeAlloc(a, unowned_bytes, case[0], .language, metadata);
        for (unowned.entry.organization.lexemes) |lexeme| try std.testing.expectEqual(@as(usize, 0), lexeme.definitions.len);
        try std.testing.expectEqualDeep(unowned.entry.media, decoded.entry.media);
        try std.testing.expectEqualDeep(unowned.entry.references, decoded.entry.references);
        const additional: usize = if (std.mem.eql(u8, case[0], "chirmán")) 0 else 1;
        try std.testing.expectEqual(unowned.entry.sections[1].blocks.len + additional, decoded.entry.sections[1].blocks.len);
        // An independently separated source oracle exercises the unchanged
        // paragraph compiler without any declared-owner capability or projection.
        var report: encoder.presentation_document.Fallbacks = .{};
        const baseline = try encoder.presentation_document.compileReportedWithLinkTrailAlloc(a, case[0], .language, "aragonés", "an", case[2], null, .{}, &ns, &report);
        var expected = try encoder.presentation_codec.decodeAlloc(a, baseline, case[0], .language, metadata);
        for (expected.entry.organization.lexemes) |lexeme| try std.testing.expectEqual(@as(usize, 0), lexeme.definitions.len);
        try std.testing.expectEqual(@as(usize, 1), decoded.entry.organization.lexemes.len);
        const lexeme = decoded.entry.organization.lexemes[0];
        try std.testing.expectEqualStrings("Noun", lexeme.kind); try std.testing.expectEqual(@as(usize, 1), lexeme.section);
        try std.testing.expectEqual(case[3].len, lexeme.definitions.len);
        for (case[3], lexeme.definitions) |block, sense| {
            try std.testing.expectEqual(block, sense.block);
            try std.testing.expectEqual(encoder.presentation_types.BlockKind.paragraph, decoded.entry.sections[1].blocks[block].kind);
        }
        expected.entry.organization = decoded.entry.organization;
        try std.testing.expectEqualDeep(expected, decoded);
        const encoded = try encoder.presentation_codec.encodeAlloc(a, decoded);
        try std.testing.expectEqualDeep(decoded, try encoder.presentation_codec.decodeAlloc(a, encoded, case[0], .language, metadata));
        try std.testing.expectEqualSlices(u8, encoded, try encoder.presentation_codec.encodeAlloc(a, expected));
    }
}

const TnMissingEqualsTest = struct {
    const T = encoder.presentation_types;
    fn install(io: std.Io, a: std.mem.Allocator, root: []const u8, providers: bool) !void {
        try DvShyOwnerTest.file(io, a, root, "manifest.jsonl", "");
        try DvShyOwnerTest.file(io, a, root, "language-registry.tsv", @embedFile("testdata/tn-project-equals/language-registry.tsv"));
        const rows = [_]struct { code: []const u8, page: u64, revision: u64, xml: []const u8 }{
            .{ .code = "en", .page = 1983, .revision = 6508, .xml = @embedFile("testdata/tn-missing-equals/en-provider.xmltext") },
            .{ .code = "pt", .page = 2668, .revision = 6514, .xml = @embedFile("testdata/tn-missing-equals/pt-provider.xmltext") },
        };
        var index: std.ArrayList(u8) = .empty;
        for (rows) |row| try index.appendSlice(a, try std.fmt.allocPrint(a,
            "0\t0\tTempolete:{s}\t\t{d}\t{d}\t2026-10-01T00:00:00Z\tA\twikitext\t10\t1\t1\n",
            .{ if (providers) try std.fmt.allocPrint(a, "={s}=", .{row.code}) else row.code, row.page, row.revision }));
        try DvShyOwnerTest.file(io, a, root, "page-index.tsv", index.items);
        var templates = try dump_source.TemplateSourceWriter.init(io, a, root); defer templates.deinit();
        for (rows, 0..) |row, i| try templates.append(i, row.page, row.revision, row.xml);
        try templates.finish(try std.fs.path.join(a, &.{root, "page-index.tsv"}));
    }
    fn roundtrip(a: std.mem.Allocator, entry: T.Entry) !void {
        const stored: T.Stored = .{ .entry = entry }; const bytes = try encoder.presentation_codec.encodeAlloc(a, stored);
        const decoded = try encoder.presentation_codec.decodeAlloc(a, bytes, entry.title, .language, .{ .heading = entry.language.?, .code = entry.language_code });
        try std.testing.expectEqualDeep(stored, decoded);
        try std.testing.expectEqualSlices(u8, bytes, try encoder.presentation_codec.encodeAlloc(a, decoded));
    }
    fn currentBaseline(a: std.mem.Allocator, before: T.Entry, count: usize) !T.Entry {
        // Same narrowly observed numeric-basis transition as the earned TN
        // courant control. Assert every marker before changing just this field.
        var current = before; const sections = try a.dupe(T.Section, before.sections); current.sections = sections;
        var changed: usize = 0;
        for (sections) |*section| {
            const blocks = try a.dupe(T.Block, section.blocks); section.blocks = blocks;
            for (blocks) |*block| {
                const spans = try a.dupe(T.Span, block.spans); block.spans = spans;
                for (spans) |*span| if (std.mem.eql(u8, span.text, "f")) {
                    try std.testing.expect(block.kind == .paragraph and span.kind == .text and span.target.len == 0);
                    try std.testing.expect(span.bold and span.italic and !span.small);
                    try std.testing.expectEqualStrings("#008000", span.foreground.?);
                    try std.testing.expectEqual(T.FontScaleBasis.context, span.font_scale_basis);
                    try std.testing.expectApproxEqAbs(@as(f32, 1.0 / 1.2), span.font_scale.?, 0.000001);
                    span.font_scale_basis = .normal_body; changed += 1;
                };
            }
        }
        try std.testing.expectEqual(count, changed);
        return current;
    }
};

test "TN genuine lua and color retain missing template regions separately from Portuguese and English" {
    const F = TnMissingEqualsTest; const T = F.T;
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator(); const io = std.testing.io;
    for ([_]struct { title: []const u8, raw: []const u8, source: []const u8, phase: []const u8, reader: []const u8, code: []const u8, markers: usize }{
        .{ .title = "lua", .raw = @embedFile("testdata/tn-missing-equals/lua-raw.wikitext"), .source = @embedFile("testdata/tn-missing-equals/lua-static.wikitext"), .phase = @embedFile("testdata/tn-missing-equals/lua-phase.json"), .reader = @embedFile("testdata/tn-missing-equals/lua-reader.json"), .code = "pt", .markers = 2 },
        .{ .title = "color", .raw = @embedFile("testdata/tn-missing-equals/color-raw.wikitext"), .source = @embedFile("testdata/tn-missing-equals/color-static.wikitext"), .phase = @embedFile("testdata/tn-missing-equals/color-phase.json"), .reader = @embedFile("testdata/tn-missing-equals/color-reader.json"), .code = "en", .markers = 3 },
    }) |f| {
        const saved = try std.json.parseFromSlice(struct { entries: []const T.Entry }, a, f.reader, .{ .ignore_unknown_fields = true });
        try std.testing.expectEqual(@as(usize, 1), saved.value.entries.len); const before = saved.value.entries[0];
        try std.testing.expectEqualStrings(f.title, before.title);
        try std.testing.expectEqualStrings("", before.language_code);
        try std.testing.expectEqual(@as(usize, 0), before.references.len);
        try std.testing.expectEqual(@as(usize, 0), before.media.len);
        try F.roundtrip(a, before);
        const expected_whole = try F.currentBaseline(a, before, f.markers);
        const lua = std.mem.eql(u8, f.title, "lua");
        try std.testing.expectEqual(@as(usize, if (lua) 2 else 1), before.sections.len);
        if (lua) {
            try std.testing.expectEqual(@as(usize, 2), before.sections[0].blocks.len);
            try std.testing.expectEqual(@as(usize, 3), before.sections[1].blocks.len);
        } else try std.testing.expectEqual(@as(usize, 9), before.sections[0].blocks.len);
        for ([_]enum { complete, no_phase, no_provider }{ .complete, .no_phase, .no_provider }) |mode| {
            var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}", .{tmp.sub_path});
            try F.install(io, a, root, mode != .no_provider);
            var ns = try namespace_registry.Registry.init(a, @embedFile("testdata/tn-project-equals/namespace-registry.tsv")); defer ns.deinit();
            var registry = try loadLanguageRegistry(io, a, root, &ns); defer registry.deinit(); const codes = languageCodes(&registry, &ns);
            var report: encoder.presentation_document.Fallbacks = .{};
            // Explicit static provider instantiation, independently checked
            // against the complete real Reader. The phase fixture exercises
            // normal API custody; it is not a claimed historical phase capture.
            const baseline_bytes = try encoder.presentation_document.compileReportedWithLinkTrailAlloc(a, f.title, .language, "Unclassified", "", f.source, null, .{}, &ns, &report);
            const baseline = (try encoder.presentation_codec.decodeAlloc(a, baseline_bytes, f.title, .language, .{ .heading = "Unclassified", .code = "" })).entry;
            try std.testing.expectEqualDeep(expected_whole, baseline);
            const output = try std.fs.path.join(a, &.{root, "blobs"});
            var writer = try encoder.blob_builder.Writer.init(io, a, output); defer writer.deinit(); writer.language_codes = codes;
            try writer.addExpandedPageWithReasonsAndPhases(a, .{ .id = 0, .kind = .language }, f.title, f.source, f.raw, null, &.{}, null, if (mode == .no_phase) null else f.phase);
            const stats = try writer.finish(codes);
            if (mode != .complete) {
                try std.testing.expectEqual(@as(usize, 1), stats.language_records);
                const actual = try GaHtmlLanguageBoundaryFixture.requiredEntry(io, a, output, "Unclassified", f.title);
                try std.testing.expectEqualDeep(expected_whole, actual);
                try F.roundtrip(a, actual);
                continue;
            }
            try std.testing.expectEqual(@as(usize, 2), stats.language_records);
            const owner = registry.resolve(f.code).?;
            const owned = try GaHtmlLanguageBoundaryFixture.requiredEntry(io, a, output, owner.heading, f.title);
            const unknown = try GaHtmlLanguageBoundaryFixture.requiredEntry(io, a, output, "Unclassified", f.title);
            var expected_owned = expected_whole; expected_owned.language = owner.heading; expected_owned.language_code = f.code;
            var expected_unknown = expected_whole;
            if (lua) {
                expected_owned.sections = expected_whole.sections[1..2];
                expected_unknown.sections = expected_whole.sections[0..1];
            } else {
                const owned_section = try a.dupe(T.Section, expected_whole.sections);
                owned_section[0].blocks = expected_whole.sections[0].blocks[0..3]; expected_owned.sections = owned_section;
                expected_unknown.sections = try a.dupe(T.Section, &.{.{ .level = 2, .title = "Unclassified", .blocks = expected_whole.sections[0].blocks[3..] }});
            }
            expected_owned.organization = .{ .lexemes = &.{}, .other_sections = &.{0} };
            expected_unknown.organization = .{ .lexemes = &.{}, .other_sections = &.{0} };
            try std.testing.expectEqualDeep(expected_owned, owned);
            try std.testing.expectEqualDeep(expected_unknown, unknown);
            try F.roundtrip(a, owned); try F.roundtrip(a, unknown);
            // Rejoin the actual typed blocks to prove complete source coverage.
            if (lua) {
                try std.testing.expectEqualDeep(expected_whole.sections[0], unknown.sections[0]);
                try std.testing.expectEqualDeep(expected_whole.sections[1], owned.sections[0]);
            } else {
                var blocks: std.ArrayList(T.Block) = .empty;
                try blocks.appendSlice(a, owned.sections[0].blocks); try blocks.appendSlice(a, unknown.sections[0].blocks);
                try std.testing.expectEqualDeep(expected_whole.sections[0].blocks, blocks.items);
            }
        }
        // Restore only the asserted basis fields and recover the entire old
        // reader value, including every link, style, body and organization.
        for (@constCast(expected_whole.sections)) |*section| for (@constCast(section.blocks)) |*block| for (@constCast(block.spans)) |*span| {
            if (std.mem.eql(u8, span.text, "f")) span.font_scale_basis = .context;
        };
        try std.testing.expectEqualDeep(before, expected_whole);
    }
}

