test "SS d191 complete defaults and 194 captured Figure facts load through normal source roles" {
    const a = std.testing.allocator; const io = std.testing.io;
    var arena = std.heap.ArenaAllocator.init(a); defer arena.deinit(); const temp = arena.allocator();
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    const root = try tmp.dir.realPathFileAlloc(io, ".", temp);
    const ns_bytes = @embedFile("testdata/d191-consumer/ss-namespace.tsv");
    const defaults_bytes = @embedFile("testdata/d191-consumer/ss-defaults.json");
    try tmp.dir.writeFile(io, .{ .sub_path = "namespace-registry.tsv", .data = ns_bytes });
    try tmp.dir.writeFile(io, .{ .sub_path = "figure-siteinfo.raw.json", .data = defaults_bytes });
    var ns = try namespace_registry.Registry.init(a, ns_bytes); defer ns.deinit();
    const core = "d1919ec5e4ebd7b0dea1ff6ea1cb4347a9349ca2";
    const main_page = try parseSiteMainPage(temp, defaults_bytes, &ns);
    try std.testing.expectEqualStrings(core, main_page.figure_core_revision orelse return error.TestUnexpectedResult);
    const site = (try loadFigureSite(io, temp, root, &ns)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(core, site.core_revision);
    try std.testing.expectEqual(@as(?u32, 250), site.source_context.defaults.default_thumbnail_width);
    try std.testing.expect(!site.source_context.defaults.rtl);
    try std.testing.expect(site.source_context.missing_media_profile == null);
    try std.testing.expect(ns.figure_source_defaults == null);
    try std.testing.expect(ns.manual_conversion_context == null);
    try std.testing.expect(ns.language_conversion == null);
    const Slice = struct {
        bytes: []const u8,
        fn readAt(context: *anyopaque, out: []u8, offset: u64) !usize {
            const self: *@This() = @ptrCast(@alignCast(context));
            if (offset >= self.bytes.len) return 0;
            const start: usize = @intCast(offset); const n = @min(out.len, self.bytes.len - start, 181);
            @memcpy(out[0..n], self.bytes[start..][0..n]); return n;
        }
        fn input(self: *@This()) figure_sizing.StreamInput { return .{ .context = self, .read_at = readAt, .size = self.bytes.len }; }
    };
    var p = Slice{ .bytes = @embedFile("testdata/d191-consumer/ss-projection.json") };
    var r = Slice{ .bytes = @embedFile("testdata/d191-consumer/ss-raw.json") };
    var projection = p.input(); var raw = r.input();
    var figures = try figure_sizing.Registry.initStream(a, &projection, &raw,
        @embedFile("testdata/d191-consumer/ss-site.json"), &ns, site.core_revision);
    defer figures.deinit();
    try std.testing.expect(projection.digest != null and raw.digest != null);
    try std.testing.expectEqual(@as(usize, 190), figures.records.len);
    try std.testing.expectEqual(@as(u32, 1), figures.missing_files.count());
    for (figures.records) |record| {
        try std.testing.expectEqual(@as(?encoder.presentation_types.FigureSizingPolicy, .requested_fit),
            try figure_sizing.Registry.resolve(&figures, a, record.canonical_file, .thumbnail, @min(record.original_width, 180), null));
    }
    // Unknown source and foreign language remain unsupported through the actual loader.
    for (0..2) |mode| {
        var value = try std.json.parseFromSliceLeaky(std.json.Value, temp, defaults_bytes, .{ .allocate = .alloc_always });
        const general = value.object.getPtr("query").?.object.getPtr("general").?;
        try general.object.put(temp, if (mode == 0) "git-hash" else "lang",
            .{ .string = if (mode == 0) "0000000000000000000000000000000000000000" else "et" });
        try tmp.dir.writeFile(io, .{ .sub_path = "figure-siteinfo.raw.json", .data = try std.json.Stringify.valueAlloc(temp, value, .{}) });
        if (mode == 0) try std.testing.expectError(error.InvalidFigureSizingSource, loadFigureSite(io, temp, root, &ns))
        else try std.testing.expectError(error.InvalidLanguageConversionProfile, loadFigureSite(io, temp, root, &ns));
        try std.testing.expect(ns.figure_source_defaults == null);
        try std.testing.expect(ns.manual_conversion_context == null);
        try std.testing.expect(ns.language_conversion == null);
    }
}

const YiCategoryHeadingTest = struct {
    const namespace_source = @embedFile("testdata/yi-source-category/namespace-registry.tsv");
    const registry_source = @embedFile("testdata/yi-source-category/language-registry.tsv");
    const categories = [3][]const u8{ @embedFile("testdata/yi-source-category/tr.wikitext"), @embedFile("testdata/yi-source-category/tr-.wikitext"), @embedFile("testdata/yi-source-category/tr--.wikitext") };
    const providers = [2][]const u8{ @embedFile("testdata/yi-source-category/interwiktionary.wikitext"), @embedFile("testdata/yi-source-category/interwiki.wikitext") };
    const label = "טערקיש";
};

test "Yiddish category heading derives only from three agreeing source declarations and exact providers" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = YiCategoryHeadingTest;
    var ns = try namespace_registry.Registry.init(a, F.namespace_source); defer ns.deinit();
    var registry = language_registry.Registry.empty(a); defer registry.deinit(); try registry.addTsv(F.registry_source);
    try std.testing.expect(registry.resolveTrusted(F.label) == null);
    try std.testing.expectEqualStrings(F.label, source_category_language.yiddishCategoryHeading(F.categories, F.providers, &ns, &registry).?);
    for ([_][]const u8{
        "{{interwiktionary|CODE=fr|LANGUAGE=טערקיש}}{{interwiki|CODE=fr|LANGUAGE=טערקיש}}",
        "{{interwiktionary|CODE=tr|LANGUAGE=Other}}{{interwiki|CODE=tr|LANGUAGE=Other}}",
        "{{interwiktionary|CODE=tr|LANGUAGE=טערקיש}}",
        "<!--{{interwiktionary|CODE=tr|LANGUAGE=טערקיש}}-->{{interwiki|CODE=tr|LANGUAGE=טערקיש}}",
        "<nowiki>{{interwiktionary|CODE=tr|LANGUAGE=טערקיש}}</nowiki>{{interwiki|CODE=tr|LANGUAGE=טערקיש}}",
        "{{interwiktionary|CODE=tr|CODE=tr|LANGUAGE=טערקיש}}{{interwiki|CODE=tr|LANGUAGE=טערקיש}}",
        "{{interwiktionary|CODE=tr|LANGUAGE=טערקיש|other=1}}{{interwiki|CODE=tr|LANGUAGE=טערקיש}}",
        "{{interwiktionary|CODE=tr|LANGUAGE={{unknown}}}}{{interwiki|CODE=tr|LANGUAGE=טערקיש}}",
        "{{interwiktionary|CODE=tr|LANGUAGE=טערקיש}}{{interwiki|CODE=tr|LANGUAGE=טערקיש}}{{unknown}}",
        "{{interwiktionary|CODE=tr|LANGUAGE=טערקיש}}{{interwiki|CODE=tr|LANGUAGE=טערקיש}}{{interwiki|CODE=tr|LANGUAGE=טערקיש}}",
        "{{interwiktionary|CODE=tr|LANGUAGE=טערקיש}}{{interwiki|CODE=tr|LANGUAGE=טערקיש}}{{מוסטער:interwiki|CODE=fr|LANGUAGE=Other}}",
        "{{interwiktionary|CODE=tr|LANGUAGE=טערקיש}}{{interwiki|CODE=tr|LANGUAGE=טערקיש}}{{Template:interwiki|CODE=fr|LANGUAGE=Other}}",
        "[[target|{{interwiki|CODE=fr|LANGUAGE=Other}}]]{{interwiktionary|CODE=tr|LANGUAGE=טערקיש}}{{interwiki|CODE=tr|LANGUAGE=טערקיש}}",
        "<span title=\"{{interwiki|CODE=fr|LANGUAGE=Other}}\">label</span>{{interwiktionary|CODE=tr|LANGUAGE=טערקיש}}{{interwiki|CODE=tr|LANGUAGE=טערקיש}}",
    }) |bad| {
        var categories = F.categories; categories[1] = bad;
        try std.testing.expect(source_category_language.yiddishCategoryHeading(categories, F.providers, &ns, &registry) == null);
    }
    var providers = F.providers; providers[0] = "[[:{{{LANGUAGE}}}:|{{{CODE}}}]]";
    try std.testing.expect(source_category_language.yiddishCategoryHeading(F.categories, providers, &ns, &registry) == null);
    var foreign = ns; foreign.wiki = "otherwiktionary";
    try std.testing.expect(source_category_language.yiddishCategoryHeading(F.categories, F.providers, &foreign, &registry) == null);
    var absent = language_registry.Registry.empty(a); defer absent.deinit(); try absent.addTsv("# content-language\tyi\n# mediawiki\nyi\tYiddish\nfr\tFrench\n");
    try std.testing.expect(source_category_language.yiddishCategoryHeading(F.categories, F.providers, &ns, &absent) == null);
    try registry.addLocalAlias(F.label, "fr");
    try std.testing.expect(source_category_language.yiddishCategoryHeading(F.categories, F.providers, &ns, &registry) == null);
}

test "Yiddish indexed category heading preserves Writer body links codec and mixed owners" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator(); const io = std.testing.io;
    const F = YiCategoryHeadingTest;
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    const root = try tmp.dir.realPathFileAlloc(io, ".", a);
    var ns = try namespace_registry.Registry.init(a, F.namespace_source); defer ns.deinit();
    var registry = language_registry.Registry.empty(a); defer registry.deinit(); try registry.addTsv(F.registry_source);
    const original_heading = registry.headings.get("tr").?;
    var fixture: TeCategoryFixture = .{ .a = a };
    const category_ns = ns.byId(14).?; const template_ns = ns.byId(10).?;
    for ([_][]const u8{ "tr", "tr-", "tr--" }, F.categories) |name, source|
        try fixture.page(try std.fmt.allocPrint(a, "{s}:{s}", .{ category_ns.name, name }), 14, source, "wikitext");
    for ([_][]const u8{ "interwiktionary", "interwiki" }, F.providers) |name, source|
        try fixture.page(try std.fmt.allocPrint(a, "{s}:{s}", .{ template_ns.name, name }), 10, source, "wikitext");
    const input_path = try std.fs.path.join(a, &.{ root, "input.xml" });
    const index_path = try std.fs.path.join(a, &.{ root, "page-index.tsv" });
    const title_path = try std.fs.path.join(a, &.{ root, dump_source.page_title_index_filename });
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = input_path, .data = fixture.source.items });
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = index_path, .data = fixture.index.items });
    try dump_source.buildPageTitleIndex(io, a, index_path, title_path);
    var page_index = try mmapPath(io, index_path); defer page_index.deinit();
    var title_storage = try mmapPath(io, title_path); defer title_storage.deinit();
    const titles = try dump_source.PageTitleIndex.init(title_storage.bytes);
    var reader = try dump_source.SourceReader.open(io, a, a, input_path, .raw_xml, null); defer reader.deinit();
    var proof: source_category_language.Context = .{ .allocator = a, .registry = &registry, .namespace_catalog = &ns, .source = &reader, .page_index = page_index.bytes, .title_index = titles };
    var wrong = proof; wrong.title_index.page_index_size += 1;
    try std.testing.expectError(error.PageTitleIndexMismatch, wrong.installYiddishCategoryHeading(&registry));
    try std.testing.expect(registry.resolveTrusted(F.label) == null);
    try proof.installYiddishCategoryHeading(&registry);
    try proof.installYiddishCategoryHeading(&registry);
    const owner = registry.resolveTrusted(F.label) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("tr", owner.code);
    try std.testing.expectEqualStrings(original_heading, registry.headings.get("tr").?);
    try std.testing.expectEqualStrings(original_heading, owner.heading);
    const raw = @embedFile("testdata/yi-source-category/yollamak.wikitext");
    // The focused fixture resolves only PAGENAME; the later ordinary indexed
    // page is the integration check for the actual expansion worker.
    const expanded = try std.mem.replaceOwned(u8, a, raw, "{{PAGENAME}}", "yollamak");
    const english = registry.resolveTrusted(registry.headings.get("en").?).?;
    const mixed_raw = try std.fmt.allocPrint(a, "{s}\n=={s}==\n# [[english-target]]\n", .{ raw, english.heading });
    const mixed_expanded = try std.fmt.allocPrint(a, "{s}\n=={s}==\n# [[english-target]]\n", .{ expanded, english.heading });
    const output = try std.fs.path.join(a, &.{ root, "blobs" });
    var writer = try encoder.blob_builder.Writer.init(io, a, output); defer writer.deinit();
    const codes = languageCodes(&registry, &ns); writer.language_codes = codes;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "yollamak", mixed_expanded, mixed_raw, null);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 2), stats.language_records);
    for ([_]language_registry.Resolved{ owner, english }) |expected| {
        var filename: [encoder.blob_catalog.language_blob_filename_len]u8 = undefined;
        const path = try std.fs.path.join(a, &.{ output, encoder.blob_catalog.language_directory, encoder.blob_catalog.languageBlobFilename(expected.heading, &filename) });
        var mapped = try mmapPath(io, path); defer mapped.deinit();
        const blob = try encoder.blob_format.inspect(mapped.bytes); const metadata = try blob.languageMetadata();
        var index = try blob.buildTrustedIndexAlloc(a); defer index.deinit(a);
        const record = (try index.find("yollamak")) orelse return error.TestUnexpectedResult;
        const stored = try encoder.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, metadata);
        try std.testing.expectEqualStrings(expected.code, stored.entry.language_code);
        try std.testing.expectEqualSlices(u8, record.payload, try encoder.presentation_codec.encodeAlloc(a, stored));
        var expected_links: usize = 0; var foreign_links: usize = 0; var local_label = false;
        for (stored.entry.sections) |section| {
            if (std.mem.eql(u8, section.title, F.label)) local_label = true;
            for (section.blocks) |block| for (block.spans) |span| {
            if (span.kind != .link) continue;
            if (std.mem.eql(u8, span.target, if (std.mem.eql(u8, expected.code, "tr")) "שיקן" else "english-target")) expected_links += 1;
            if (std.mem.eql(u8, span.target, if (std.mem.eql(u8, expected.code, "tr")) "english-target" else "שיקן")) foreign_links += 1;
            };
        }
        try std.testing.expectEqual(@as(usize, 1), expected_links);
        try std.testing.expectEqual(@as(usize, 0), foreign_links);
        if (std.mem.eql(u8, expected.code, "tr")) try std.testing.expect(local_label);
    }
}

const StPairedOrthographyTesting = if (@import("builtin").is_test) struct {
    const prefix = "testdata/st-paired-orthography/";
    const cases = .{
        .{ "bosweu", @embedFile("testdata/st-paired-orthography/bosweu.raw.wikitext"), @embedFile("testdata/st-paired-orthography/bosweu.reader.json") },
        .{ "dilotho", @embedFile("testdata/st-paired-orthography/dilotho.raw.wikitext"), @embedFile("testdata/st-paired-orthography/dilotho.reader.json") },
        .{ "toeba", @embedFile("testdata/st-paired-orthography/toeba.raw.wikitext"), @embedFile("testdata/st-paired-orthography/toeba.reader.json") },
        .{ "tsamaile", @embedFile("testdata/st-paired-orthography/tsamaile.raw.wikitext"), @embedFile("testdata/st-paired-orthography/tsamaile.reader.json") },
        .{ "divouto", @embedFile("testdata/st-paired-orthography/divouto.raw.wikitext"), @embedFile("testdata/st-paired-orthography/divouto.reader.json") },
        .{ "livouto", @embedFile("testdata/st-paired-orthography/livouto.raw.wikitext"), @embedFile("testdata/st-paired-orthography/livouto.reader.json") },
        .{ "libouto", @embedFile("testdata/st-paired-orthography/libouto.raw.wikitext"), @embedFile("testdata/st-paired-orthography/libouto.reader.json") },
        .{ "mokorotlo", @embedFile("testdata/st-paired-orthography/mokorotlo.raw.wikitext"), @embedFile("testdata/st-paired-orthography/mokorotlo.reader.json") },
        .{ "mekorotlo", @embedFile("testdata/st-paired-orthography/mekorotlo.raw.wikitext"), @embedFile("testdata/st-paired-orthography/mekorotlo.reader.json") },
    };
    fn entry(io: std.Io, a: std.mem.Allocator, output: []const u8, owner: []const u8, title: []const u8) !?encoder.presentation_types.Entry {
        var filename: [encoder.blob_catalog.language_blob_filename_len]u8 = undefined;
        const path = try std.fs.path.join(a, &.{ output, "languages", encoder.blob_catalog.languageBlobFilename(owner, &filename) });
        const bytes = try std.Io.Dir.cwd().readFileAlloc(io, path, a, .limited(1024 * 1024));
        const blob = try encoder.blob_format.inspect(bytes);
        var index = try blob.buildTrustedIndexAlloc(a); defer index.deinit(a);
        const record = (try index.find(title)) orelse return null;
        const stored = try encoder.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, try blob.languageMetadata());
        try std.testing.expectEqualSlices(u8, record.payload, try encoder.presentation_codec.encodeAlloc(a, stored));
        return stored.entry;
    }
} else struct {};

test "ordinary paired Sesotho cards preserve complete original Reader bodies both spellings styles links and codec" {
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator(); const io = std.testing.io; const F = StPairedOrthographyTesting;
    var ns = try namespace_registry.Registry.init(a, @embedFile("testdata/st-paired-orthography/namespace-registry.tsv")); defer ns.deinit();
    var registry = language_registry.Registry.empty(a); defer registry.deinit();
    try registry.addTsv(@embedFile("testdata/st-paired-orthography/language-registry.tsv"));
    const owner = registry.resolveStrong("Sesotho") orelse registry.resolveTrusted("Sesotho") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("st", owner.code);
    try std.testing.expectEqualStrings("Sesotho", owner.heading);
    const codes = languageCodes(&registry, &ns);
    const output = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/st-cards", .{tmp.sub_path});
    var writer = try encoder.blob_builder.Writer.init(io, a, output); defer writer.deinit(); writer.language_codes = codes;
    inline for (F.cases) |case| try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, case[0], case[1], case[1], null);
    const source = F.cases[0][1];
    const changes = [_][2][]const u8{
        .{ "[[Category:Sesotho]]", "" },
        .{ "[[Category:Sesotho]]", "[[Category:English]]" },
        .{ "'''Sesotho word (Lesotho orthography):''' -soeu", "" },
        .{ "'''English translation:''' ''white'' (adjective)", "" },
        .{ "Sesotho word (Lesotho orthography)", "English word (Lesotho orthography)" },
        .{ "Sesotho word (Lesotho orthography)", "Sesotho word (Other orthography)" },
    };
    for (changes, 0..) |change, i| {
        const altered = try std.mem.replaceOwned(u8, a, source, change[0], change[1]);
        try std.testing.expect(!std.mem.eql(u8, source, altered));
        const title = try std.fmt.allocPrint(a, "negative-{d}", .{i});
        try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, title, altered, altered, null);
    }
    const incidental = try std.mem.concat(a, u8, &.{ "Discussion of a sample card:\n", source });
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "incidental", incidental, incidental, null);
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "category-only", "[[Category:Sesotho]]\nordinary prose", "[[Category:Sesotho]]\nordinary prose", null);
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "expanded-only", source, "unrelated original source", null);
    var no_trust = codes; no_trust.strong_fn = null; no_trust.trusted_fn = null;
    writer.language_codes = no_trust;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "ordinary-alias-only", source, source, null);
    _ = try writer.finish(codes);
    var projected_bare_images: usize = 0;
    inline for (F.cases) |case| {
        const actual = (try F.entry(io, a, output, owner.heading, case[0])) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings("st", actual.language_code);
        const T = encoder.presentation_types;
        const captured = try std.json.parseFromSliceLeaky(struct { entries: []const T.Entry }, a, case[2], .{ .ignore_unknown_fields = true });
        try std.testing.expectEqual(@as(usize, 1), captured.entries.len);
        const before = captured.entries[0];
        try std.testing.expectEqualStrings("", before.language_code);
        try std.testing.expectEqualStrings(case[0], actual.title);
        try std.testing.expectEqualStrings(owner.heading, actual.language.?);
        try std.testing.expectEqual(before.kind, actual.kind);
        try std.testing.expectEqualDeep(before.display_title, actual.display_title);
        try std.testing.expectEqualDeep(before.preamble_spans, actual.preamble_spans);
        try std.testing.expectEqualDeep(before.references, actual.references);
        try std.testing.expectEqualDeep(before.media, actual.media);
        try std.testing.expectEqualDeep(before.redirect, actual.redirect);
        try std.testing.expectEqualDeep(before.alias, actual.alias);
        try std.testing.expectEqualDeep(before.body_adjoining, actual.body_adjoining);
        try std.testing.expectEqualDeep(before.body_typography, actual.body_typography);
        try std.testing.expectEqualDeep(before.organization, actual.organization);
        try std.testing.expectEqual(@as(usize, 0), actual.organization.lexemes.len);
        try std.testing.expectEqual(before.sections.len, actual.sections.len);
        for (before.sections, actual.sections, 0..) |old_section, new_section, section_index| {
            try std.testing.expectEqual(old_section.level, new_section.level);
            try std.testing.expectEqualStrings(old_section.anchor, new_section.anchor);
            try std.testing.expectEqualStrings(old_section.anchor_fallback, new_section.anchor_fallback);
            if (section_index == 0 and std.mem.startsWith(u8, case[1], "[[Image:Katiba.gif]]\n")) {
                // The original capture predates typed images. This bare source has no caption or options.
                try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, case[1], "[[Image:"));
                try std.testing.expectEqual(@as(usize, 1), before.sections.len);
                try std.testing.expect(old_section.blocks.len > 0);
                try std.testing.expect(old_section.blocks[0].spans.len > 0);
                var image_actions: usize = 0;
                for (old_section.blocks) |block| for (block.spans) |span| {
                    if (std.mem.eql(u8, span.target, "File:Katiba.gif")) image_actions += 1;
                };
                try std.testing.expectEqual(@as(usize, 1), image_actions);
                const old_image = old_section.blocks[0].spans[0];
                try std.testing.expectEqual(.link, old_image.kind);
                try std.testing.expectEqualStrings("Image:Katiba.gif", old_image.text);
                try std.testing.expectEqualStrings("File:Katiba.gif", old_image.target);
                try std.testing.expectEqualStrings("wikidict-media wikidict-media-file-4b61746962612e676966", old_image.classes);
                try std.testing.expect(old_image.image == null);
                const expected_blocks = try a.dupe(T.Block, old_section.blocks);
                const expected_spans = try a.dupe(T.Span, old_section.blocks[0].spans);
                expected_spans[0].text = "";
                expected_spans[0].image = .{ .file = "Katiba.gif" };
                expected_blocks[0].spans = expected_spans;
                // Deep equality retains every action/style field, every other span, and the full image defaults.
                try std.testing.expectEqualDeep(expected_blocks, new_section.blocks);
                projected_bare_images += 1;
            } else {
                try std.testing.expectEqualDeep(old_section.blocks, new_section.blocks);
            }
        }
        const payload = try encoder.presentation_document.compileClassifiedWithHeadingAnchorsAlloc(a, case[0], .language,
            owner.heading, owner.code, encoder.presentation_document.MissingText.untracked(case[1]), null, codes.link_trail, &ns, null, null,
            .{}, null, null, &.{}, null, &.{}, .{ .heading = owner.heading, .code = owner.code });
        const reference = try encoder.presentation_codec.decodeAlloc(a, payload, case[0], .language, .{ .code = owner.code, .heading = owner.heading });
        try std.testing.expectEqualDeep(reference.entry, actual);
    }
    try std.testing.expectEqual(@as(usize, 2), projected_bare_images);
    for (changes, 0..) |_, i| {
        const title = try std.fmt.allocPrint(a, "negative-{d}", .{i});
        try std.testing.expect((try F.entry(io, a, output, owner.heading, title)) == null);
        const unknown = (try F.entry(io, a, output, "Unclassified", title)) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings("", unknown.language_code);
    }
    for ([_][]const u8{ "incidental", "category-only", "expanded-only", "ordinary-alias-only" }) |title| {
        try std.testing.expect((try F.entry(io, a, output, owner.heading, title)) == null);
        try std.testing.expectEqualStrings("", ((try F.entry(io, a, output, "Unclassified", title)) orelse return error.TestUnexpectedResult).language_code);
    }
}


